window.PHILO_BANQUE={"version":2,"updated":"2026-10-17","legacyIds":{"platon-persuasion":"platon-convaincre-sans-faire-connaitre","platon-recherche":"platon-apprendre-et-se-ressouvenir","platon-ecriture":"platon-le-silence-de-lecrit","platon-caverne":null,"platon-desir":null,"aristote-bonheur":"aristote-le-bonheur-et-le-loisir","aristote-vertu":"aristote-devenir-juste","aristote-savoir":"aristote-connaitre-la-cause","aristote-discours":null,"aristote-cite":"aristote-lanimal-politique","aristote-art":"aristote-imiter-pour-apprendre","nietzsche-valeurs":"nietzsche-le-ressentiment-et-les-valeurs","nietzsche-verite":"nietzsche-lhypothese-scientifique","nietzsche-perspective":null,"nietzsche-liberte":"nietzsche-se-liberer-et-creer","baudelaire-remords-et-irreparable":"baudelaire-memoire-et-duree","baudelaire-conscience-et-miroir":"baudelaire-rencontre-et-possible","racine-bonheur-et-interet":"racine-pouvoir-et-peur","racine-honneur-et-argent":"racine-separation-et-avenir","racine-aimer-sans-contraindre":"racine-desir-et-fuite"},"entries":[{"id":"platon-savoir-et-croire","code":"P01","author":"Platon","title":"Savoir et croire","work":"Gorgias","locator":"454d","quote":"Savoir et croyance ne sont donc pas la même chose, c’est évident.","notions":["verite","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Être certain d’une idée suffit-il pour la connaître ?"},{"function":"L’affirmation","sentence":"Socrate distingue le fait de croire une proposition et le fait de savoir qu’elle est vraie."},{"function":"Les concepts","sentence":"La croyance est une adhésion qui peut être vraie ou fausse, tandis que le savoir ne peut pas être faux sans cesser d’être un savoir."},{"function":"La raison","sentence":"C’est pourquoi la force de notre conviction ne permet pas, à elle seule, de distinguer la croyance du savoir."},{"function":"L’exemple","sentence":"Un accusateur peut croire sincèrement un homme coupable alors que l’enquête établit son innocence."},{"function":"La portée","sentence":"Il faut donc examiner ce qui justifie une affirmation, sans conclure que toute croyance serait nécessairement fausse."}],"uses":[{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Introduire une distinction","reason":"Distinguer l’adhésion à une proposition de la possession de ses raisons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Être conscient, est-ce savoir ?","function":"Limiter une première réponse","reason":"Être convaincu de quelque chose ne garantit pas qu’on le connaisse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"speaker":"Socrate"},{"id":"platon-convaincre-sans-faire-connaitre","code":"P02","author":"Platon","title":"Convaincre sans faire connaître","work":"Gorgias","locator":"454e–455a","quote":"La rhétorique est donc, semble-t-il, productrice de conviction ; elle fait croire que le juste et l’injuste sont ceci et cela, mais elle ne les fait pas connaître.","notions":["langage","justice","verite"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Un discours qui convainc fait-il nécessairement connaître la vérité ?"},{"function":"L’affirmation","sentence":"Socrate affirme que la rhétorique peut faire adopter un jugement sur le juste sans en donner la connaissance."},{"function":"Les concepts","sentence":"Produire une conviction signifie obtenir l’accord de l’auditeur, tandis que faire connaître exige de lui permettre de comprendre pourquoi le jugement est vrai."},{"function":"La raison","sentence":"Dans une assemblée ou un tribunal, l’orateur peut emporter cet accord sans transmettre un savoir à chacun de ceux qui l’écoutent."},{"function":"L’exemple","sentence":"Un jury ému par un plaidoyer peut ainsi approuver une conclusion sans avoir examiné ce qui la justifie."},{"function":"La portée","sentence":"L’efficacité d’une parole ne garantit donc pas sa vérité, même si une parole vraie peut aussi chercher à convaincre."}],"uses":[{"subject":"Bien parler, est-ce bien penser ?","function":"Contester une assimilation","reason":"L’efficacité persuasive ne prouve pas la justesse de la pensée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Comment savoir ce qui est juste ?","function":"Écarter un faux critère","reason":"L’accord produit par un orateur n’établit pas le savoir du juste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Socrate"},{"id":"platon-subir-ou-commettre-linjustice","code":"P03","author":"Platon","title":"Subir ou commettre l’injustice","work":"Gorgias","locator":"469c","quote":"Mais, s’il était nécessaire soit de commettre l’injustice soit de la subir, je choisirais de la subir plutôt que de la commettre.","notions":["justice","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Faut-il préserver sa sécurité au prix d’une injustice ?"},{"function":"L’affirmation","sentence":"Socrate affirme que, s’il devait choisir, il préférerait subir l’injustice plutôt que la commettre."},{"function":"Les concepts","sentence":"Subir l’injustice signifie être victime d’un tort, tandis que la commettre signifie devenir responsable d’une action injuste."},{"function":"La raison","sentence":"Il juge ce second mal plus grave parce qu’il abîme la qualité morale de celui qui agit, au lieu de seulement lui infliger un dommage extérieur."},{"function":"L’exemple","sentence":"Accuser un innocent pour éviter soi-même une peine préserverait peut-être notre sécurité, mais nous rendrait responsables de sa condamnation."},{"function":"La portée","sentence":"La justice de notre conduite vaut donc davantage que l’évitement de toute souffrance, sans que cela oblige à rechercher le malheur."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Fixer une limite morale","reason":"La préservation de soi ne justifie pas n’importe quelle action.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Soutenir une réponse négative","reason":"Souffrir ne rend pas juste l’injustice que l’on commet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-justice-et-bonheur","code":"P04","author":"Platon","title":"Justice et bonheur","work":"Gorgias","locator":"470e","quote":"J’affirme que l’être (homme ou femme) doté d’une bonne nature morale est heureux, mais que l’être injuste et méchant est malheureux.","notions":["bonheur","justice"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"La puissance et la réussite suffisent-elles pour être heureux ?"},{"function":"L’affirmation","sentence":"Socrate soutient qu’une personne juste est heureuse et qu’une personne injuste est malheureuse."},{"function":"Les concepts","sentence":"Il rapporte ainsi le bonheur à la manière dont une personne conduit sa vie, plutôt qu’à la seule quantité de biens dont elle dispose."},{"function":"La raison","sentence":"Une conduite injuste laisse les désirs et les rapports de force gouverner la vie, au lieu de les régler selon ce qui est bon."},{"function":"L’exemple","sentence":"Un dirigeant capable de faire tout ce qui lui plaît peut encore vivre dans la crainte, l’avidité et le désordre."},{"function":"La portée","sentence":"Le succès extérieur ne prouve donc pas le bonheur, mais le lien affirmé entre justice et bonheur demande encore à être défendu."}],"uses":[{"subject":"L’homme injuste peut-il être heureux ?","function":"Défendre une réponse négative","reason":"Distinguer les avantages de l’injuste et le bien de son âme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"La morale peut-elle se définir comme l’art d’être heureux ?","function":"Construire une réponse affirmative","reason":"La justice peut être comprise comme une condition du bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=115","sourceLabel":"Recueil académique · p. 115"}],"speaker":"Socrate"},{"id":"platon-linjustice-ne-justifie-pas-linjustice","code":"P05","author":"Platon","title":"L’injustice ne justifie pas l’injustice","work":"Criton","locator":"49b","quote":"Il s’ensuit que même à l’injustice il ne faut en aucune façon répondre par l’injustice, comme se l’imaginent les gens, dès lors que l’on admet qu’il ne faut jamais commettre l’injustice.","notions":["justice","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une injustice subie rend-elle juste notre vengeance ?"},{"function":"L’affirmation","sentence":"Socrate refuse de répondre à l’injustice par une autre injustice."},{"function":"Les concepts","sentence":"L’injustice désigne ici le tort que l’on fait à autrui, même lorsque cet autre nous a d’abord nui."},{"function":"La raison","sentence":"Si faire injustement du tort est mauvais, le tort subi ne suffit pas à changer la valeur de l’action par laquelle nous ripostons."},{"function":"L’exemple","sentence":"Être victime d’un mensonge n’autorise pas à fabriquer à son tour une fausse accusation."},{"function":"La portée","sentence":"La riposte doit donc rester juste, ce qui permet de distinguer la sanction d’une faute et la vengeance qui reproduit cette faute."}],"uses":[{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Réfuter une justification","reason":"La situation de victime ne supprime pas l’exigence de justice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"Ressentir l’injustice m’apprend-il ce qui est juste ?","function":"Limiter le sentiment comme critère","reason":"Le sentiment d’avoir subi un tort peut encore conduire à faire du tort.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-une-opinion-vraie-peut-guider","code":"P06","author":"Platon","title":"Une opinion vraie peut guider","work":"Ménon","locator":"97b","quote":"Donc, une opinion vraie n’est pas un moins bon guide, pour la rectitude de l’action, que la raison.","notions":["raison","verite","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Faut-il toujours savoir pourquoi une action est correcte pour agir correctement ?"},{"function":"L’affirmation","sentence":"Socrate reconnaît qu’une opinion vraie peut guider une action aussi bien qu’un savoir."},{"function":"Les concepts","sentence":"L’opinion vraie atteint le vrai sans nécessairement pouvoir le justifier, alors que le savoir en possède les raisons."},{"function":"La raison","sentence":"Pour arriver au bon résultat, la vérité de l’indication peut suffire, même lorsque celui qui la donne ne sait pas l’expliquer."},{"function":"L’exemple","sentence":"Dans le dialogue, quelqu’un qui a une opinion vraie du chemin de Larissa peut guider les voyageurs aussi bien que celui qui connaît ce chemin."},{"function":"La portée","sentence":"L’efficacité pratique ne permet donc pas de confondre opinion et savoir, car une opinion vraie reste plus fragile qu’une connaissance justifiée."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Nuancer la nécessité du savoir","reason":"Une action correcte peut être guidée par une opinion vraie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Distinguer vérité et justification","reason":"Une croyance peut être vraie sans que son détenteur sache en rendre raison.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}],"speaker":"Socrate"},{"id":"platon-apprendre-et-se-ressouvenir","code":"P07","author":"Platon","title":"Apprendre et se ressouvenir","work":"Ménon","locator":"81d","quote":"Ainsi, le fait de chercher et le fait d’apprendre sont, au total, une réminiscence.","notions":["raison","science"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment chercher une connaissance que l’on ne possède pas encore ?"},{"function":"L’affirmation","sentence":"Socrate propose de comprendre la recherche et l’apprentissage comme une réminiscence."},{"function":"Les concepts","sentence":"La réminiscence est le retour à une connaissance que l’âme aurait acquise avant sa vie présente."},{"function":"La raison","sentence":"Cette hypothèse permet d’expliquer comment une réponse peut être reconnue comme vraie sans avoir été simplement reçue d’un maître."},{"function":"L’exemple","sentence":"L’interrogation du jeune serviteur dans le Ménon fait apparaître une réponse géométrique à travers ses erreurs et ses rectifications."},{"function":"La portée","sentence":"Apprendre serait donc retrouver par l’examen, mais l’expérience du dialogue ne prouve pas à elle seule l’existence antérieure de l’âme."}],"uses":[{"subject":"D’où viennent nos connaissances ?","function":"Proposer une origine du savoir","reason":"La réminiscence fait dépendre l’apprentissage d’un savoir antérieur de l’âme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"},{"subject":"Être conscient, est-ce savoir ?","function":"Distinguer possession et accès","reason":"Une connaissance supposée présente dans l’âme peut encore demander à être retrouvée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"speaker":"Socrate"},{"id":"platon-pourquoi-les-hommes-sassocient","code":"P08","author":"Platon","title":"Pourquoi les hommes s’associent","work":"La République","locator":"II, 369c","quote":"Dès lors, un homme recourt à un autre pour un besoin particulier, puis à un autre en fonction de tel autre besoin, et parce qu’ils manquent d’une multitude de choses, les hommes se rassemblent nombreux au sein d’une même fondation, s’associant pour s’entraider.","notions":["etat","travail"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Pourquoi les hommes ne vivent-ils pas chacun de leur côté ?"},{"function":"L’affirmation","sentence":"Socrate explique leur association par la diversité de leurs besoins et leur incapacité à les satisfaire seuls."},{"function":"Les concepts","sentence":"L’entraide consiste à recevoir d’autrui ce que l’on ne peut produire soi-même et à lui apporter en retour une autre contribution."},{"function":"La raison","sentence":"Comme chacun manque de plusieurs choses, la coopération et la répartition des activités rendent la vie commune avantageuse."},{"function":"L’exemple","sentence":"Le cultivateur peut fournir la nourriture tandis que le bâtisseur construit les logements dont tous ont besoin."},{"function":"La portée","sentence":"Les besoins expliquent donc une raison de vivre ensemble, sans suffire à déterminer ce qui rend cette communauté juste."}],"uses":[{"subject":"Est-ce la faiblesse qui nous pousse à vivre en société ?","function":"Installer une première réponse","reason":"L’insuffisance de chacun explique le recours à la coopération.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=126","sourceLabel":"Recueil académique · p. 126"},{"subject":"Les hommes ne vivent-ils en société que par intérêt ?","function":"Donner sa part de vérité à l’intérêt","reason":"L’entraide répond aux besoins ; il reste à examiner si elle épuise le sens de la société.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=126","sourceLabel":"Recueil académique · p. 126"}],"speaker":"Socrate"},{"id":"platon-la-justice-et-les-fonctions","code":"P09","author":"Platon","title":"La justice et les fonctions","work":"La République","locator":"IV, 433b","quote":"Et nous avons dit, de plus, que la justice consiste à s’occuper de ses tâches propres et à ne pas se disperser dans des tâches diverses, et cela, nous l’avons souvent entendu dire de plusieurs autres et nous-mêmes l’avons affirmé à plusieurs reprises.","notions":["justice","etat"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Qu’est-ce qui rend juste l’organisation d’une cité ?"},{"function":"L’affirmation","sentence":"Socrate propose que chacun y accomplisse la tâche qui lui revient sans empiéter sur celles des autres."},{"function":"Les concepts","sentence":"La justice est alors un ordre des fonctions, et non seulement le respect de règles dans les échanges entre personnes."},{"function":"La raison","sentence":"La cité fonctionne comme un ensemble dont chaque activité contribue au bien commun lorsqu’elle tient sa place."},{"function":"L’exemple","sentence":"Les gardiens doivent ainsi protéger la cité plutôt qu’utiliser leur pouvoir pour s’approprier le travail des autres."},{"function":"La portée","sentence":"Cette conception exige un accord entre les fonctions, mais laisse à examiner la justice de leur répartition et la possibilité d’en changer."}],"uses":[{"subject":"Comment savoir ce qui est juste ?","function":"Proposer un critère à examiner","reason":"Définir le juste par l’organisation et la répartition des fonctions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"L’État doit-il mettre fin aux injustices ?","function":"Préciser ce que l’État devrait réaliser","reason":"Envisager la justice comme un ordre des fonctions, puis en examiner les limites.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-la-liberte-qui-devient-servitude","code":"P10","author":"Platon","title":"La liberté qui devient servitude","work":"La République","locator":"VIII, 564a","quote":"Une liberté excessive ne peut donc apparemment se muer qu’en une servitude excessive, et cela aussi bien pour l’individu que pour la cité.","notions":["liberte","etat"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une liberté sans aucune limite peut-elle se conserver ?"},{"function":"L’affirmation","sentence":"Socrate soutient que la recherche d’une liberté excessive peut aboutir à une servitude excessive."},{"function":"Les concepts","sentence":"La liberté visée ici est le refus de toute autorité et de toute règle, tandis que la servitude est la soumission à un pouvoir qui ne rencontre plus de limites."},{"function":"La raison","sentence":"Dans l’analyse de Platon, le désordre des désirs et des conflits peut préparer l’appel à un protecteur qui finit par dominer tous les autres."},{"function":"L’exemple","sentence":"Un chef d’abord soutenu contre les puissants peut supprimer ses adversaires puis les garanties de ceux qui l’ont soutenu."},{"function":"La portée","sentence":"La liberté peut donc avoir besoin de limites communes, sans que cela permette de présenter toute démocratie comme une tyrannie en devenir."}],"uses":[{"subject":"L’État est-il le garant de ma liberté ?","function":"Faire apparaître une limite","reason":"L’absence de règle commune peut préparer la domination plutôt que la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"},{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Dépasser une opposition simple","reason":"Certaines contraintes peuvent empêcher la liberté de se détruire elle-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"}],"speaker":"Socrate"},{"id":"platon-le-silence-de-lecrit","code":"P11","author":"Platon","title":"Le silence de l’écrit","work":"Phèdre","locator":"275d","quote":"Car, à mon avis, ce qu’il y a de terrible, Phèdre, c’est la ressemblance qu’entretient l’écriture avec la peinture.","notions":["langage","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Un texte écrit peut-il expliquer lui-même ce que nous ne comprenons pas en lui ?"},{"function":"L’affirmation","sentence":"Socrate compare l’écriture à la peinture parce que l’une et l’autre semblent vivantes sans pouvoir répondre à nos questions."},{"function":"Les concepts","sentence":"La ressemblance porte sur une présence apparente qui laisse pourtant le lecteur ou le spectateur sans réponse nouvelle."},{"function":"La raison","sentence":"Une fois fixé, le discours répète les mêmes signes et ne choisit ni ses lecteurs ni les explications dont ils ont besoin."},{"function":"L’exemple","sentence":"Une définition écrite ne peut pas reconnaître notre erreur de lecture et la corriger comme le ferait un interlocuteur."},{"function":"La portée","sentence":"L’écrit peut soutenir la compréhension, mais sa conservation ne remplace pas le travail vivant de l’explication."}],"uses":[{"subject":"Le langage n’est-il qu’un outil ?","function":"Examiner une limite du support","reason":"Le discours écrit circule sans pouvoir ajuster sa réponse au lecteur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"},{"subject":"Bien parler, est-ce bien penser ?","function":"Introduire l’exigence de justification","reason":"Un discours fixé ne remplace pas l’aptitude vivante à répondre aux objections.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"}],"speaker":"Socrate"},{"id":"platon-linspiration-du-poete","code":"P12","author":"Platon","title":"L’inspiration du poète","work":"Ion","locator":"533e","quote":"En effet, tous les poètes auteurs de vers épiques – je parle des bons poètes – ne sont pas tels par l’effet d’un art, mais c’est inspirés par le dieu et possédés par lui qu’ils profèrent tous ces beaux poèmes.","notions":["art"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment un poète peut-il réussir sans savoir expliquer sa réussite ?"},{"function":"L’affirmation","sentence":"Dans l’Ion, Socrate attribue la puissance des bons poètes à une inspiration divine plutôt qu’à la maîtrise d’un art."},{"function":"Les concepts","sentence":"L’art est ici un savoir réglé dont on peut rendre raison, tandis que l’inspiration fait parler sous l’effet d’une puissance qui nous dépasse."},{"function":"La raison","sentence":"Le dialogue distingue ainsi la force d’une parole poétique et les connaissances que son auteur ou son interprète peut réellement justifier."},{"function":"L’exemple","sentence":"Ion peut émouvoir en récitant Homère sans connaître pour autant la médecine ou la stratégie dont les poèmes parlent."},{"function":"La portée","sentence":"La réussite poétique ne prouve donc pas la possession du savoir correspondant, sans que cela suffise à exclure tout travail du poète."}],"uses":[{"subject":"Faut-il recourir à la notion d’inspiration pour rendre compte de la production artistique ?","function":"Soutenir une hypothèse à discuter","reason":"La beauté produite peut dépasser le savoir explicite de son auteur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’artiste est-il maître de son œuvre ?","function":"Limiter la maîtrise","reason":"Le poète ne commande pas entièrement ce qui fait la valeur de sa production.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"L’artiste sait-il ce qu’il fait ?","function":"II.2 : construire la nouvelle réponse","reason":"L’inspiration permet de distinguer produire une œuvre réussie et savoir expliquer sa production.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-l-artiste-sait-il-ce-qu-il-fait.html","a20Step":"II.2","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}],"speaker":"Socrate"},{"id":"platon-le-dialogue-interieur","code":"P13","author":"Platon","title":"Le dialogue intérieur","work":"Théétète","locator":"189e–190a","quote":"Car voici ce que me semble faire l’âme quand elle pense : rien d’autre que dialoguer, s’interrogeant elle-même et répondant, affirmant et niant.","notions":["conscience","langage","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment pouvons-nous discuter une idée lorsque nous sommes seuls ?"},{"function":"L’affirmation","sentence":"Socrate décrit la pensée comme un dialogue que l’âme entretient avec elle-même."},{"function":"Les concepts","sentence":"Dialoguer signifie ici se poser des questions, avancer des réponses et examiner ce que l’on doit affirmer ou nier."},{"function":"La raison","sentence":"La pensée ne reçoit donc pas seulement des idées, elle les confronte avant de se fixer sur un jugement."},{"function":"L’exemple","sentence":"Avant de tenir une promesse pour obligatoire dans une situation nouvelle, nous pouvons en examiner intérieurement les raisons et les objections."},{"function":"La portée","sentence":"La parole intérieure éclaire ainsi le travail du jugement, sans établir que toute forme de pensée soit un discours prononcé en silence."}],"uses":[{"subject":"Penser, est-ce se parler à soi-même ?","function":"Défendre une analyse du penser","reason":"L’interrogation et la réponse peuvent s’effectuer intérieurement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Peut-on penser sans douter ?","function":"Montrer le rôle de l’examen","reason":"Penser implique de mettre des propositions à l’épreuve avant de trancher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"}],"speaker":"Socrate"},{"id":"platon-le-temps-et-leternite","code":"P14","author":"Platon","title":"Le temps et l’éternité","work":"Timée","locator":"37d","quote":"Le démiurge a donc l’idée de fabriquer une image mobile de l’éternité ; et, tandis qu’il met le ciel en ordre, il fabrique de l’éternité qui reste dans l’unité une certaine image éternelle progressant suivant le nombre, celle-là même que précisément nous appelons le « temps ».","notions":["temps"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment un monde changeant peut-il présenter un ordre durable ?"},{"function":"L’affirmation","sentence":"Le Timée présente le temps comme une image mobile de l’éternité produite avec l’organisation du ciel."},{"function":"Les concepts","sentence":"L’éternité demeure dans l’unité, tandis que le temps se déploie dans une succession réglée par le nombre."},{"function":"La raison","sentence":"Les mouvements célestes permettent de retrouver un ordre dans le changement au lieu de le laisser à une succession sans mesure."},{"function":"L’exemple","sentence":"Le retour des jours, des mois et des années donne ainsi des repères réguliers à ce qui naît et se transforme."},{"function":"La portée","sentence":"L’éternité n’est donc pas un temps qui ne finirait jamais, mais ce dont le temps reproduit l’ordre à travers la succession."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer deux modes d’être","reason":"L’éternité ne désigne pas simplement un temps qui durerait sans fin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Maîtrise-t-on le temps ?","function":"Préciser l’objet de la maîtrise","reason":"Le nombre et l’ordre rendent le temps mesurable sans le rendre disponible à volonté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}],"speaker":"Timée"},{"id":"platon-les-richesses-et-la-vertu","code":"P15","author":"Platon","title":"Les richesses et la vertu","work":"Apologie de Socrate","locator":"30b","quote":"Ce n’est pas des richesses que vient la vertu, mais c’est de la vertu que viennent les richesses et tous les autres biens, pour les particuliers comme pour l’État.","notions":["bonheur","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"La possession de richesses suffit-elle à rendre une vie bonne ?"},{"function":"L’affirmation","sentence":"Socrate donne la priorité à la vertu plutôt qu’à l’acquisition des richesses."},{"function":"Les concepts","sentence":"La vertu est la qualité morale qui règle notre conduite, tandis que les richesses sont des ressources dont la valeur dépend aussi de l’usage."},{"function":"La raison","sentence":"Une possession peut servir une action bonne ou aggraver une conduite injuste, de sorte que son utilité ne garantit pas son bon emploi."},{"function":"L’exemple","sentence":"Une fortune peut permettre d’aider des proches, mais aussi d’acheter des complicités pour nuire à autrui."},{"function":"La portée","sentence":"Il faut donc prendre soin de sa conduite pour faire bon usage des biens, sans promettre que la vertu enrichira toujours celui qui la pratique."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Distinguer possession et bien véritable","reason":"La possession ne suffit pas : il faut examiner le rapport que l’on entretient avec ce que l’on possède.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Définir une condition morale","reason":"Les avantages matériels ne justifient pas le sacrifice de la vertu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"speaker":"Socrate"},{"id":"aristote-le-desir-de-savoir","code":"A01","author":"Aristote","title":"Le désir de savoir","work":"Métaphysique","locator":"A, 1, 980a21","quote":"Tous les humains ont par nature le désir de savoir.","notions":["science","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"La connaissance n’a-t-elle de valeur que lorsqu’elle sert à quelque chose ?"},{"function":"L’affirmation","sentence":"Aristote affirme que le désir de savoir appartient à la nature humaine."},{"function":"Les concepts","sentence":"Ce désir peut porter sur la connaissance elle-même, sans se réduire à la recherche d’un avantage pratique."},{"function":"La raison","sentence":"Aristote en prend pour indice le plaisir des sensations, particulièrement celui de voir, même lorsque nous n’en attendons aucune action utile."},{"function":"L’exemple","sentence":"Nous pouvons ainsi observer les formes d’un paysage par intérêt pour leurs différences, sans vouloir en tirer un produit."},{"function":"La portée","sentence":"La connaissance peut donc valoir pour elle-même, sans que cela rende toute recherche également souhaitable ou prioritaire."}],"uses":[{"subject":"Peut-on désirer savoir pour savoir ?","function":"Soutenir une valeur propre du connaître","reason":"La recherche de connaissance peut être désirée indépendamment de son utilité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Pourquoi désire-t-on savoir ?","function":"Proposer une origine du désir","reason":"Le texte rattache le désir de savoir à la nature humaine et au plaisir de percevoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"La science doit-elle être utile ?","function":"II.1 : introduire une autre exigence","reason":"Le désir de savoir peut donner une valeur propre à la connaissance, distincte de son utilité pratique.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-la-science-doit-elle-etre-utile.html","a20Step":"II.1","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}]},{"id":"aristote-connaitre-la-cause","code":"A02","author":"Aristote","title":"Connaître la cause","work":"Seconds Analytiques","locator":"I, 2, 71b9–12","quote":"Nous pensons connaître scientifiquement chaque chose au sens absolu, et non pas à la manière sophistique par accident, lorsque nous pensons connaître la cause du fait de laquelle la chose est, savoir que c’est bien la cause de la chose et que cette chose ne peut pas être autrement qu’elle n’est.","notions":["science","verite"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Connaître un fait suffit-il pour le comprendre scientifiquement ?"},{"function":"L’affirmation","sentence":"Aristote exige que le savoir scientifique fasse connaître la cause du fait et sa nécessité."},{"function":"Les concepts","sentence":"La cause explique pourquoi la chose est ainsi, tandis que la nécessité signifie qu’elle ne peut pas être autrement dans les conditions considérées."},{"function":"La raison","sentence":"Un constat isolé n’explique pas encore pourquoi le fait se produit et ne donne donc pas à lui seul cette connaissance."},{"function":"L’exemple","sentence":"Voir une éclipse n’équivaut pas à comprendre pourquoi la Terre interposée prive la Lune de lumière."},{"function":"La portée","sentence":"Ce modèle distingue la science du simple constat, mais doit être confronté aux formes de connaissance qui portent sur des faits variables ou probables."}],"uses":[{"subject":"Savoir, est-ce ne rien croire ?","function":"Définir une exigence de connaissance","reason":"La science n’est pas seulement une conviction vraie ; elle doit rendre raison du fait.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Distinguer assentiment et science","reason":"La croyance peut manquer de l’explication causale requise par le savoir scientifique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}]},{"id":"aristote-apprendre-en-faisant","code":"A03","author":"Aristote","title":"Apprendre en faisant","work":"Éthique à Nicomaque","locator":"II, 1, 1103a32–33","quote":"En effet, ce qu’on doit apprendre à faire, c’est en le faisant que nous l’apprenons.","notions":["technique","art"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Comment acquérir une capacité que l’on ne sait pas encore exercer ?"},{"function":"L’affirmation","sentence":"Aristote affirme que certaines activités s’apprennent par leur pratique."},{"function":"Les concepts","sentence":"Apprendre à faire consiste à former une capacité durable, et pas seulement à recevoir une règle."},{"function":"La raison","sentence":"L’exercice transforme progressivement celui qui agit et lui permet de mieux accomplir ce qu’il essaie déjà de faire."},{"function":"L’exemple","sentence":"On apprend à jouer d’un instrument en jouant, en corrigeant ses erreurs et en reprenant les passages difficiles."},{"function":"La portée","sentence":"La pratique est donc formatrice, à condition de ne pas confondre un exercice qui progresse avec la répétition aveugle d’un défaut."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Construire la part de vérité de la pratique","reason":"L’exercice forme des capacités, sans suffire à expliquer toute création.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Installer un acquis à dépasser","reason":"La pratique est nécessaire à une maîtrise, mais ne définit pas seule l’artiste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-devenir-juste","code":"A04","author":"Aristote","title":"Devenir juste","work":"Éthique à Nicomaque","locator":"II, 1, 1103b1–2","quote":"De la même façon, c’est donc aussi en exécutant des actes justes que nous devenons justes, des actes tempérants qu’on devient tempérant et des actes courageux qu’on devient courageux.","notions":["devoir","justice"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Suffit-il de connaître la justice pour devenir juste ?"},{"function":"L’affirmation","sentence":"Aristote affirme que les qualités morales se forment par l’accomplissement des actes correspondants."},{"function":"Les concepts","sentence":"Devenir juste signifie acquérir une disposition stable à choisir et à faire ce qui est juste."},{"function":"La raison","sentence":"Nos actes répétés façonnent nos manières de désirer, de décider et de réagir, comme les exercices façonnent une capacité technique."},{"function":"L’exemple","sentence":"Apprendre à partager équitablement prépare à reconnaître et à choisir l’équité dans des situations nouvelles."},{"function":"La portée","sentence":"La formation morale demande donc des actes, mais une action extérieurement juste ne prouve pas encore que son auteur agisse avec justice et pour de bonnes raisons."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Compléter la connaissance par la formation","reason":"Connaître le bien ne remplace pas l’acquisition d’une disposition à l’accomplir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Le sentiment de la justice est-il naturel ?","function":"Construire la part de l’acquisition","reason":"La conduite juste suppose une formation par les actes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"aristote-le-juste-milieu","code":"A05","author":"Aristote","title":"Le juste milieu","work":"Éthique à Nicomaque","locator":"II, 6, 1106b36–1107a1","quote":"Par conséquent, la vertu est un état décisionnel qui consiste en une moyenne, fixée relativement à nous.","notions":["devoir","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Agir bien consiste-t-il à appliquer partout une quantité identique ?"},{"function":"L’affirmation","sentence":"Aristote définit la vertu comme une disposition à choisir un milieu relatif à celui qui agit."},{"function":"Les concepts","sentence":"Ce milieu évite l’excès et le défaut selon les circonstances, au lieu de partager mécaniquement la distance entre deux extrêmes."},{"function":"La raison","sentence":"Une action réussie doit convenir à la situation et à la personne, ce qui exige un jugement plutôt qu’une recette."},{"function":"L’exemple","sentence":"Le courage évite ainsi la fuite devant tout danger comme l’exposition irréfléchie à n’importe quel risque."},{"function":"La portée","sentence":"La vertu recherche donc ce qui convient, sans signifier que toute action mauvaise pourrait devenir bonne par simple modération."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Préciser le jugement pratique","reason":"La règle doit être appliquée par un choix attentif aux circonstances.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Construire une transformation du désir","reason":"La vertu éduque les affections au lieu de seulement les supprimer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"aristote-deliberer-sur-les-moyens","code":"A06","author":"Aristote","title":"Délibérer sur les moyens","work":"Éthique à Nicomaque","locator":"III, 3, 1112b11–12","quote":"D’autre part, nous ne délibérons pas des fins, mais des moyens pour y parvenir.","notions":["technique","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Que cherchons-nous lorsque nous délibérons sur une action ?"},{"function":"L’affirmation","sentence":"Aristote distingue la fin déjà posée et les moyens que la délibération examine pour l’atteindre."},{"function":"Les concepts","sentence":"La fin est ce que nous voulons obtenir, tandis que les moyens sont les actions susceptibles d’y conduire."},{"function":"La raison","sentence":"Une fois le but fixé, la délibération porte sur ce qui dépend de nous et sur les voies réellement possibles."},{"function":"L’exemple","sentence":"Le médecin qui cherche à guérir compare les traitements adaptés plutôt que de redéfinir la guérison à chaque décision."},{"function":"La portée","sentence":"Choisir des moyens efficaces ne suffit donc pas à justifier une fin, dont la valeur peut demander un autre examen."}],"uses":[{"subject":"Existe-t-il des techniques pour être heureux ?","function":"Distinguer fin et moyens","reason":"Un procédé peut aider à atteindre un but sans établir en quoi consiste le bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"},{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Délimiter la technique","reason":"Savoir exécuter les moyens ne règle pas à soi seul la valeur de la fin artistique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-les-amis-et-les-autres-biens","code":"A07","author":"Aristote","title":"Les amis et les autres biens","work":"Éthique à Nicomaque","locator":"VIII, 1, 1155a5–6","quote":"Sans amis en effet nul ne choisirait de vivre, aurait-il tous les biens qui restent ; car c’est lorsqu’ils sont riches et en possession des formes du pouvoir et de la puissance que les gens éprouvent surtout le besoin d’amis.","notions":["bonheur"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Posséder tous les autres biens rendrait-il l’amitié superflue ?"},{"function":"L’affirmation","sentence":"Aristote affirme que même une vie comblée de richesses et de pouvoir resterait indésirable sans amis."},{"function":"Les concepts","sentence":"L’amitié est une relation dans laquelle on souhaite du bien à l’autre pour lui-même et de manière réciproque."},{"function":"La raison","sentence":"Les biens possédés ne remplacent ni la possibilité de les partager ni celle d’agir avec des personnes auxquelles on tient."},{"function":"L’exemple","sentence":"Une réussite matérielle peut laisser sans personne avec qui se réjouir ou accomplir une action généreuse."},{"function":"La portée","sentence":"L’amitié appartient donc à la vie bonne au lieu de seulement compenser un manque de ressources."}],"uses":[{"subject":"La recherche du bonheur est-elle un idéal égoïste ?","function":"Contester l’autosuffisance solitaire","reason":"La vie bonne inclut un lien avec autrui qui ne se réduit pas à sa possession.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Limiter l’accumulation des biens","reason":"La possession de nombreux biens peut laisser manquer l’amitié.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"aristote-le-bonheur-et-le-loisir","code":"A08","author":"Aristote","title":"Le bonheur et le loisir","work":"Éthique à Nicomaque","locator":"X, 7, 1177b4","quote":"De plus, le bonheur semble impliquer le loisir.","notions":["bonheur","travail"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Être libéré du travail suffit-il pour être heureux ?"},{"function":"L’affirmation","sentence":"Aristote rapporte le bonheur au loisir, c’est-à-dire à une activité choisie pour elle-même."},{"function":"Les concepts","sentence":"Le loisir s’oppose ici à l’occupation imposée par la nécessité, et non à toute activité."},{"function":"La raison","sentence":"Si l’on peine pour obtenir du repos, ce repos doit permettre une manière de vivre qui ait sa valeur propre."},{"function":"L’exemple","sentence":"Étudier une question pour la comprendre peut ainsi donner un sens au temps libéré, au lieu de seulement remplir un vide."},{"function":"La portée","sentence":"Le bonheur ne se réduit donc ni à travailler sans fin ni à ne rien faire, mais demande d’examiner les activités auxquelles la vie peut se consacrer."}],"uses":[{"subject":"Travailler moins, est-ce vivre mieux ?","function":"Distinguer temps libéré et vie bonne","reason":"La réduction de la peine vaut par les activités qu’elle rend possibles.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"},{"subject":"Faut-il travailler pour être heureux ?","function":"Distinguer condition et fin","reason":"Le travail peut préparer les conditions d’une vie qui trouve sa fin ailleurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"}]},{"id":"aristote-lanimal-politique","code":"A09","author":"Aristote","title":"L’animal politique","work":"Les Politiques","locator":"I, 2, 1253a7–8","quote":"Que l’homme soit un animal politique plus que n’importe quelle abeille et que n’importe quel animal grégaire, c’est évident.","notions":["etat","langage"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Pierre Pellegrin (remarque préliminaire, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"La vie politique n’est-elle qu’une façon de se regrouper ?"},{"function":"L’affirmation","sentence":"Aristote affirme que l’être humain est politique dans un sens plus fort que les animaux vivant en groupe."},{"function":"Les concepts","sentence":"La vie politique suppose une communauté capable de discuter ce qui est avantageux, juste ou injuste."},{"function":"La raison","sentence":"Le langage permet de mettre ces évaluations en commun, au-delà de la simple expression du plaisir ou de la douleur."},{"function":"L’exemple","sentence":"Débattre d’une loi commune demande ainsi de donner des raisons sur ce qui doit valoir pour les citoyens."},{"function":"La portée","sentence":"La communauté humaine ne se comprend donc pas seulement par la proximité physique ou l’instinct de regroupement."}],"uses":[{"subject":"Doit-on tout attendre de l’État ?","function":"Fonder le besoin de communauté","reason":"La communauté politique répond à une dimension constitutive de la vie humaine, sans se confondre avec toute sa vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"Le langage des animaux est-il comparable à celui des hommes ?","function":"Introduire une différence de fonction","reason":"L’enjeu politique du langage distingue la communauté humaine du simple grégarisme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"}]},{"id":"aristote-le-langage-et-le-juste","code":"A10","author":"Aristote","title":"Le langage et le juste","work":"Les Politiques","locator":"I, 2, 1253a14–15","quote":"Mais le langage existe en vue de manifester l’avantageux et le nuisible, et par suite aussi le juste et l’injuste.","notions":["langage","justice","etat"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Pierre Pellegrin (remarque préliminaire, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Le langage sert-il seulement à transmettre des sensations ou des informations ?"},{"function":"L’affirmation","sentence":"Aristote lui attribue la capacité de rendre manifestes l’utile, le nuisible, le juste et l’injuste."},{"function":"Les concepts","sentence":"Manifester signifie rendre une évaluation compréhensible et discutable par d’autres personnes."},{"function":"La raison","sentence":"La mise en commun de tels jugements permet aux hommes de former une communauté qui se donne des règles."},{"function":"L’exemple","sentence":"Discuter de la répartition d’une charge publique exige d’expliquer pourquoi une solution serait équitable et pas seulement avantageuse pour soi."},{"function":"La portée","sentence":"Le langage contribue donc à la vie politique, sans garantir que les décisions prises par la parole soient toujours justes."}],"uses":[{"subject":"Faire usage du langage, est-ce renoncer à la violence ?","function":"Construire une alternative à la force","reason":"Discuter publiquement du juste peut remplacer la seule imposition d’un intérêt.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Le langage n’est-il qu’un outil ?","function":"Élargir la fonction du langage","reason":"Le langage participe à la constitution de la communauté politique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-imiter-pour-apprendre","code":"A11","author":"Aristote","title":"Imiter pour apprendre","work":"Poétique","locator":"4, 1448b4–8","quote":"En effet, les êtres humains sont dès leur enfance naturellement enclins à imiter, et cela précisément les distingue des autres animaux : l’homme est l’être le plus enclin à imiter, et il fait ses premiers apprentissages au moyen de l’imitation.","notions":["art","nature"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"L’imitation empêche-t-elle de comprendre et d’apprendre ?"},{"function":"L’affirmation","sentence":"Aristote voit dans l’imitation une tendance humaine naturelle et une origine des premiers apprentissages."},{"function":"Les concepts","sentence":"Imiter consiste à reprendre ou à représenter une action ou une forme, ce qui n’exclut pas d’en comprendre l’organisation."},{"function":"La raison","sentence":"L’enfant apprend en reproduisant des gestes, et le plaisir de reconnaître ce qui est représenté contribue aussi à l’intérêt des œuvres."},{"function":"L’exemple","sentence":"Un dessin peut nous faire reconnaître la posture d’un animal en sélectionnant quelques traits au lieu de tout copier."},{"function":"La portée","sentence":"L’imitation peut donc former la perception et l’intelligence, sans suffire à expliquer à elle seule toute création artistique."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Installer le rôle de l’imitation","reason":"L’imitation forme les premières capacités et ne s’oppose pas d’emblée à l’art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il prendre la nature pour modèle ?","function":"Nuancer l’opposition nature et culture","reason":"L’imitation peut être naturelle à l’être humain sans fixer un modèle unique à reproduire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"aristote-la-connaissance-par-la-fiction","code":"A12","author":"Aristote","title":"La connaissance par la fiction","work":"Poétique","locator":"9, 1451b6–7","quote":"En effet, la poésie raconte les événements davantage dans leur généralité ; l’histoire, les événements dans leur particularité.","notions":["art","verite"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une fiction peut-elle nous apprendre quelque chose sans raconter un fait réel ?"},{"function":"L’affirmation","sentence":"Aristote distingue le récit des faits particuliers et la représentation de ce qui pourrait arriver de manière générale."},{"function":"Les concepts","sentence":"Le général désigne ici des rapports vraisemblables ou nécessaires entre un type de situation, une conduite et ses conséquences."},{"function":"La raison","sentence":"Une intrigue inventée peut faire comprendre ces rapports en les organisant de manière cohérente."},{"function":"L’exemple","sentence":"Une tragédie peut montrer comment une décision aveugle conduit au malheur sans que tous ses personnages aient réellement existé."},{"function":"La portée","sentence":"La connaissance apportée par une œuvre ne se mesure donc pas seulement à l’exactitude historique des événements qu’elle représente."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","function":"Établir un pouvoir de compréhension","reason":"La fiction fait saisir des rapports vraisemblables ou nécessaires entre les actions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il indifférent à la vérité ?","function":"Distinguer vérité et fait réel","reason":"Ne pas raconter un événement réellement arrivé n’implique pas de ne rien faire comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"}]},{"id":"aristote-la-main-et-lintelligence","code":"A13","author":"Aristote","title":"La main et l’intelligence","work":"Les Parties des animaux","locator":"IV, 10, 687a7–10","quote":"Anaxagore dit ainsi que c’est du fait qu’il a des mains que l’être humain est le plus intelligent des animaux, alors qu’il est rationnel que ce soit du fait qu’il est le plus intelligent qu’il soit pourvu de mains.","notions":["technique","nature"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"L’intelligence vient-elle de l’outil ou explique-t-elle la capacité d’en user ?"},{"function":"L’affirmation","sentence":"Aristote refuse la thèse d’Anaxagore qui fait des mains la cause de la supériorité intellectuelle humaine."},{"function":"Les concepts","sentence":"Il distingue la possession d’un instrument et l’aptitude à l’employer de plusieurs manières."},{"function":"La raison","sentence":"Dans son explication, la nature attribue la main à l’être capable de tirer parti de nombreux instruments."},{"function":"L’exemple","sentence":"Posséder une flûte ne donne pas l’art d’en jouer, alors que cet art permet de faire bon usage de l’instrument."},{"function":"La portée","sentence":"La technique suppose donc des capacités d’usage, mais cette explication ne suffit pas à nier que les outils puissent ensuite développer ces capacités."}],"uses":[{"subject":"Y a-t-il de l’intelligence dans les techniques ?","function":"Articuler capacité et instrument","reason":"La main polyvalente rend possible l’exercice de nombreuses techniques, selon une intelligence qui sait en user.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=99","sourceLabel":"Recueil académique · p. 99"},{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Distinguer instrument et aptitude","reason":"La disponibilité de l’instrument ne produit pas à elle seule la capacité d’en user.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-le-temps-et-le-mouvement","code":"A14","author":"Aristote","title":"Le temps et le mouvement","work":"Physique","locator":"IV, 11, 219b1–2","quote":"Car c’est cela le temps : le nombre d’un mouvement selon l’antérieur et le postérieur.","notions":["temps"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Le temps se confond-il avec les changements que nous observons ?"},{"function":"L’affirmation","sentence":"Aristote définit le temps comme ce qui permet de nombrer le mouvement selon l’avant et l’après."},{"function":"Les concepts","sentence":"Le nombre désigne ici l’ordre et la quantité du changement, tandis que l’antérieur et le postérieur distinguent ses moments."},{"function":"La raison","sentence":"Nous reconnaissons un intervalle de temps lorsque nous distinguons des étapes d’un changement et ce qui les sépare."},{"function":"L’exemple","sentence":"Le déplacement régulier d’une aiguille permet de mesurer l’attente d’un événement sans être cet événement lui-même."},{"function":"La portée","sentence":"Le temps se rapporte donc au mouvement sans lui être identique, et sa mesure ne donne pas le pouvoir d’en commander le passage."}],"uses":[{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer mesure et pouvoir","reason":"Mesurer un mouvement ne signifie pas commander son écoulement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"Est-il possible d’échapper au temps ?","function":"Préciser la condition du devenir","reason":"Interroger le rapport entre être soumis au changement et être dans le temps.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"aristote-des-rigueurs-differentes","code":"A15","author":"Aristote","title":"Des rigueurs différentes","work":"Éthique à Nicomaque","locator":"I, 7, 1098a26–29","quote":"Il faut cependant garder aussi en mémoire ce qu’on a dit précédemment, et ne pas réclamer le même genre de rigueur partout.","notions":["raison","science","devoir"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Toute connaissance doit-elle atteindre la précision d’une démonstration mathématique ?"},{"function":"L’affirmation","sentence":"Aristote demande d’ajuster le genre de rigueur à l’objet étudié."},{"function":"Les concepts","sentence":"La rigueur consiste à justifier suffisamment ce que l’on affirme selon la nature du problème."},{"function":"La raison","sentence":"Une matière variable ne permet pas toujours la même exactitude qu’un objet défini par des rapports nécessaires."},{"function":"L’exemple","sentence":"Le géomètre cherche les propriétés de l’angle droit, tandis que le menuisier en cherche une réalisation assez précise pour son travail."},{"function":"La portée","sentence":"Exiger une précision adaptée ne dispense donc pas d’argumenter, mais évite de rendre impossible un jugement en lui demandant une certitude étrangère à son objet."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Distinguer raison pratique et démonstration","reason":"L’incertitude des situations ne supprime pas l’exigence de jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Comment savoir ce qui est juste ?","function":"Délimiter le type de certitude attendu","reason":"La recherche du juste ne se traite pas nécessairement comme un calcul géométrique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}]},{"id":"nietzsche-la-meconnaissance-de-soi","code":"N01","author":"Nietzsche","title":"La méconnaissance de soi","work":"Généalogie de la morale","locator":"Avant-propos, § 1","quote":"Nous ne nous connaissons pas nous-mêmes, nous les hommes de la connaissance, et nous sommes nous-mêmes inconnus à nous-mêmes.","notions":["conscience","inconscient"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel, Ole Hansen-Løve, Théo Leydenbach et Pierre Pénisson","commentary":[{"function":"Le problème","sentence":"La connaissance du monde garantit-elle la connaissance de soi ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que les hommes voués à la connaissance peuvent demeurer étrangers à eux-mêmes."},{"function":"Les concepts","sentence":"Se connaître demande de comprendre ses propres manières de vivre et de vouloir, au-delà du savoir que l’on accumule sur des objets."},{"function":"La raison","sentence":"L’attention portée à ce que nous cherchons peut nous détourner de l’examen de celui qui cherche."},{"function":"L’exemple","sentence":"Un chercheur peut décrire avec précision son domaine sans reconnaître ce qui oriente son ambition ou ses rivalités."},{"function":"La portée","sentence":"La proximité avec soi ne vaut donc pas connaissance immédiate, sans que cela rende tout examen de soi impossible."}],"uses":[{"subject":"Suis-je le mieux placé pour me connaître ?","function":"Contester un privilège immédiat","reason":"La proximité avec soi peut aller de pair avec la méconnaissance de ses propres activités.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Être conscient, est-ce savoir ?","function":"Distinguer expérience de soi et connaissance","reason":"Se vivre soi-même ne suffit pas à se comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"nietzsche-les-interpretations-morales","code":"N02","author":"Nietzsche","title":"Les interprétations morales","work":"Par-delà bien et mal","locator":"§ 108","quote":"Il n’y a pas de phénomènes moraux du tout, mais seulement une interprétation morale de phénomènes…","notions":["devoir","justice"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Le bien et le mal sont-ils des propriétés que l’on constaterait directement dans les faits ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que la qualification morale d’un phénomène relève d’une interprétation."},{"function":"Les concepts","sentence":"Interpréter moralement consiste à rapporter ce qui arrive à des valeurs qui permettent de le louer ou de le condamner."},{"function":"La raison","sentence":"La description d’un geste ne contient pas encore les critères au nom desquels nous le jugeons."},{"function":"L’exemple","sentence":"Garder le silence peut être loué comme de la discrétion ou condamné comme de la lâcheté selon le sens qu’on lui donne."},{"function":"La portée","sentence":"Il faut donc examiner les évaluations à l’œuvre dans un jugement moral, sans conclure que toutes les interprétations ont la même valeur."}],"uses":[{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Mettre en cause l’évidence morale","reason":"Une évaluation intériorisée ne prouve pas sa propre validité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"},{"subject":"Le sentiment de la justice est-il naturel ?","function":"Introduire l’histoire de l’évaluation","reason":"Ce qui paraît immédiatement juste peut résulter d’une interprétation acquise.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"nietzsche-devenir-ce-que-lon-combat","code":"N03","author":"Nietzsche","title":"Devenir ce que l’on combat","work":"Par-delà bien et mal","locator":"§ 146","quote":"Que celui qui lutte avec des monstres veille à ce que cela ne le transforme pas en monstre.","notions":["justice","etat"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Une lutte juste protège-t-elle toujours celui qui la mène de devenir injuste ?"},{"function":"L’affirmation","sentence":"Nietzsche avertit que le combat contre les monstres peut transformer le combattant en monstre."},{"function":"Les concepts","sentence":"Le monstre désigne ici ce dont on combat la violence ou la cruauté, et la transformation touche les pratiques de celui qui s’y oppose."},{"function":"La raison","sentence":"L’habitude d’affronter un adversaire peut faire adopter ses moyens et perdre de vue la fin initiale."},{"function":"L’exemple","sentence":"Un pouvoir qui prétend combattre la terreur peut en venir à imposer lui-même la peur et l’arbitraire."},{"function":"La portée","sentence":"La valeur d’un combat ne dispense donc pas d’examiner ses moyens et leurs effets sur ceux qui les emploient."}],"uses":[{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Limiter les moyens de la riposte","reason":"Combattre un mal ne légitime pas la reproduction de ce mal.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"L’État doit-il préférer l’injustice au désordre ?","function":"Mettre à l’épreuve une justification","reason":"Lutter contre le désordre peut corrompre la fin annoncée si les moyens deviennent injustes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}]},{"id":"nietzsche-les-affects-qui-se-combattent","code":"N04","author":"Nietzsche","title":"Les affects qui se combattent","work":"Par-delà bien et mal","locator":"§ 117","quote":"La volonté de surmonter un affect n’est en dernière instance que la volonté d’un autre ou de plusieurs autres affects.","notions":["conscience","inconscient","liberte"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Lorsque nous maîtrisons un désir, est-ce nécessairement la raison seule qui commande ?"},{"function":"L’affirmation","sentence":"Nietzsche propose de comprendre la domination d’un affect par la force d’autres affects."},{"function":"Les concepts","sentence":"Un affect est une manière de sentir et d’être poussé à agir, comme la peur, la fierté ou l’attachement."},{"function":"La raison","sentence":"La décision de résister peut donc être soutenue par des forces affectives que l’on ne reconnaît pas immédiatement."},{"function":"L’exemple","sentence":"Refuser une satisfaction présente peut tenir au désir plus fort de réussir, de tenir une promesse ou de garder l’estime d’autrui."},{"function":"La portée","sentence":"La maîtrise de soi demande ainsi de comprendre l’organisation de nos désirs, au lieu de supposer une volonté sans aucun mobile affectif."}],"uses":[{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Déplacer l’opposition raison et désir","reason":"Une conduite réglée peut mobiliser et organiser des affects.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Sommes-nous conscients de ce que nous désirons ?","function":"Interroger le motif de la maîtrise","reason":"Le désir de se maîtriser peut lui-même avoir des mobiles affectifs inaperçus.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"nietzsche-le-ressentiment-et-les-valeurs","code":"N05","author":"Nietzsche","title":"Le ressentiment et les valeurs","work":"Généalogie de la morale","locator":"I, § 10","quote":"L’insurrection des esclaves dans la morale commence lorsque le ressentiment lui-même devient créateur et engendre des valeurs : le ressentiment d’êtres tels que la véritable réaction, celle de l’acte, leur est interdite, qui ne s’en sortent indemnes que par une vengeance imaginaire.","notions":["devoir","justice"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel, Ole Hansen-Løve, Théo Leydenbach et Pierre Pénisson","commentary":[{"function":"Le problème","sentence":"Des valeurs morales peuvent-elles naître d’une impossibilité d’agir ?"},{"function":"L’affirmation","sentence":"Nietzsche décrit le ressentiment comme une force capable de créer des valeurs."},{"function":"Les concepts","sentence":"Le ressentiment est une hostilité durable qui, ne pouvant se décharger dans l’action, se transforme en évaluation de l’adversaire."},{"function":"La raison","sentence":"La vengeance devient alors imaginaire, car elle déprécie ce qu’elle ne peut effectivement vaincre."},{"function":"L’exemple","sentence":"Une personne impuissante à rivaliser peut présenter toute réussite adverse comme un vice et sa propre impuissance comme une vertu."},{"function":"La portée","sentence":"Cette analyse invite à interroger l’origine des jugements, sans autoriser à réduire toute demande de justice à du ressentiment."}],"uses":[{"subject":"Ressentir l’injustice m’apprend-il ce qui est juste ?","function":"Distinguer ressentiment et jugement juste","reason":"Un sentiment d’impuissance peut produire une évaluation sans en garantir la justice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Interroger la provenance des valeurs","reason":"L’origine affective d’un jugement peut rester masquée à celui qui le porte.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"}]},{"id":"nietzsche-les-convictions-comme-prisons","code":"N06","author":"Nietzsche","title":"Les convictions comme prisons","work":"L’Antéchrist","locator":"§ 54","quote":"Les convictions sont des prisons.","notions":["liberte","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel","commentary":[{"function":"Le problème","sentence":"Une conviction peut-elle empêcher de penser librement ?"},{"function":"L’affirmation","sentence":"Nietzsche compare les convictions à des prisons lorsqu’elles soumettent le jugement au lieu de le servir."},{"function":"Les concepts","sentence":"La conviction devient enfermement quand une idée est tenue pour intouchable et décide d’avance de ce que l’on acceptera d’examiner."},{"function":"La raison","sentence":"Celui qui en dépend écarte les objections pour préserver sa certitude au lieu de mesurer celle-ci aux objections."},{"function":"L’exemple","sentence":"Une personne persuadée qu’un groupe a toujours tort peut refuser d’entendre même les raisons qu’il avance."},{"function":"La portée","sentence":"La liberté de penser exige donc de pouvoir reprendre ses convictions, sans imposer l’indécision permanente ni l’absence de toute fin."}],"uses":[{"subject":"Croire nous empêche-t-il de chercher la vérité ?","function":"Soutenir une objection au dogmatisme","reason":"Tenir une affirmation pour intouchable ferme l’enquête.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Montrer une servitude intérieure","reason":"L’enfermement peut venir d’une conviction à laquelle on ne s’autorise plus à toucher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"nietzsche-lhypothese-scientifique","code":"N07","author":"Nietzsche","title":"L’hypothèse scientifique","work":"Le Gai Savoir","locator":"§ 344","quote":"Dans la science, les convictions n’ont pas droit de cité, voilà ce que l’on dit à juste titre : c’est seulement lorsqu’elles s’abaissent au rang modeste d’une hypothèse, d’un point de vue expérimental provisoire, d’une fiction régulatrice, que l’on a le droit de leur accorder l’accès au royaume de la connaissance et de leur y reconnaître même une certaine valeur, – toujours avec cette restriction de demeurer soumises à la surveillance policière, à la police de la méfiance.","notions":["science","verite","religion"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Quelle différence sépare une hypothèse scientifique d’une conviction intangible ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme qu’une proposition n’entre dans la science qu’en acceptant d’être tenue pour provisoire et examinable."},{"function":"Les concepts","sentence":"L’hypothèse est une explication proposée à l’épreuve, tandis que la conviction prétend ici soustraire son contenu à la remise en question."},{"function":"La raison","sentence":"La discipline scientifique exige que les raisons de conserver une proposition puissent être discutées et ses insuffisances recherchées."},{"function":"L’exemple","sentence":"Une explication que des observations contraires ne permettraient jamais de corriger serait protégée de l’examen plutôt que soutenue par lui."},{"function":"La portée","sentence":"Le passage distingue ainsi recherche et dogmatisme, avant d’interroger dans la suite du paragraphe la confiance des savants dans la valeur de la vérité."}],"uses":[{"subject":"Croire en la science, est-ce une forme de religion ?","function":"Distinguer méthode et adhésion inconditionnelle","reason":"L’hypothèse scientifique doit rester exposée à la critique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"Savoir, est-ce ne rien croire ?","function":"Nuancer l’opposition","reason":"Une hypothèse est admise provisoirement sans être tenue pour une certitude intangible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}]},{"id":"nietzsche-lart-et-la-lucidite","code":"N08","author":"Nietzsche","title":"L’art et la lucidité","work":"Le Gai Savoir","locator":"§ 107","quote":"Si nous n’avions pas donné notre approbation aux arts et inventé cette espèce de culte du non-vrai : la compréhension de l’universalité du non-vrai et du mensonge que nous offrent à présent les sciences – la compréhension de l’illusion et de l’erreur comme condition de l’existence connaissante et percevante –, nous seraient totalement insupportables.","notions":["art","verite","bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Comment supporter une connaissance qui révèle la part d’illusion dans notre existence ?"},{"function":"L’affirmation","sentence":"Nietzsche attribue à l’art la puissance de rendre cette lucidité vivable."},{"function":"Les concepts","sentence":"L’apparence artistique est une forme que nous savons produite et à laquelle nous pouvons pourtant prendre plaisir."},{"function":"La raison","sentence":"Elle permet de ne pas réduire toute expérience à la seule dénonciation de ses erreurs ou de ses imperfections."},{"function":"L’exemple","sentence":"Une œuvre peut donner forme à une souffrance sans la supprimer ni prétendre qu’elle n’a jamais eu lieu."},{"function":"La portée","sentence":"L’art peut donc soutenir une relation à la vérité, sans se confondre avec un mensonge destiné à tromper autrui."}],"uses":[{"subject":"L’art nous aide-t-il à vivre ?","function":"Défendre une nécessité de l’art","reason":"L’expérience esthétique permet une relation supportable à l’existence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Faire apparaître un coût de la lucidité","reason":"La connaissance peut demander une puissance de mise en forme pour être vécue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"}]},{"id":"nietzsche-donner-forme-a-son-caractere","code":"N09","author":"Nietzsche","title":"Donner forme à son caractère","work":"Le Gai Savoir","locator":"§ 290","quote":"« Donner du style » à son caractère – un art grand et rare !","notions":["conscience","liberte"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Devenir soi-même consiste-t-il seulement à découvrir un caractère déjà fixé ?"},{"function":"L’affirmation","sentence":"Nietzsche présente la mise en forme de son caractère comme un art exigeant."},{"function":"Les concepts","sentence":"Donner du style signifie organiser ses forces et ses faiblesses selon une forme que l’on travaille."},{"function":"La raison","sentence":"Ce travail suppose de reconnaître ses dispositions puis de les exercer, de les transformer ou de leur donner une autre place."},{"function":"L’exemple","sentence":"Une grande sensibilité peut devenir un obstacle si elle nous disperse ou une ressource si un travail d’écriture lui donne une forme."},{"function":"La portée","sentence":"La formation de soi unit donc connaissance et exercice, sans permettre de se fabriquer arbitrairement à partir de rien."}],"uses":[{"subject":"Faut-il apprendre à se connaître soi-même ?","function":"Relier connaissance et formation de soi","reason":"Reconnaître ses forces et ses faiblesses peut permettre de les organiser.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=129","sourceLabel":"Recueil académique · p. 129"},{"subject":"Suis-je le mieux placé pour me connaître ?","function":"Déplacer la connaissance vers une tâche","reason":"Se connaître demande un travail de composition plutôt qu’une simple inspection immédiate.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"nietzsche-se-liberer-et-creer","code":"N10","author":"Nietzsche","title":"Se libérer et créer","work":"Ainsi parlait Zarathoustra","locator":"I, « Des trois métamorphoses »","quote":"Créer des valeurs nouvelles, le lion lui-même n’y est pas encore apte ; mais s’affranchir afin de devenir apte à créer des valeurs nouvelles, voilà ce que peut la force du lion.","notions":["liberte","devoir"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Geneviève Bianquis, traduction revue par Paul Mathias","commentary":[{"function":"Le problème","sentence":"Suffit-il de refuser les valeurs reçues pour devenir capable de créer ?"},{"function":"L’affirmation","sentence":"Zarathoustra distingue la libération accomplie par le lion et la création de valeurs nouvelles."},{"function":"Les concepts","sentence":"Le lion représente la force de dire non à une autorité qui impose ses commandements comme sacrés."},{"function":"La raison","sentence":"Ce refus ouvre une liberté, mais ne fournit pas encore les fins auxquelles elle pourra se consacrer."},{"function":"L’exemple","sentence":"Abandonner une règle imposée ne dit pas encore quel engagement nous voulons prendre ni quelle vie nous voulons construire."},{"function":"La portée","sentence":"La liberté ne s’achève donc pas dans l’opposition, puisque l’affirmation de nouvelles valeurs demande une autre puissance, représentée ensuite par l’enfant."}],"uses":[{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Distinguer refus et création","reason":"Dire non à une obligation peut être une étape sans constituer l’autonomie entière.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Construire une émancipation","reason":"La critique des valeurs reçues ouvre une possibilité, sans fournir à elle seule de nouvelles valeurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"nietzsche-les-limites-de-la-connaissance","code":"N11","author":"Nietzsche","title":"Les limites de la connaissance","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 5","quote":"La sagesse trace des limites, même à la connaissance.","notions":["raison","bonheur","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Faut-il vouloir tout connaître sans jamais interroger ce que cette recherche engage ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que la sagesse peut fixer des limites au désir de connaissance."},{"function":"Les concepts","sentence":"La sagesse désigne ici une manière de conduire sa vie qui ne traite pas tout savoir comme un bien inconditionnel."},{"function":"La raison","sentence":"La recherche doit aussi répondre de ce qu’elle exige de nous et de la place qu’elle prend parmi nos activités."},{"function":"L’exemple","sentence":"Chercher sans fin à connaître chaque jugement d’autrui sur nous peut nourrir l’inquiétude au lieu d’éclairer une décision."},{"function":"La portée","sentence":"Interroger les limites du connaître ne revient donc pas à préférer toute ignorance, mais à juger la valeur d’une recherche déterminée."}],"uses":[{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Interroger la valeur inconditionnelle du savoir","reason":"Il faut aussi examiner ce que l’exigence de savoir engage pour la vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"},{"subject":"Savoir rend-il malheureux ?","function":"Déplacer la question vers l’usage du savoir","reason":"La sagesse peut régler la recherche au lieu d’identifier ignorance et bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}]},{"id":"nietzsche-lepreuve-et-la-force","code":"N12","author":"Nietzsche","title":"L’épreuve et la force","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 8","quote":"Ce qui ne me fait pas mourir me rend plus fort.","notions":["bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Une difficulté doit-elle être jugée seulement d’après la souffrance qu’elle inflige ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme à la première personne qu’une épreuve qui ne le détruit pas peut accroître sa force."},{"function":"Les concepts","sentence":"La force désigne ici une puissance de vivre et de surmonter, et non la simple absence de blessure."},{"function":"La raison","sentence":"Une résistance peut nous obliger à développer des capacités qui ne s’exerceraient pas dans une vie entièrement protégée."},{"function":"L’exemple","sentence":"Un échec peut conduire à reprendre un travail et à mieux comprendre ses exigences."},{"function":"La portée","sentence":"La formule invite ainsi à penser la transformation d’une épreuve, mais ne démontre pas que toute souffrance renforce nécessairement celui qui la subit."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer bonheur et absence d’épreuve","reason":"Une vie peut gagner en puissance en traversant une difficulté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Satisfaire ses désirs peut-il rendre malheureux ?","function":"Contester l’évitement de toute frustration","reason":"Le refus immédiat d’un désir peut avoir une valeur formatrice, sans que toute frustration soit bonne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"nietzsche-le-besoin-de-musique","code":"N13","author":"Nietzsche","title":"Le besoin de musique","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 33","quote":"Sans musique la vie serait une erreur.","notions":["art","bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"La valeur d’une vie se réduit-elle à la satisfaction des besoins indispensables ?"},{"function":"L’affirmation","sentence":"Nietzsche donne à la musique une importance telle qu’une vie qui en serait privée lui paraît manquer son sens."},{"function":"Les concepts","sentence":"L’erreur désigne ici une manière de vivre appauvrie plutôt qu’une proposition intellectuellement fausse."},{"function":"La raison","sentence":"La musique peut donner rythme, intensité et forme à l’expérience, au-delà de ce qui sert seulement à survivre."},{"function":"L’exemple","sentence":"Un chant peut faire éprouver ensemble une joie ou une douleur que la seule description ne ferait pas vivre de la même manière."},{"function":"La portée","sentence":"L’art peut donc appartenir à ce qui rend une existence désirable, sans que chaque œuvre produise le même effet sur chacun."}],"uses":[{"subject":"Avons-nous besoin d’art ?","function":"Défendre un besoin au-delà de la survie","reason":"Une vie humaine ne s’évalue pas seulement à sa conservation matérielle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il un luxe ?","function":"Contester l’idée d’un simple supplément","reason":"La musique peut être comprise comme une composante de la valeur d’une vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"nietzsche-la-raison-et-les-sens","code":"N14","author":"Nietzsche","title":"La raison et les sens","work":"Le Crépuscule des idoles","locator":"« La “raison” dans la philosophie », § 2","quote":"Si nous faussons le témoignage des sens, c’est la « raison » qui en est la cause.","notions":["raison","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Les erreurs viennent-elles toujours des sens plutôt que de nos interprétations ?"},{"function":"L’affirmation","sentence":"Nietzsche accuse certaines constructions de la raison de fausser le témoignage sensible."},{"function":"Les concepts","sentence":"Les sens présentent le changement, tandis que la raison visée ici cherche des choses fixes et identiques derrière ce changement."},{"function":"La raison","sentence":"L’erreur peut donc venir de catégories que nous imposons à l’expérience en les prenant pour la réalité elle-même."},{"function":"L’exemple","sentence":"Nommer une chose peut nous inciter à la croire absolument identique alors même que nous en observons les transformations."},{"function":"La portée","sentence":"La critique demande ainsi d’examiner nos manières d’interpréter, sans déclarer que tout raisonnement serait trompeur."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer la dépendance envers le sensible","reason":"L’interprétation doit répondre de ce qu’elle fait au témoignage des sens.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer perception et interprétation","reason":"L’erreur ne se situe pas nécessairement dans la sensation elle-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"nietzsche-la-grammaire-et-la-metaphysique","code":"N15","author":"Nietzsche","title":"La grammaire et la métaphysique","work":"Le Crépuscule des idoles","locator":"« La “raison” dans la philosophie », § 5","quote":"Je crains bien que nous ne nous débarrassions jamais de Dieu, puisque nous croyons encore à la grammaire…","notions":["langage","religion"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Abandonner une croyance religieuse suffit-il à abandonner les habitudes de pensée qui lui sont liées ?"},{"function":"L’affirmation","sentence":"Nietzsche soutient que certaines croyances métaphysiques peuvent subsister dans notre confiance envers la grammaire."},{"function":"Les concepts","sentence":"Croire à la grammaire signifie ici prendre la structure de nos phrases pour une description nécessaire de la structure du réel."},{"function":"La raison","sentence":"L’habitude de rapporter une action à un sujet peut nous conduire à supposer derrière tout événement un agent ou une substance qui le produirait."},{"function":"L’exemple","sentence":"Dire « je pense » peut ainsi nous faire traiter le « je » comme une réalité déjà connue, alors que la forme de la phrase ne démontre pas son existence comme substance."},{"function":"La portée","sentence":"La critique doit donc examiner les présupposés de nos formulations, au lieu de croire que supprimer le mot « Dieu » libérerait à lui seul la pensée de toute métaphysique."}],"uses":[{"subject":"Le langage déforme-t-il la pensée ?","function":"Interroger une contrainte inaperçue","reason":"La forme grammaticale peut suggérer des êtres ou des causes qu’il reste à justifier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Croire, est-ce renoncer à la raison ?","function":"Déplacer l’opposition croyance et rationalité","reason":"La pensée qui se croit délivrée de la croyance peut en conserver certains présupposés.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Sommes-nous prisonniers du langage ?","function":"I.2 : renforcer la première réponse","reason":"La grammaire peut imposer à notre pensée des catégories que nous n’avons pas explicitement choisies.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-sommes-nous-prisonniers-du-langage.html","a20Step":"I.2","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}]},{"id":"spinoza-liberte-et-necessite","code":"S01","author":"Spinoza","title":"Liberté et nécessité","work":"Éthique","locator":"I, définition 7","quote":"On dit qu’est libre une chose qui existe par la seule nécessité de sa nature et qui n’est déterminée à agir que par elle seule ; mais on appelle nécessaire ou plutôt contrainte celle qui est déterminée par autre chose à exister et à accomplir ses opérations selon une raison précise et déterminée.","notions":["liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Être libre exige-t-il d’échapper à toute nécessité ?"},{"function":"L’affirmation","sentence":"Spinoza définit la liberté par une action qui découle de la nature propre de ce qui agit."},{"function":"Les concepts","sentence":"La nécessité désigne ce qui suit d’une nature, tandis que la contrainte désigne ici une détermination par autre chose."},{"function":"La raison","sentence":"Une action peut donc être nécessaire sans être imposée du dehors, ce que réalise absolument Dieu seul dans ce système."},{"function":"L’exemple","sentence":"Pour l’homme, comprendre les raisons de sa conduite permet de concevoir une autonomie plus grande que la simple obéissance à une impulsion."},{"function":"La portée","sentence":"La liberté humaine se pense ainsi comme un degré d’activité à conquérir, sans faire de l’homme une cause absolument indépendante."}],"uses":[{"subject":"Être libre, est-ce ne se soumettre à rien ?","function":"Redéfinir la liberté","reason":"Distinguer l’absence de toute détermination de la capacité à agir selon des raisons comprises.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Faut-il être raisonnable pour être libre ?","function":"Fonder une autonomie active","reason":"Comprendre ce qui nous détermine peut accroître notre activité, sans supprimer notre dépendance envers la nature.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=41","sourceLabel":"Recueil académique · p. 41"}]},{"id":"spinoza-connaitre-par-les-causes","code":"S02","author":"Spinoza","title":"Connaître par les causes","work":"Éthique","locator":"I, axiome 4","quote":"La connaissance de l’effet dépend de la connaissance de la cause et l’enveloppe.","notions":["science","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Constater qu’un événement se produit suffit-il à le connaître ?"},{"function":"L’affirmation","sentence":"Spinoza lie la connaissance de l’effet à celle de ce qui le produit."},{"function":"Les concepts","sentence":"La cause désigne ce dont l’effet suit, et non un événement qui le précède simplement dans le temps."},{"function":"La raison","sentence":"Comprendre pourquoi une chose existe demande de saisir la relation qui rend compte de sa production."},{"function":"L’exemple","sentence":"Observer la dilatation d’un métal ne l’explique pas encore si l’on ignore le rôle de son échauffement."},{"function":"La portée","sentence":"Cet axiome donne ainsi à la connaissance une exigence explicative qui dépasse le seul relevé des faits."}],"uses":[{"subject":"Connaître est-ce nécessairement expliquer ?","function":"Défendre une connaissance explicative","reason":"Connaître un effet exige ici de comprendre sa production, au-delà de sa seule description.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"},{"subject":"Prévoir, est-ce expliquer ?","function":"Distinguer prévision et causalité","reason":"Une régularité peut permettre une prévision sans donner encore la connaissance de la cause.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"spinoza-l-erreur-comme-connaissance-partielle","code":"S03","author":"Spinoza","title":"L’erreur comme connaissance partielle","work":"Éthique","locator":"II, proposition 35","quote":"La fausseté consiste en une privation de connaissance qu’enveloppent les idées inadéquates, autrement dit mutilées et confuses.","notions":["verite","conscience"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une idée fausse est-elle dépourvue de tout rapport au réel ?"},{"function":"L’affirmation","sentence":"Spinoza situe la fausseté dans ce qui manque à une idée pour être adéquate."},{"function":"Les concepts","sentence":"Une idée inadéquate donne une connaissance partielle dont nous ne saisissons pas suffisamment les causes et les relations."},{"function":"La raison","sentence":"Elle peut donc exprimer une affection réelle tout en nous trompant lorsque nous la prenons pour une connaissance complète de son objet."},{"function":"L’exemple","sentence":"Le Soleil paraît proche même à celui qui connaît sa distance, mais celui-ci ne confond plus cette apparence avec une mesure."},{"function":"La portée","sentence":"Corriger l’erreur consiste alors à compléter et à situer nos représentations, sans exiger la disparition de toutes les apparences."}],"uses":[{"subject":"L’ignorance est-elle la seule cause de nos erreurs ?","function":"Préciser le manque qui fait erreur","reason":"L’erreur ne se réduit pas à ne rien savoir : elle implique une représentation partielle dont la limite nous échappe.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Dissiper une illusion, est-ce seulement corriger une erreur ?","function":"Distinguer apparence et jugement","reason":"La connaissance peut corriger le jugement alors que l’apparence sensible persiste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"spinoza-se-connaitre-par-le-corps","code":"S04","author":"Spinoza","title":"Se connaître par le corps","work":"Éthique","locator":"II, proposition 23","quote":"L’esprit ne se connaît pas lui-même, sinon en tant qu’il perçoit les idées des affections du corps.","notions":["conscience","nature"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La connaissance de soi vient-elle d’un regard intérieur indépendant du corps ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que l’esprit se connaît à travers les idées des modifications corporelles."},{"function":"Les concepts","sentence":"Une affection est ici une modification du corps, dont l’esprit forme une idée et peut percevoir cette idée."},{"function":"La raison","sentence":"L’esprit étant l’idée du corps, sa connaissance de lui-même passe par les manières dont ce corps est affecté."},{"function":"L’exemple","sentence":"Éprouver puis reconnaître sa peur engage ainsi la perception de changements corporels, et pas seulement un jugement abstrait sur soi."},{"function":"La portée","sentence":"La conscience de soi se construit donc dans une expérience incarnée, sans garantir une connaissance complète de ses causes."}],"uses":[{"subject":"Être conscient, est-ce savoir ?","function":"Limiter la transparence à soi","reason":"Percevoir ce que l’on éprouve donne une conscience de soi, sans suffire à en connaître adéquatement les causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Peut-on penser sans sentir ?","function":"Montrer le rôle du corps","reason":"La connaissance de soi passe ici par les idées des affections corporelles plutôt que par un esprit isolé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"spinoza-perseverer-dans-son-etre","code":"S05","author":"Spinoza","title":"Persévérer dans son être","work":"Éthique","locator":"III, proposition 6","quote":"Abstraction faite du reste, chaque chose s’efforce de persévérer dans son être.","notions":["nature","liberte"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Le désir humain s’explique-t-il seulement par ce qui nous manque ?"},{"function":"L’affirmation","sentence":"Spinoza inscrit l’effort humain dans une tendance de chaque chose à persévérer dans son être."},{"function":"Les concepts","sentence":"Cet effort, appelé conatus, désigne une puissance effective d’exister et d’agir, sans supposer un projet conscient chez toute chose."},{"function":"La raison","sentence":"Considérée en elle-même, une chose affirme sa nature, tandis que sa destruction vient de causes qui lui sont contraires."},{"function":"L’exemple","sentence":"Un organisme qui répare une blessure manifeste une activité de conservation sans devoir se représenter une fin."},{"function":"La portée","sentence":"Le désir peut ainsi être compris à partir d’une puissance positive, sans nier les obstacles extérieurs qui la limitent."}],"uses":[{"subject":"Ne désirons-nous que ce qui nous manque ?","function":"Contester une définition par le manque","reason":"L’effort de vivre et d’agir exprime une puissance présente, même lorsqu’il rencontre une privation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Le désir est-il un obstacle à la liberté ?","function":"Écarter la suppression de tout désir","reason":"Si le désir exprime notre effort d’exister, la liberté doit transformer sa conduite plutôt que supprimer cet effort.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=43","sourceLabel":"Recueil académique · p. 43"}]},{"id":"spinoza-le-desir-et-le-jugement-de-valeur","code":"S06","author":"Spinoza","title":"Le désir et le jugement de valeur","work":"Éthique","locator":"III, proposition 9, scolie","quote":"Au contraire, si nous jugeons qu’une chose est bonne, c’est parce que nous faisons effort vers elle, que nous la voulons, que nous y aspirons, que nous la désirons.","notions":["raison","devoir"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Jugeons-nous une chose bonne avant de la désirer ?"},{"function":"L’affirmation","sentence":"Spinoza renverse cet ordre en faisant du désir le principe de notre jugement de valeur."},{"function":"Les concepts","sentence":"Le bon désigne ici ce que notre effort nous porte à rechercher, plutôt qu’une qualité reconnue indépendamment de toute aspiration."},{"function":"La raison","sentence":"Nos évaluations expriment ainsi une manière d’être affectés et de poursuivre ce qui nous paraît favorable."},{"function":"L’exemple","sentence":"Un aliment paraît précieux à celui qui a faim alors qu’il laisse indifférent celui qui est rassasié."},{"function":"La portée","sentence":"Ce renversement invite à examiner nos désirs, sans conclure que tous les objets désirés sont réellement utiles ou également bons."}],"uses":[{"subject":"Ne désirons-nous que les choses que nous estimons bonnes ?","function":"Renverser le rapport entre désir et valeur","reason":"Examiner si notre jugement motive le désir ou exprime déjà une aspiration.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=92","sourceLabel":"Recueil académique · p. 92"},{"subject":"Le désir est-il aveugle ?","function":"Interroger l’indépendance de nos jugements","reason":"Un jugement apparemment réfléchi peut traduire un désir dont nous ne connaissons pas les causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"}]},{"id":"spinoza-la-joie-et-la-puissance-d-agir","code":"S07","author":"Spinoza","title":"La joie et la puissance d’agir","work":"Éthique","locator":"IV, proposition 41","quote":"La joie, directement, n’est pas mauvaise, mais bonne ; la tristesse, au contraire, est directement mauvaise.","notions":["bonheur","devoir"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La joie a-t-elle seulement une valeur agréable et subjective ?"},{"function":"L’affirmation","sentence":"Spinoza la dit directement bonne et attribue à la tristesse la valeur contraire."},{"function":"Les concepts","sentence":"La joie est un passage à une puissance d’agir plus grande, tandis que la tristesse marque une diminution de cette puissance."},{"function":"La raison","sentence":"Leur valeur directe dépend de cette variation de nos capacités, et pas simplement d’une préférence pour des sensations plaisantes."},{"function":"L’exemple","sentence":"La joie de comprendre une difficulté peut rendre possible un travail qui paraissait jusque-là hors de portée."},{"function":"La portée","sentence":"Cette valeur directe ne rend pourtant pas toute joie bonne dans toutes ses conséquences, car certaines satisfactions partielles peuvent être excessives."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer joie et satisfaction immédiate","reason":"Le gain de puissance permet d’évaluer une joie, puis d’examiner ses effets au-delà de son agrément.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Obéir à la raison suffit-il à rendre heureux ?","function":"Relier raison et vie affective","reason":"La raison peut soutenir une joie active : vivre raisonnablement ne signifie pas vivre sans affects.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}]},{"id":"spinoza-transformer-les-affects","code":"S08","author":"Spinoza","title":"Transformer les affects","work":"Éthique","locator":"IV, proposition 7","quote":"Un affect ne peut être ni contrarié, ni supprimé, sinon par un affect contraire et plus fort que l’affect à contrarier.","notions":["liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une simple décision suffit-elle à vaincre une passion ?"},{"function":"L’affirmation","sentence":"Spinoza affirme qu’un affect ne cède que devant un affect contraire dont la force le dépasse."},{"function":"Les concepts","sentence":"Un affect est une modification qui augmente ou diminue notre puissance d’agir, accompagnée de son idée."},{"function":"La raison","sentence":"Une consigne abstraite ne change donc pas une passion tant qu’elle ne prend pas elle-même une force dans notre vie affective."},{"function":"L’exemple","sentence":"Le plaisir effectif d’un travail partagé peut ainsi contrarier une envie de renoncer plus efficacement qu’un ordre sans prise sur nous."},{"function":"La portée","sentence":"La maîtrise de soi exige alors une transformation des affects, où la raison agit par des désirs et des joies qu’elle fait naître."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Préciser les moyens de la libération","reason":"On ne combat pas une passion depuis une volonté sans affects : il faut construire une force contraire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"N’y a-t-il que des passions déraisonnables ?","function":"Distinguer affect et passion","reason":"La raison produit aussi des affects actifs, capables de transformer ceux que nous subissons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"}]},{"id":"spinoza-un-bien-qui-se-partage","code":"S09","author":"Spinoza","title":"Un bien qui se partage","work":"Éthique","locator":"IV, proposition 36","quote":"Le bien suprême de ceux qui poursuivent la vertu est commun à tous, et tout le monde peut s’en réjouir à égalité.","notions":["bonheur","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Le bien des autres diminue-t-il nécessairement le mien ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que le bien suprême de la vie vertueuse peut être partagé par tous."},{"function":"Les concepts","sentence":"Ce bien est la connaissance de Dieu, c’est-à-dire la compréhension de la réalité dont nous faisons partie, et la vertu est une puissance d’agir."},{"function":"La raison","sentence":"Comprendre ne prive personne de comprendre, contrairement à la possession exclusive d’un objet rare."},{"function":"L’exemple","sentence":"Lorsqu’un élève explique une démonstration à un camarade, le second peut la comprendre sans retirer au premier son savoir."},{"function":"La portée","sentence":"Un bien commun devient donc pensable au-delà de la rivalité, sans supposer que tous les biens matériels se partagent de cette manière."}],"uses":[{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Dépasser la rivalité des intérêts","reason":"Partager une compréhension peut contribuer à la joie d’autrui sans en faire un état que l’on pourrait lui imposer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La raison n’a-t-elle pour fin que la connaissance du réel ?","function":"Montrer une portée éthique du connaître","reason":"La compréhension peut constituer un bien partageable et transformer nos rapports avec les autres.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"}]},{"id":"spinoza-agir-par-raison-ou-par-peur","code":"S10","author":"Spinoza","title":"Agir par raison ou par peur","work":"Éthique","locator":"IV, proposition 63","quote":"Qui est conduit par la crainte, et fait le bien pour éviter le mal, n’est pas conduit par la raison.","notions":["devoir","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une conduite conforme au bien est-elle nécessairement raisonnable ?"},{"function":"L’affirmation","sentence":"Spinoza distingue l’action conduite par la crainte de celle qui naît de la raison."},{"function":"Les concepts","sentence":"La crainte nous fait fuir un mal incertain, tandis que la raison nous porte directement vers ce qui accroît notre puissance."},{"function":"La raison","sentence":"Un même comportement peut donc provenir de motifs différents, selon que nous comprenons son utilité ou redoutons une peine."},{"function":"L’exemple","sentence":"Respecter une règle par peur d’être puni diffère de la respecter parce qu’on comprend la protection qu’elle assure à chacun."},{"function":"La portée","sentence":"La valeur rationnelle d’une conduite demande ainsi l’examen de son principe, au-delà de sa seule conformité extérieure."}],"uses":[{"subject":"Obéir, est-ce nécessairement se soumettre ?","function":"Distinguer conformité et motif","reason":"Distinguer l’obéissance motivée par la peur de celle qui procède de la compréhension du bien poursuivi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"},{"subject":"Faut-il être raisonnable pour être libre ?","function":"Critiquer une obéissance dominée par la peur","reason":"Une conduite prudente en apparence peut rester sous la dépendance d’une passion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=41","sourceLabel":"Recueil académique · p. 41"}]},{"id":"spinoza-une-sagesse-de-la-vie","code":"S11","author":"Spinoza","title":"Une sagesse de la vie","work":"Éthique","locator":"IV, proposition 67","quote":"L’homme libre ne pense à rien moins qu’à la mort, et sa sagesse est une méditation non de la mort, mais de la vie.","notions":["bonheur","liberte","temps"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La sagesse doit-elle se construire autour de la peur de mourir ?"},{"function":"L’affirmation","sentence":"Spinoza définit la sagesse de l’homme libre par une méditation de la vie."},{"function":"Les concepts","sentence":"L’expression ne penser à rien moins qu’à la mort signifie que la mort est ce qui occupe le moins sa pensée."},{"function":"La raison","sentence":"Conduit par la raison, cet homme recherche directement ce qui lui permet de vivre et d’agir plutôt que de fuir seulement un mal."},{"function":"L’exemple","sentence":"Prendre soin de sa santé peut ainsi viser les activités que l’on aime accomplir au lieu de devenir une obsession de sa fin."},{"function":"La portée","sentence":"La lucidité sur notre condition mortelle ne disparaît pas, mais la crainte de la mort cesse de commander toute l’existence."}],"uses":[{"subject":"Pourquoi craindre la mort ?","function":"Contester le rôle directeur de la crainte","reason":"La sagesse peut reconnaître la mortalité tout en prenant pour objet principal la puissance de vivre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=143","sourceLabel":"Recueil académique · p. 143"},{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Déplacer l’obstacle vers notre rapport à la mort","reason":"La finitude n’empêche pas toute joie, tandis que la peur peut envahir la vie présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"}]},{"id":"spinoza-la-liberte-dans-la-cite","code":"S12","author":"Spinoza","title":"La liberté dans la cité","work":"Éthique","locator":"IV, proposition 73","quote":"L’homme conduit par la raison est plus libre dans la cité où il vit par décision commune, que dans la solitude où il n’obéit qu’à lui seul.","notions":["etat","liberte"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Être libre demande-t-il de vivre sans dépendre des autres ?"},{"function":"L’affirmation","sentence":"Spinoza affirme qu’une vie réglée en commun peut rendre l’homme raisonnable plus libre que la solitude."},{"function":"Les concepts","sentence":"La cité désigne une organisation politique, et la liberté une puissance d’agir guidée par la raison plutôt qu’une absence de liens."},{"function":"La raison","sentence":"La coopération et des droits communs soutiennent des capacités qu’un individu isolé ne pourrait exercer aussi sûrement."},{"function":"L’exemple","sentence":"Une règle commune protégeant chacun de la violence permet des activités que la seule force individuelle ne garantirait pas."},{"function":"La portée","sentence":"L’obéissance peut donc servir la liberté, sous réserve d’examiner les institutions réelles et sans justifier toute domination politique."}],"uses":[{"subject":"La liberté exclut-elle l’obéissance ?","function":"Distinguer obéissance et servitude","reason":"Obéir à une décision commune peut protéger une puissance d’agir au lieu de l’annuler.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Être seul, est-ce être libre ?","function":"Renverser l’idéal d’indépendance","reason":"La solitude supprime certains liens mais prive aussi des moyens d’agir que procure la vie commune.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}]},{"id":"spinoza-comprendre-une-passion","code":"S13","author":"Spinoza","title":"Comprendre une passion","work":"Éthique","locator":"V, proposition 3","quote":"Un affect qui est une passion cesse d’être une passion, sitôt que nous en formons une idée claire et distincte.","notions":["conscience","liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Comprendre ce que nous éprouvons peut-il modifier ce que nous subissons ?"},{"function":"L’affirmation","sentence":"Spinoza soutient qu’une connaissance claire de l’affect lui retire son caractère passif."},{"function":"Les concepts","sentence":"La passion est un affect dont nous ne sommes qu’une cause partielle, et son idée demeure confuse."},{"function":"La raison","sentence":"Former une idée adéquate transforme notre rapport à cet affect en y introduisant une activité de compréhension."},{"function":"L’exemple","sentence":"Identifier précisément les mécanismes de sa colère peut permettre d’agir sur la situation au lieu d’en accuser aveuglément une personne."},{"function":"La portée","sentence":"La compréhension devient ainsi un moyen de libération, sans promettre que nommer une émotion suffise à la connaître ni que toute émotion disparaisse."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Remplacer la répression par la compréhension","reason":"La passion peut être transformée par une activité de connaissance plutôt que combattue comme une force étrangère.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"Est-ce l’ignorance de ce que nous sommes qui fait la force de nos passions ?","function":"Établir un lien entre confusion et passivité","reason":"Comprendre l’affect change la manière dont nous en sommes affectés, au-delà d’une simple prise de conscience.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=131","sourceLabel":"Recueil académique · p. 131"}]},{"id":"spinoza-comprendre-la-necessite","code":"S14","author":"Spinoza","title":"Comprendre la nécessité","work":"Éthique","locator":"V, proposition 6","quote":"En tant que l’esprit comprend toutes choses comme nécessaires, il a par là une plus grande puissance sur les affects, autrement dit, il pâtit moins d’eux.","notions":["liberte","raison","bonheur"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Comprendre la nécessité nous condamne-t-il à subir davantage ?"},{"function":"L’affirmation","sentence":"Spinoza affirme au contraire que cette compréhension augmente notre puissance sur les affects."},{"function":"Les concepts","sentence":"La nécessité désigne l’enchaînement des causes qui produit les choses, tandis que pâtir signifie dépendre de causes que nous ne maîtrisons pas."},{"function":"La raison","sentence":"Comprendre cet enchaînement réduit les représentations confuses qui nourrissent certains regrets, certaines colères et certaines attentes impossibles."},{"function":"L’exemple","sentence":"Comprendre qu’une perte ne pouvait être évitée peut atténuer le regret qui la redouble, sans effacer immédiatement la tristesse."},{"function":"La portée","sentence":"La connaissance peut donc transformer notre manière de vivre ce qui arrive, sans nous donner le pouvoir de tout empêcher."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Montrer un effet pratique de la compréhension","reason":"Connaître les causes peut transformer notre rapport à une épreuve, même lorsque l’événement lui-même échappe à notre pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Obéir à la raison suffit-il à rendre heureux ?","function":"Établir un progrès sans garantir une invulnérabilité","reason":"Comprendre diminue certaines dépendances affectives, mais ne supprime pas notre exposition aux causes extérieures.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"},{"subject":"Faut-il être inconscient pour être heureux ?","function":"III.2 : faire du savoir une ressource contre la peur","reason":"Prolonger l’examen de la crainte par la compréhension des causes : elle peut diminuer certains regrets, sans faire disparaître toute douleur.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-faut-il-etre-inconscient-pour-etre-heureux.html","a20Step":"III.2","a20Status":"Insertion proposée après lecture de la copie ; citation absente du modèle."}]},{"id":"spinoza-l-ordre-des-idees-et-des-choses","code":"S15","author":"Spinoza","title":"L’ordre des idées et des choses","work":"Éthique","locator":"II, proposition 7","quote":"L’ordre et enchaînement des idées est le même que l’ordre et enchaînement des choses.","notions":["nature","raison","science"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La pensée et les choses appartiennent-elles à deux mondes sans rapport ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que leurs enchaînements expriment un même ordre."},{"function":"Les concepts","sentence":"Les idées sont des modes de la pensée, tandis que les choses se comprennent sous les attributs dont elles relèvent."},{"function":"La raison","sentence":"Une même réalité s’exprime selon ces attributs sans qu’il faille supposer une action de la pensée sur l’étendue ou de l’étendue sur la pensée."},{"function":"L’exemple","sentence":"Un événement corporel et son idée se comprennent ainsi comme deux expressions d’une même réalité, et non comme deux événements qui se commanderaient du dehors."},{"function":"La portée","sentence":"Cette thèse fonde l’intelligibilité du réel, sans prétendre que toutes nos représentations particulières en donnent une connaissance adéquate."}],"uses":[{"subject":"La raison suffit-elle à connaître le réel ?","function":"Fonder la possibilité d’une connaissance rationnelle","reason":"Le réel présente un ordre intelligible, mais il reste à établir que nos idées particulières le saisissent adéquatement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"L’activité de l’esprit s’explique-t-elle par des causes matérielles ?","function":"Distinguer unité et réduction","reason":"Le même ordre s’exprime sous la pensée et l’étendue sans faire d’un événement matériel la cause d’une idée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=99","sourceLabel":"Recueil académique · p. 99"}]},{"id":"cioran-les-faux-absolus","code":"C01","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les faux absolus","work":"Précis de décomposition","locator":"« Généalogie du fanatisme »","quote":"L’histoire n’est qu’un défilé de faux Absolus, une succession de temples élevés à des prétextes, un avilissement de l’esprit devant l’improbable.","notions":["religion","raison"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Abandonner une religion suffit-il à se libérer de toute croyance absolue ?"},{"function":"L’affirmation","sentence":"Cioran présente l’histoire comme une succession d’objets humains transformés en absolus."},{"function":"Les concepts","sentence":"Un faux absolu est ici une valeur ou une cause particulière soustraite à toute discussion et adorée comme une divinité."},{"function":"La raison","sentence":"Le besoin de croire peut donc déplacer sa ferveur vers une nation, une classe ou une idée sans changer de fonctionnement."},{"function":"L’exemple","sentence":"Une cause politique devient ainsi une idole lorsque toute objection passe pour une trahison."},{"function":"La portée","sentence":"Cette image dénonce une possibilité du fanatisme, mais sa généralisation polémique ne démontre pas que toute conviction ou toute histoire se réduise à ce mécanisme."}],"uses":[{"subject":"L’esprit religieux ne se manifeste-t-il que dans les religions ?","function":"Déplacer la frontière du religieux","reason":"Interroger les formes de sacralisation qui survivent dans des idéologies se déclarant étrangères à la religion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"L’histoire enseigne-t-elle la relativité des valeurs ?","function":"Mettre à distance les valeurs proclamées absolues","reason":"La succession des causes sacralisées invite à examiner leur prétention à une validité inconditionnelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=106","sourceLabel":"Recueil académique · p. 106"},{"subject":"Peut-on concevoir une humanité sans religion ?","function":"II.3 : limiter la force du lien religieux","reason":"Une communauté peut transformer sa croyance commune en absolu et exclure la contestation ; une idéologie séculière peut reproduire ce mécanisme.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517529.pdf#page=2","sourceLabel":"Bac 2026 · Antilles et Guyane","a20":"philosophie-bac-2026-peut-on-concevoir-une-humanite-sans-religion.html","a20Step":"II.3","a20Status":"Insertion possible après lecture de la copie ; citation absente du modèle."}]},{"id":"cioran-les-mots-et-la-presence-des-choses","code":"C02","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les mots et la présence des choses","work":"Précis de décomposition","locator":"« Dans le cimetière des définitions »","quote":"Sous chaque formule gît un cadavre : l’être ou l’objet meurt sous le prétexte auquel ils ont donné lieu.","notions":["langage","verite"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Une formule rend-elle compte d’une chose ou risque-t-elle de s’y substituer ?"},{"function":"L’affirmation","sentence":"Cioran décrit la définition comme une opération qui peut faire disparaître la présence vivante de son objet."},{"function":"Les concepts","sentence":"Le cadavre est une métaphore de la chose réduite à ce que notre formule en retient, et non détruite matériellement."},{"function":"La raison","sentence":"Lorsque l’esprit prend sa définition pour la réalité entière, il néglige ce que la rencontre sensible et singulière lui faisait éprouver."},{"function":"L’exemple","sentence":"Réduire une personne à une étiquette peut ainsi empêcher d’écouter ce qui, dans sa conduite, dément cette étiquette."},{"function":"La portée","sentence":"La formule oblige à éprouver nos mots au contact des choses, sans établir que toute définition soit inutile ou nécessairement trompeuse."}],"uses":[{"subject":"Le langage nous éloigne-t-il du réel ?","function":"Analyser le risque de substitution","reason":"Un énoncé peut devenir un écran lorsqu’il remplace l’attention portée à ce qu’il désigne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Le langage peut-il être un obstacle à la recherche de la vérité ?","function":"Critiquer une définition figée","reason":"Il faut distinguer l’outil qui permet de chercher de la formule qui prétend clore la recherche.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35"}]},{"id":"cioran-l-ennui-et-le-sens-de-vivre","code":"C03","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’ennui et le sens de vivre","work":"Précis de décomposition","locator":"« Désarticulation du temps »","quote":"La vie se crée dans le délire et se défait dans l’ennui.","notions":["bonheur","temps"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le repos et l’absence de difficultés suffisent-ils à donner le sentiment de vivre ?"},{"function":"L’affirmation","sentence":"Cioran oppose l’élan qui peuple la vie de significations à l’ennui qui les défait."},{"function":"Les concepts","sentence":"Le délire désigne ici nos investissements excessifs dans des désirs et des valeurs, tandis que l’ennui les prive de leur évidence."},{"function":"La raison","sentence":"Lorsque plus rien ne nous attire, les instants continuent de passer mais cessent de porter des possibilités auxquelles nous tenons."},{"function":"L’exemple","sentence":"Une journée entièrement libre peut ainsi paraître interminable si aucun projet ne rend ses moments désirables."},{"function":"La portée","sentence":"L’opposition éclaire la fragilité du sens vécu, sans faire de tout engagement une maladie ni de tout repos un vide."}],"uses":[{"subject":"Le bonheur se trouve-t-il dans le repos ?","function":"Limiter l’idéal d’absence de trouble","reason":"Le repos ne suffit pas si la disparition des préoccupations retire aussi tout intérêt à ce que l’on vit.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Un bonheur sans illusion est-il concevable ?","function":"Interroger le rôle des attachements","reason":"Examiner si le sentiment de vivre dépend de valeurs investies au-delà de ce qu’une lucidité critique peut garantir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-expliquer-et-vivre","code":"C04","author":"Cioran","authorRole":"Écrivain et penseur","title":"Expliquer et vivre","work":"Précis de décomposition","locator":"« Adieu à la philosophie »","quote":"On ne peut éluder l’existence par des explications, on ne peut que la subir, l’aimer ou la haïr, l’adorer ou la craindre, dans cette alternance de félicité et d’horreur qui exprime le rythme même de l’être, ses oscillations, ses dissonances, ses véhémences amères ou allègres.","notions":["raison","bonheur"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Comprendre pourquoi nous souffrons suffit-il à nous dispenser de vivre cette souffrance ?"},{"function":"L’affirmation","sentence":"Cioran conteste le pouvoir des explications de nous soustraire à l’épreuve de l’existence."},{"function":"Les concepts","sentence":"Éluder signifie esquiver, tandis qu’expliquer consiste à rendre intelligible ce qui arrive plutôt qu’à l’éprouver à notre place."},{"function":"La raison","sentence":"Une théorie peut décrire une situation sans supprimer les sentiments contradictoires dans lesquels nous la traversons."},{"function":"L’exemple","sentence":"Connaître les mécanismes du deuil ne fait pas disparaître immédiatement la douleur d’une perte."},{"function":"La portée","sentence":"Cette critique limite la prétention du savoir à nous délivrer de toute épreuve, sans prouver qu’une explication ne puisse jamais nous aider à vivre."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Limiter le pouvoir du savoir","reason":"Comprendre une épreuve ne dispense pas de la traverser ; il reste à préciser en quoi la compréhension peut néanmoins aider.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La raison peut-elle tout expliquer ?","function":"Distinguer explication et expérience","reason":"Même une explication étendue ne remplace pas l’expérience vécue, ce qui ne constitue pas à soi seul une réfutation de cette explication.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"}]},{"id":"cioran-les-desirs-dementent-nos-principes","code":"C05","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les désirs démentent nos principes","work":"Précis de décomposition","locator":"« Cosmogonie du désir »","quote":"Chaque désir humilie la somme de nos vérités et nous oblige à reconsidérer nos négations.","notions":["raison","liberte"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Nos conclusions intellectuelles commandent-elles effectivement nos désirs ?"},{"function":"L’affirmation","sentence":"Cioran montre le désir revenant contredire les raisons par lesquelles nous prétendions nous détacher de la vie."},{"function":"Les concepts","sentence":"Les vérités et les négations désignent ici les conclusions pessimistes du narrateur, tandis que le désir marque la persistance de son attachement."},{"function":"La raison","sentence":"Le corps peut continuer de vouloir ce que l’esprit avait déclaré vain, révélant un écart entre conviction théorique et conduite effective."},{"function":"L’exemple","sentence":"Celui qui proclame l’inutilité des honneurs peut encore attendre avec impatience un signe de reconnaissance."},{"function":"La portée","sentence":"Le désir éprouve ainsi la portée pratique de nos principes, sans que sa force suffise à démontrer leur fausseté logique."}],"uses":[{"subject":"La raison s’oppose-t-elle nécessairement au désir ?","function":"Analyser un conflit sans le généraliser","reason":"Les raisons de se détacher peuvent échouer à éteindre un attachement, ce qui ne condamne pas toute alliance entre raison et désir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Peut-on être en conflit avec soi-même ?","function":"Distinguer jugement et attachement","reason":"Un même individu peut soutenir une conclusion et continuer de désirer ce qu’elle dévalue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}]},{"id":"cioran-reflechir-transforme-la-sensation","code":"C06","author":"Cioran","authorRole":"Écrivain et penseur","title":"Réfléchir transforme la sensation","work":"Précis de décomposition","locator":"« Visages de la décadence »","quote":"Méditer ses sensations – savoir que l’on mange, – c’est là une prise de conscience grâce à laquelle un acte élémentaire dépasse son but immédiat.","notions":["conscience","nature"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La conscience accompagne-t-elle seulement nos actes ou en transforme-t-elle la signification ?"},{"function":"L’affirmation","sentence":"Cioran affirme que l’attention portée à une sensation modifie un acte aussi élémentaire que manger."},{"function":"Les concepts","sentence":"Le but immédiat est ici de se nourrir, tandis que méditer sa sensation fait du repas un objet de réflexion et de recherche."},{"function":"La raison","sentence":"L’acte ne se limite plus à satisfaire un besoin lorsque l’esprit s’intéresse à la qualité et aux variations de ce qu’il éprouve."},{"function":"L’exemple","sentence":"Comparer lentement des saveurs introduit ainsi une recherche du goût au-delà de la seule faim."},{"function":"La portée","sentence":"Dans ce passage sur la décadence, ce raffinement reste ambivalent et ne vaut donc pas comme preuve que toute réflexion améliore la vie."}],"uses":[{"subject":"Sommes-nous conscients ou le devenons-nous ?","function":"Distinguer vécu immédiat et réflexion","reason":"La prise de conscience peut modifier le sens d’un acte déjà accompli sans attention réfléchie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"La conscience de ce que nous sommes peut-elle faire obstacle à notre bonheur ?","function":"Interroger les effets du retour sur soi","reason":"La réflexion enrichit parfois une sensation, mais peut aussi compliquer et inquiéter ce qui se faisait spontanément.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-le-doute-et-la-vie-commune","code":"C07","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le doute et la vie commune","work":"La Chute dans le temps","locator":"« Le sceptique et le barbare »","quote":"Une civilisation débute par le mythe et finit dans le doute ; doute théorique qui, lorsqu’elle le retourne contre elle-même, s’achève en doute pratique.","notions":["raison","verite"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La critique des croyances peut-elle finir par atteindre notre capacité d’agir ?"},{"function":"L’affirmation","sentence":"Cioran décrit une civilisation dont le doute passe de l’examen des idées à l’incertitude sur ses propres fins."},{"function":"Les concepts","sentence":"Le doute théorique porte sur ce que l’on tient pour vrai, tandis que le doute pratique atteint les valeurs qui orientent les actes."},{"function":"La raison","sentence":"Lorsqu’une communauté ne reconnaît plus aucun motif de préférer une fin à une autre, sa lucidité peut se convertir en impuissance."},{"function":"L’exemple","sentence":"Un groupe qui remet indéfiniment en question toutes ses raisons de décider peut ne plus parvenir à choisir une action commune."},{"function":"La portée","sentence":"Ce schéma tragique interroge le coût d’un doute généralisé, sans constituer une loi démontrée de la naissance et de la mort de toutes les civilisations."}],"uses":[{"subject":"Douter, est-ce renoncer à la vérité ?","function":"Distinguer examen et désorientation","reason":"Le doute peut servir la recherche, mais son extension à toute raison de juger peut retirer à cette recherche sa direction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Peut-on ne croire en rien ?","function":"Examiner les conditions de l’action","reason":"Une suspension totale des convictions pose la question des raisons qui permettraient encore de décider.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}]},{"id":"cioran-convertir-et-contraindre","code":"C08","author":"Cioran","authorRole":"Écrivain et penseur","title":"Convertir et contraindre","work":"La Chute dans le temps","locator":"« Portrait du civilisé »","quote":"Ce n’est point pour libérer, c’est pour enchaîner qu’on s’applique à convertir.","notions":["religion","liberte"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Vouloir faire adopter sa conviction revient-il toujours à servir la liberté d’autrui ?"},{"function":"L’affirmation","sentence":"Cioran soupçonne la conversion de prolonger une volonté de soumettre sous une promesse de libération."},{"function":"Les concepts","sentence":"Convertir signifie faire adhérer à une croyance, et la chaîne figure ici une dépendance imposée au jugement."},{"function":"La raison","sentence":"Celui qui ne supporte pas sa propre discipline peut vouloir la généraliser plutôt que reconnaître à un autre la possibilité de s’en passer."},{"function":"L’exemple","sentence":"Une doctrine devient contraignante lorsque celui qui prétend sauver autrui lui retire le droit de refuser son salut."},{"function":"La portée","sentence":"La formule démasque une logique possible du prosélytisme, mais son absoluité polémique ne suffit pas à identifier toute transmission d’une croyance à une oppression."}],"uses":[{"subject":"La religion unit-elle ou sépare-t-elle les hommes ?","function":"Interroger les conditions du rassemblement","reason":"L’union autour d’une croyance peut devenir une exigence d’uniformité qui exclut le refus et la différence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"La liberté exclut-elle l’obéissance ?","function":"Critiquer une soumission présentée comme un salut","reason":"Il faut examiner si l’adhésion conserve la possibilité de juger et de refuser, au-delà de la liberté annoncée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}]},{"id":"cioran-l-assurance-et-le-besoin-d-eloge","code":"C09","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’assurance et le besoin d’éloge","work":"La Chute dans le temps","locator":"« Désir et horreur de la gloire »","quote":"En apparence, tout le monde est content de soi ; en réalité, personne.","notions":["conscience","bonheur"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"L’assurance que nous montrons aux autres prouve-t-elle que nous sommes satisfaits de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Cioran oppose l’image publique de la satisfaction à une insécurité intérieure que l’éloge vient apaiser."},{"function":"Les concepts","sentence":"L’apparence désigne ce que nous affichons, tandis que le contentement de soi désigne ici une estime assez stable pour ne plus chercher de confirmation."},{"function":"La raison","sentence":"Le besoin persistant de compliments peut révéler une dépendance au jugement d’autrui jusque chez celui qui se dit supérieur à ce jugement."},{"function":"L’exemple","sentence":"Une personne affichant son indifférence aux critiques peut pourtant attendre avec impatience des félicitations."},{"function":"La portée","sentence":"La symétrie provocatrice entre tout le monde et personne invite à interroger cette dépendance, sans établir que nul ne puisse jamais acquérir une estime de soi solide."}],"uses":[{"subject":"Avons-nous besoin d’autrui pour avoir conscience de nous-mêmes ?","function":"Distinguer conscience de soi et validation","reason":"Le besoin d’approbation montre un rôle du regard d’autrui, sans prouver que toute conscience de soi dépende de ses éloges.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"},{"subject":"La conscience de soi est-elle trompeuse ?","function":"Interroger l’image que l’on se donne","reason":"Le sentiment d’assurance peut masquer à soi-même une demande de reconnaissance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}]},{"id":"cioran-le-corps-revele-par-l-epreuve","code":"C10","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le corps révélé par l’épreuve","work":"La Chute dans le temps","locator":"« Sur la maladie »","quote":"Pour que la conscience atteigne à une certaine intensité, il faut que l’organisme pâtisse et même qu’il se désagrège : la conscience, à ses débuts, est conscience des organes.","notions":["conscience","nature","liberte"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le corps devient-il plus présent à la conscience lorsqu’il cesse de fonctionner sans difficulté ?"},{"function":"L’affirmation","sentence":"Cioran rapporte l’intensification de la conscience à l’épreuve d’un organisme qui souffre."},{"function":"Les concepts","sentence":"La conscience des organes désigne ici leur présence insistante dans notre expérience, plutôt qu’un savoir anatomique complet."},{"function":"La raison","sentence":"Ce qui se faisait oublier dans une activité aisée retient notre attention dès qu’une gêne ou une douleur interrompt cette activité."},{"function":"L’exemple","sentence":"Une difficulté à respirer peut ainsi rendre sensible une fonction que nous accomplissions sans y penser."},{"function":"La portée","sentence":"Ce diagnostic polémique éclaire une expérience du corps empêché, sans établir que la souffrance soit nécessaire à toute conscience ni que cette conscience accrue rende plus libre."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer un enracinement corporel de la réflexion","reason":"Une modification corporelle peut devenir le point de départ d’une attention et d’une réflexion sur soi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"La conscience est-elle source de liberté ou de contrainte ?","function":"Distinguer conscience accrue et pouvoir accru","reason":"Mieux sentir sa dépendance corporelle ne donne pas nécessairement les moyens de la surmonter.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"}]},{"id":"cioran-la-creation-et-la-clairvoyance","code":"C11","author":"Cioran","authorRole":"Écrivain et penseur","title":"La création et la clairvoyance","work":"La Chute dans le temps","locator":"« Les dangers de la sagesse »","quote":"Produire, « créer », c’est s’interdire la clairvoyance, c’est avoir le courage ou le bonheur de ne pas percevoir le mensonge de la diversité, le caractère trompeur du multiple.","notions":["art","verite"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Une lucidité qui relativise toute apparence laisse-t-elle encore un motif de créer ?"},{"function":"L’affirmation","sentence":"Cioran présente la création comme un engagement dans des différences qu’une sagesse détachée tend à dissoudre."},{"function":"Les concepts","sentence":"La clairvoyance désigne ici ce détachement radical, tandis que la diversité est le monde des formes et des conflits qui fournit ses matériaux à l’artiste."},{"function":"La raison","sentence":"Créer suppose d’accorder assez d’importance à ces différences pour les explorer plutôt que les ramener toutes au même néant."},{"function":"L’exemple","sentence":"Un romancier travaille les conflits de ses personnages parce qu’il consent à prendre au sérieux leurs attachements singuliers."},{"function":"La portée","sentence":"Cette provocation oppose deux rapports au monde, sans démontrer que l’artiste doive ignorer son métier ou renoncer à tout examen critique de son œuvre."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","function":"Distinguer attention créatrice et détachement","reason":"Une œuvre peut explorer des apparences auxquelles une certaine sagesse refuserait de s’attacher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Interroger les effets d’une lucidité radicale","reason":"Examiner si dévoiler toute apparence comme trompeuse peut détruire aussi des motifs de vivre et de créer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"L’artiste sait-il ce qu’il fait ?","function":"II.3 : mettre à l’épreuve une création sans lucidité","reason":"Confronter le détachement radical visé par Cioran à la lucidité du travail artistique : refuser une sagesse qui dissout les apparences n’interdit pas les choix et les corrections.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-l-artiste-sait-il-ce-qu-il-fait.html","a20Step":"II.3","a20Status":"Insertion possible comme thèse à discuter après lecture de la copie ; citation absente du modèle."}]},{"id":"cioran-l-avenir-deja-passe","code":"C12","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’avenir déjà passé","work":"La Chute dans le temps","locator":"« Tomber du temps »","quote":"Vivre, c’est subir la magie du possible ; mais lorsqu’on perçoit dans le possible même du révolu à venir, tout devient virtuellement passé, et il n’y a plus de présent ni de futur.","notions":["temps","conscience"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Que devient le présent si nous regardons chaque possibilité comme déjà révolue ?"},{"function":"L’affirmation","sentence":"Cioran décrit une expérience où l’anticipation de la disparition retire aux instants leur ouverture."},{"function":"Les concepts","sentence":"Le possible est ce qui peut encore advenir, tandis que le révolu désigne ce qui est achevé et ne peut plus être modifié."},{"function":"La raison","sentence":"Traiter par avance un projet comme un souvenir détruit l’attente qui permettrait de s’y engager et d’en éprouver la nouveauté."},{"function":"L’exemple","sentence":"Imaginer une rencontre uniquement comme ce qui sera bientôt terminé peut empêcher d’être disponible à ce qui s’y passe."},{"function":"La portée","sentence":"La formule éclaire ainsi une manière de perdre le présent, sans affirmer que le temps physique cesse de s’écouler ni que toute anticipation soit paralysante."}],"uses":[{"subject":"Est-il possible de vivre au présent ?","function":"Distinguer présence chronologique et disponibilité","reason":"Être dans l’instant ne suffit pas si l’on le considère déjà comme un passé clos.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer mesure et temps vécu","reason":"Un même intervalle mesuré peut être vécu comme une ouverture ou comme une disparition déjà accomplie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}]},{"id":"cioran-le-malaise-avant-la-faute","code":"C13","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le malaise avant la faute","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"La malédiction qui nous accable pesait déjà sur notre premier ancêtre, bien avant qu’il se tournât vers l’arbre de la connaissance.","notions":["bonheur","religion"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Pourquoi désirer quitter un bonheur dont on disposerait déjà ?"},{"function":"L’affirmation","sentence":"Cioran situe le malaise d’Adam avant la transgression, au cœur même du paradis."},{"function":"Les concepts","sentence":"La malédiction désigne ici une insatisfaction constitutive, et le premier ancêtre est la figure biblique par laquelle cette condition humaine est interrogée."},{"function":"La raison","sentence":"Si Adam cède si facilement à la tentation, c’est, selon cette lecture, que la paix disponible ne suffisait déjà pas à le satisfaire."},{"function":"L’exemple","sentence":"Un repos longtemps désiré peut ainsi laisser paraître une nouvelle impatience lorsqu’aucun obstacle extérieur ne trouble plus notre vie."},{"function":"La portée","sentence":"La relecture du mythe interroge notre aptitude au bonheur, sans établir que toute insatisfaction soit universelle ni que cette interprétation soit le sens unique de la Genèse."}],"uses":[{"subject":"Le bonheur est-il inaccessible à l’homme ?","function":"Déplacer la difficulté vers notre rapport au bonheur","reason":"L’obstacle peut tenir à notre incapacité de nous satisfaire d’un bonheur présent, et pas seulement aux événements qui nous en privent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Un bonheur sans illusion est-il concevable ?","function":"Interroger l’idéal d’une innocence heureuse","reason":"La fiction d’un paradis antérieur au savoir peut elle-même dissimuler une inquiétude déjà présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-connaitre-et-perdre-la-familiarite-du-monde","code":"C14","author":"Cioran","authorRole":"Écrivain et penseur","title":"Connaître et perdre la familiarité du monde","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Le désir de connaître, empreint de perversité et de corruption, plus il nous tient, plus il nous rend incapables de demeurer à l’intérieur de quelque réalité que ce soit.","notions":["raison","verite","bonheur"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le désir de savoir nous rapproche-t-il toujours du monde dans lequel nous vivons ?"},{"function":"L’affirmation","sentence":"Cioran décrit une connaissance qui éloigne de la participation immédiate aux choses à mesure qu’elle cherche à les analyser."},{"function":"Les concepts","sentence":"Demeurer à l’intérieur d’une réalité signifie ici y être engagé sans la tenir constamment à distance comme un objet à examiner."},{"function":"La raison","sentence":"Dans sa relecture de la Genèse, la curiosité rompt une familiarité et pousse l’homme vers de nouvelles questions plutôt que vers un repos définitif."},{"function":"L’exemple","sentence":"Analyser sans cesse les raisons d’une joie peut modifier cette joie et empêcher de s’y abandonner."},{"function":"La portée","sentence":"Le vocabulaire de la faute dramatise cette rupture, sans démontrer que tout savoir soit nuisible ni que toute analyse interdise de vivre."}],"uses":[{"subject":"Le désir de savoir est-il naturel ?","function":"Distinguer élan spontané et accord avec la nature","reason":"Le désir de connaître peut être puissant tout en nous éloignant, selon Cioran, d’une adhésion immédiate à notre condition.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=48","sourceLabel":"Recueil académique · p. 48"},{"subject":"La connaissance peut-elle nuire au bonheur ?","function":"Analyser le prix d’une mise à distance","reason":"Le regard qui examine peut défaire certaines évidences dont une expérience heureuse se nourrissait.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Faut-il être inconscient pour être heureux ?","function":"I.2 : renforcer l’attrait de l’insouciance","reason":"Le désir d’analyse peut rompre une familiarité heureuse et nourrir l’inquiétude ; cette première réponse reste à confronter aux dangers que l’ignorance ne supprime pas.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-faut-il-etre-inconscient-pour-etre-heureux.html","a20Step":"I.2","a20Status":"Insertion possible après lecture de la copie, en complément de Pascal, sans assimiler les deux arguments."}]},{"id":"cioran-la-conscience-de-notre-fragilite","code":"C15","author":"Cioran","authorRole":"Écrivain et penseur","title":"La conscience de notre fragilité","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"L’inorganique se suffit à lui-même ; l’organique est dépendant, menacé, instable ; le conscient est quintessence de caducité.","notions":["conscience","nature","temps"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La conscience de notre condition ajoute-t-elle une épreuve à notre fragilité physique ?"},{"function":"L’affirmation","sentence":"Cioran présente la conscience comme une intensification de la précarité propre au vivant."},{"function":"Les concepts","sentence":"La caducité désigne le caractère périssable, tandis que la quintessence en figure ici la concentration extrême."},{"function":"La raison","sentence":"Dans ce passage, l’homme éprouve sa dépendance et anticipe sa mort, au lieu de seulement subir les limites de son organisme."},{"function":"L’exemple","sentence":"Prévoir la disparition future d’un bonheur peut ainsi troubler une joie qui n’est pas encore menacée dans le présent."},{"function":"La portée","sentence":"Cette gradation éclaire le poids de la mortalité connue, sans décrire scientifiquement tous les vivants ni établir que toute conscience exclue la joie."}],"uses":[{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Distinguer mortalité et anticipation de la mort","reason":"La conscience d’une fin peut peser sur le présent avant que cette fin survienne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"},{"subject":"Peut-on être pleinement homme sans penser à la mort ?","function":"Interroger la place de la finitude dans la conscience","reason":"Le passage lie la singularité humaine au savoir de sa précarité, dont il faut examiner aussi les effets sur la vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=137","sourceLabel":"Recueil académique · p. 137"}]},{"id":"cioran-le-savoir-nous-precipite-dans-le-temps","code":"C16","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le savoir nous précipite dans le temps","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Précipités par le savoir dans le temps, nous fûmes du même coup dotés d’un destin.","notions":["temps","conscience","religion"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Comment le savoir pourrait-il nous faire entrer dans un temps où nous vivons déjà ?"},{"function":"L’affirmation","sentence":"Cioran interprète la sortie du paradis comme l’apparition d’une existence consciente de son devenir."},{"function":"Les concepts","sentence":"Le temps désigne ici l’expérience de la perte et des possibles, tandis que le destin donne à notre vie la forme d’une histoire orientée vers sa fin."},{"function":"La raison","sentence":"Le savoir rompt l’adhésion innocente au présent en faisant apparaître ce qui pourrait arriver et ce qui ne reviendra plus."},{"function":"L’exemple","sentence":"Savoir qu’une rencontre peut être la dernière transforme un moment ordinaire en événement chargé d’attente et de regret."},{"function":"La portée","sentence":"Cette lecture philosophique du mythe distingue le temps vécu de la simple durée, sans prétendre que les êtres privés de ce savoir échappent au changement physique."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer durée physique et conscience du devenir","reason":"Le paradis figure une innocence soustraite à l’expérience inquiète de la perte, plutôt qu’une simple absence de changement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"La conscience de ce que nous sommes peut-elle faire obstacle à notre bonheur ?","function":"Montrer le poids de l’anticipation","reason":"La conscience de notre avenir et de notre fin peut troubler l’adhésion au présent, sans suffire à condamner toute lucidité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-l-outil-et-la-faiblesse-humaine","code":"C17","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’outil et la faiblesse humaine","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"N’éprouvant nul besoin d’ajouter à sa force, qui est réelle, un fauve ne s’abaisse pas à l’outil.","notions":["technique","nature"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La puissance technique prouve-t-elle une force naturelle supérieure ?"},{"function":"L’affirmation","sentence":"Cioran renverse cette interprétation en présentant l’outil comme une compensation dont l’animal puissant n’aurait pas besoin."},{"function":"Les concepts","sentence":"La force réelle désigne ici une puissance corporelle disponible, tandis que l’outil ajoute des moyens artificiels à un organisme insuffisamment armé."},{"function":"La raison","sentence":"Dans le récit de la sortie du paradis, l’inadaptation humaine devient ainsi le ressort d’une conquête toujours plus ambitieuse."},{"function":"L’exemple","sentence":"Un instrument de coupe permet à une main de réaliser ce qu’elle ne pourrait accomplir par sa seule force."},{"function":"La portée","sentence":"Le verbe s’abaisser exprime une provocation qui renverse notre hiérarchie habituelle, sans fournir une classification scientifique des animaux ni prouver que tout outil soit dégradant."}],"uses":[{"subject":"La technique nous libère-t-elle de la nature ?","function":"Retrouver une dépendance dans la puissance acquise","reason":"L’invention technique peut répondre à des limites naturelles plutôt que nous en rendre absolument indépendants.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=47","sourceLabel":"Recueil académique · p. 47"},{"subject":"La technique naît-elle de nos besoins ou de nos rêves ?","function":"Relier compensation et ambition","reason":"Un manque initial peut susciter des moyens dont le développement dépasse ensuite la seule satisfaction du besoin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"}]},{"id":"cioran-devenir-n-est-pas-progresser","code":"C18","author":"Cioran","authorRole":"Écrivain et penseur","title":"Devenir n’est pas progresser","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Devenir et progrès sont notions en apparence voisines, en fait divergentes.","notions":["technique","temps","raison"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le simple fait de changer nous conduit-il nécessairement vers un état meilleur ?"},{"function":"L’affirmation","sentence":"Cioran refuse d’identifier le devenir à un progrès."},{"function":"Les concepts","sentence":"Le devenir désigne une transformation, tandis que le progrès suppose un critère permettant de juger cette transformation meilleure."},{"function":"La raison","sentence":"Une suite de nouveautés ne justifie donc pas à elle seule une confiance dans l’amélioration de la condition humaine."},{"function":"L’exemple","sentence":"Une machine plus puissante peut faciliter une tâche tout en augmentant des dépendances ou des destructions."},{"function":"La portée","sentence":"Cette distinction oblige à évaluer les transformations plutôt qu’à célébrer leur nouveauté, sans prouver que toute amélioration soit impossible ni que tout changement soit une dégradation."}],"uses":[{"subject":"Faut-il voir dans l’histoire humaine un progrès constant ?","function":"Distinguer succession et amélioration","reason":"L’enchaînement des changements n’établit pas leur valeur ni leur direction vers un mieux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Le progrès de l’humanité se réduit-il au progrès technique ?","function":"Distinguer puissance des moyens et valeur des fins","reason":"Une efficacité accrue ne suffit pas à établir une amélioration du bonheur, de la justice ou de la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"}]},{"id":"kant-experience-et-origine","code":"K01","author":"Kant","title":"Commencer avec l’expérience","work":"Critique de la raison pure","locator":"Introduction, I · B 1–2","quote":"Cela dit, bien que toute notre connaissance s'amorce avec l'expérience, il n'en résulte pas pour autant qu'elle dérive dans sa totalité de l'expérience.","notions":["science","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Tout ce que nous connaissons vient-il de ce que nous avons éprouvé ?"},{"function":"L’affirmation","sentence":"Kant distingue le commencement de la connaissance et l’origine de tous ses éléments."},{"function":"Les concepts","sentence":"L’expérience éveille notre connaissance, mais cela ne prouve pas qu’elle fournisse aussi les règles qui l’organisent."},{"function":"La raison","sentence":"Pour connaître un objet, nous devons relier ce que nous recevons des sens, et non seulement accumuler des impressions."},{"function":"L’exemple","sentence":"Observer plusieurs changements ne suffit pas, à lui seul, à expliquer pourquoi nous recherchons pour chacun une cause."},{"function":"La portée","sentence":"L’expérience est donc indispensable à la connaissance, sans être nécessairement la source de toutes ses conditions."}],"uses":[{"subject":"L’expérience est-elle la seule source de la connaissance ?","function":"Distinguer le commencement et le fondement","reason":"Après avoir établi le rôle des sens, montrer que les règles qui organisent leurs données ne sont pas de simples impressions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"},{"subject":"D’où viennent nos connaissances ?","function":"Dépasser une réponse exclusivement empirique","reason":"Distinguer ce que nous recevons des objets et ce que notre pouvoir de connaître apporte à leur organisation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"kant-penser-et-recevoir","code":"K02","author":"Kant","title":"Penser et recevoir","work":"Critique de la raison pure","locator":"Logique transcendantale, introduction, I · A 51 / B 75","quote":"Des pensées sans contenu sont vides, des intuitions sans concepts sont aveugles.","notions":["science","raison","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Suffit-il de penser avec rigueur ou de bien observer pour connaître ?"},{"function":"L’affirmation","sentence":"Kant affirme que notre connaissance exige l’union des concepts et des intuitions sensibles."},{"function":"Les concepts","sentence":"Le concept permet de penser un objet, tandis que l’intuition le donne à notre sensibilité."},{"function":"La raison","sentence":"Une pensée sans objet reste vide, mais ce qui est reçu sans être pensé ne devient pas encore une connaissance de cet objet."},{"function":"L’exemple","sentence":"Recueillir des observations sans les organiser ne remplace pas une théorie, et une théorie sans rapport à des objets ne suffit pas davantage."},{"function":"La portée","sentence":"Il faut donc articuler réception et pensée, sans réduire la connaissance à l’une de ces deux activités."}],"uses":[{"subject":"Une expérience sans théorie nous apprend-elle quelque chose ?","function":"Montrer le besoin d’une organisation conceptuelle","reason":"Après avoir reconnu la valeur de l’observation, expliquer pourquoi recevoir des données ne suffit pas à les comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"},{"subject":"Une théorie sans expérience nous apprend-elle quelque chose ?","function":"Fixer une condition de la connaissance des objets","reason":"Limiter la puissance de la construction intellectuelle en exigeant qu’un objet puisse correspondre aux concepts.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"}]},{"id":"kant-bien-questionner","code":"K03","author":"Kant","title":"Apprendre à questionner","work":"Critique de la raison pure","locator":"Logique transcendantale, introduction, III · A 58 / B 82–83","quote":"C'est déjà une grande et nécessaire preuve de sagesse ou d'intelligence que de savoir quelles questions on peut raisonnablement poser.","notions":["raison","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Toute question mérite-t-elle qu’on cherche immédiatement à y répondre ?"},{"function":"L’affirmation","sentence":"Kant fait de l’examen des questions une marque de sagesse."},{"function":"Les concepts","sentence":"Une question raisonnable doit avoir un sens et ne pas présupposer ce qu’il faudrait justement établir."},{"function":"La raison","sentence":"Si sa formulation impose une supposition absurde, répondre risque de nous enfermer dans cette erreur."},{"function":"L’exemple","sentence":"Demander la couleur du nombre sept suppose ainsi qu’un nombre puisse posséder une propriété sensible."},{"function":"La portée","sentence":"Bien raisonner commence donc parfois par corriger la question, plutôt que par choisir entre les réponses qu’elle semble autoriser."}],"uses":[{"subject":"Peut-on apprendre à penser ?","function":"Définir un premier exercice du jugement","reason":"Avant la recherche d’une réponse, faire de l’examen des présupposés de la question un apprentissage de la pensée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"La raison peut-elle tout expliquer ?","function":"Examiner la légitimité de la demande","reason":"Avant de conclure à l’impuissance de la raison, vérifier que ce qu’on lui demande d’expliquer est formulé de manière cohérente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"}]},{"id":"kant-coherence-et-verite","code":"K04","author":"Kant","title":"La cohérence ne suffit pas","work":"Critique de la raison pure","locator":"Logique transcendantale, introduction, III · A 59–60 / B 84","quote":"Car quand bien même une connaissance parvient à concorder pleinement avec la forme logique, c'est-à-dire à ne pas se contredire elle-même, elle peut cependant toujours contredire l'objet.","notions":["verite","raison","science"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Une pensée sans contradiction est-elle nécessairement vraie ?"},{"function":"L’affirmation","sentence":"Kant affirme qu’une connaissance logiquement cohérente peut pourtant ne pas correspondre à son objet."},{"function":"Les concepts","sentence":"La cohérence concerne l’accord des propositions entre elles, tandis que la vérité engage leur rapport à ce dont elles parlent."},{"function":"La raison","sentence":"Les règles logiques permettent d’écarter certaines erreurs, mais elles ne fournissent pas à elles seules le contenu vrai."},{"function":"L’exemple","sentence":"Un récit inventé peut être parfaitement cohérent sans que les événements qu’il raconte aient eu lieu."},{"function":"La portée","sentence":"La logique demeure donc nécessaire à la recherche du vrai, sans constituer un critère suffisant de toute vérité."}],"uses":[{"subject":"La cohérence d’une pensée suffit-elle à garantir sa vérité ?","function":"Distinguer une condition nécessaire d’une condition suffisante","reason":"Après avoir montré la nécessité d’éviter la contradiction, établir qu’une pensée cohérente peut encore manquer son objet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"La rigueur d’un raisonnement suffit-elle pour garantir la vérité ?","function":"Limiter la portée de la seule rigueur formelle","reason":"Séparer la validité de l’enchaînement logique et la vérité des affirmations auxquelles il s’applique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=88","sourceLabel":"Recueil académique · p. 88"}]},{"id":"kant-sens-et-jugement","code":"K05","author":"Kant","title":"Les sens ne jugent pas","work":"Critique de la raison pure","locator":"Dialectique transcendantale, introduction, I · A 293–294 / B 350","quote":"On peut donc assurément dire avec justesse que les sens ne commettent pas d'erreur, non pas toutefois parce qu'ils jugent toujours de façon juste, mais parce qu'ils ne portent aucun jugement.","notions":["verite","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Les sens nous trompent-ils lorsqu’une perception nous conduit à l’erreur ?"},{"function":"L’affirmation","sentence":"Kant distingue ce que les sens donnent et le jugement que nous portons sur cette donnée."},{"function":"Les concepts","sentence":"Sentir est recevoir une représentation, tandis que juger consiste à affirmer quelque chose d’un objet."},{"function":"La raison","sentence":"L’erreur apparaît lorsque nous attribuons à l’objet ce que sa seule apparence ne permet pas d’établir."},{"function":"L’exemple","sentence":"Un bâton plongé dans l’eau paraît brisé, mais c’est affirmer qu’il est réellement brisé qui constitue l’erreur."},{"function":"La portée","sentence":"Il faut donc examiner notre interprétation des perceptions, sans prétendre que toute apparence nous livre immédiatement la réalité."}],"uses":[{"subject":"L’ignorance est-elle la seule cause de nos erreurs ?","function":"Identifier une erreur d’interprétation","reason":"Après le manque de connaissances, examiner la confusion entre une apparence sensible et un jugement sur l’objet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer voir et affirmer","reason":"Montrer qu’un témoignage des sens doit être interprété et que la confiance dans la vue ne dispense pas de juger.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"kant-illusion-et-lucidite","code":"K06","author":"Kant","title":"Comprendre une illusion ne l’abolit pas","work":"Critique de la raison pure","locator":"Dialectique transcendantale, introduction, I · A 297 / B 353–354","quote":"L'apparence transcendantale, au contraire, ne cesse pas, quand bien même on l'a découverte et que la critique transcendantale en a fait voir clairement le néant (par exemple, l'apparence qui se trouve contenue dans la proposition : le monde doit nécessairement posséder un commencement chronologique).","notions":["verite","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Comprendre pourquoi nous sommes trompés fait-il disparaître toute illusion ?"},{"function":"L’affirmation","sentence":"Kant affirme que certaines apparences produites par la raison persistent après leur explication."},{"function":"Les concepts","sentence":"L’apparence transcendantale consiste à prendre une exigence de notre pensée pour une propriété nécessaire des choses elles-mêmes."},{"function":"La raison","sentence":"Le besoin de donner à nos explications un terme définitif nous pousse ainsi à dépasser ce que nous pouvons connaître."},{"function":"L’exemple","sentence":"Nous sommes tentés d’affirmer un premier commencement du monde parce que la remontée des causes nous paraît devoir s’arrêter."},{"function":"La portée","sentence":"La critique peut empêcher notre adhésion à cette apparence sans supprimer la tendance qui la produit."}],"uses":[{"subject":"Dissiper une illusion, est-ce seulement corriger une erreur ?","function":"Distinguer la persistance de l’apparence et l’adhésion","reason":"Après la rectification d’un jugement faux, montrer pourquoi une illusion peut continuer à solliciter notre pensée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"L’ignorance est-elle la seule cause de nos erreurs ?","function":"Mettre en évidence une tendance de la raison","reason":"Montrer que certaines erreurs naissent d’un besoin d’explication absolue, et non du seul manque d’informations.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"kant-concevoir-et-exister","code":"K07","author":"Kant","title":"Concevoir n’est pas faire exister","work":"Critique de la raison pure","locator":"Dialectique transcendantale, idéal de la raison pure, section IV · A 598–599 / B 626–627","quote":"Être n'est à l'évidence pas un prédicat réel, c'est-à-dire un concept de quelque chose qui puisse s'ajouter au concept d'une chose.","notions":["raison","religion","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Peut-on établir l’existence d’une chose en analysant seulement son concept ?"},{"function":"L’affirmation","sentence":"Kant refuse de traiter l’existence comme une propriété ajoutée à la définition d’une chose."},{"function":"Les concepts","sentence":"Un prédicat réel désigne ici une détermination du contenu du concept, et non le fait que son objet existe."},{"function":"La raison","sentence":"Dire qu’une chose existe ne complète donc pas sa description, mais pose qu’un objet correspond à cette description."},{"function":"L’exemple","sentence":"Cent pièces réelles n’ont pas une propriété descriptive de plus que cent pièces possibles, même si leur possession change ma fortune."},{"function":"La portée","sentence":"La pensée du possible ne suffit donc pas à prouver l’existence, sans que cette critique démontre l’inexistence de ce qu’elle vise."}],"uses":[{"subject":"La raison suffit-elle à connaître le réel ?","function":"Distinguer la possibilité pensée et l’existence","reason":"Après la construction d’un concept cohérent, montrer pourquoi il reste à établir que son objet existe.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Est-il déraisonnable de croire en Dieu ?","function":"Délimiter la portée d’une preuve rationnelle","reason":"Examiner l’échec d’une preuve tirée du seul concept de Dieu, sans transformer cet échec en démonstration de son inexistence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"}]},{"id":"kant-raison-et-libre-critique","code":"K08","author":"Kant","title":"La raison doit accepter la critique","work":"Critique de la raison pure","locator":"Discipline de la raison pure, section II · A 738–739 / B 766–767","quote":"La raison doit, dans toutes ses entreprises, se soumettre à la critique, et elle ne peut par aucun interdit attenter à la liberté de cette dernière sans se nuire à elle-même et sans attirer sur elle un soupçon qui lui est dommageable.","notions":["raison","liberte","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"La raison peut-elle protéger son autorité en interdisant qu’on la conteste ?"},{"function":"L’affirmation","sentence":"Kant affirme que la raison se nuit lorsqu’elle soustrait ses entreprises à la critique."},{"function":"Les concepts","sentence":"Critiquer signifie ici examiner les raisons d’une affirmation, et non la rejeter par principe."},{"function":"La raison","sentence":"Une interdiction empêche l’épreuve des arguments et rend suspecte l’autorité qui refuse de s’y soumettre."},{"function":"L’exemple","sentence":"Une théorie qui répond aux objections par la censure ne montre pas pourquoi ses conclusions devraient être admises."},{"function":"La portée","sentence":"La liberté de la critique appartient donc à l’exercice de la raison, sans rendre toutes les objections également fondées."}],"uses":[{"subject":"Une théorie scientifique doit-elle se prémunir contre toute critique ?","function":"Distinguer la défense d’une théorie et sa mise à l’abri","reason":"Après avoir reconnu la nécessité de défendre des résultats, montrer pourquoi l’interdiction des objections compromet leur justification.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Montrer une condition publique de l’examen rationnel","reason":"Après l’indépendance intérieure, examiner le rôle de la liberté d’exposer et de discuter les objections.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"kant-persuasion-et-fondement","code":"K09","author":"Kant","title":"Être persuadé ne suffit pas","work":"Critique de la raison pure","locator":"Canon de la raison pure, section III · A 820–821 / B 848–849","quote":"La persuasion est une simple apparence, parce que le fondement du jugement, qui réside uniquement dans le sujet, est tenu pour objectif.","notions":["verite","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"La force avec laquelle je crois une proposition suffit-elle à la justifier ?"},{"function":"L’affirmation","sentence":"Kant appelle persuasion l’adhésion qui prend un fondement seulement personnel pour une raison objective."},{"function":"Les concepts","sentence":"Le fondement subjectif explique pourquoi je suis convaincu, tandis qu’une raison objective doit pouvoir justifier le jugement pour d’autres."},{"function":"La raison","sentence":"L’intensité de mon sentiment ne transforme pas ce qui agit sur moi en preuve de ce que j’affirme."},{"function":"L’exemple","sentence":"Une rumeur peut me sembler certaine parce qu’elle confirme mes peurs, sans que cette peur établisse sa vérité."},{"function":"La portée","sentence":"Examiner une certitude exige donc de distinguer ses causes personnelles et ses raisons partageables, sans confondre toute conviction avec une illusion."}],"uses":[{"subject":"La certitude est-elle une garantie de vérité ?","function":"Distinguer l’assurance personnelle et la justification","reason":"Après avoir décrit la force d’une certitude, examiner si ses raisons valent au-delà de celui qui l’éprouve.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"La conviction d’avoir raison fait-elle obstacle au dialogue ?","function":"Identifier une fermeture possible de la discussion","reason":"Montrer comment prendre ses raisons personnelles pour des preuves suffisantes peut empêcher l’examen des objections.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"}]},{"id":"kant-opinion-et-insuffisance","code":"K10","author":"Kant","title":"Une opinion consciente de ses limites","work":"Critique de la raison pure","locator":"Canon de la raison pure, section III · A 822 / B 850","quote":"L'opinion est une créance consciente d'être insuffisante subjectivement tout autant qu'objectivement.","notions":["verite","raison","science"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Avoir une opinion signifie-t-il nécessairement prétendre savoir ?"},{"function":"L’affirmation","sentence":"Kant définit l’opinion comme une adhésion consciente de son insuffisance."},{"function":"Les concepts","sentence":"La créance est le fait de tenir une proposition pour vraie, sans que cette adhésion soit toujours un savoir."},{"function":"La raison","sentence":"Dans l’opinion, les raisons disponibles ne suffisent ni à assurer pleinement celui qui juge ni à justifier le jugement pour chacun."},{"function":"L’exemple","sentence":"Un médecin peut envisager un diagnostic provisoire tout en reconnaissant que les examens nécessaires manquent encore."},{"function":"La portée","sentence":"Une opinion peut donc orienter une recherche si elle reconnaît ses limites, sans acquérir pour autant la valeur d’un savoir."}],"uses":[{"subject":"L’opinion a-t-elle nécessairement tort ?","function":"Distinguer l’insuffisance et la fausseté","reason":"Après la critique des opinions assurées, montrer qu’un jugement provisoire peut reconnaître ses limites sans être nécessairement faux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Le savant doit-il fuir l’incertitude ?","function":"Donner une place au jugement provisoire","reason":"Montrer que reconnaître l’insuffisance de ses raisons permet de poursuivre la recherche au lieu d’affirmer prématurément un savoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"}]},{"id":"kant-bonheur-et-totalite","code":"K11","author":"Kant","title":"Le bonheur et la totalité des désirs","work":"Critique de la raison pure","locator":"Canon de la raison pure, section II · A 806 / B 834","quote":"Le bonheur est la satisfaction de toutes nos inclinations (aussi bien extensive, à l'égard de leur variété, qu'intensive, quant à leur degré, et même protensive, du point de vue de leur durée).","notions":["bonheur","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Être heureux consiste-t-il à obtenir une satisfaction particulière ?"},{"function":"L’affirmation","sentence":"Kant définit le bonheur par la satisfaction de l’ensemble de nos inclinations."},{"function":"Les concepts","sentence":"Cette totalité concerne la variété de nos désirs, l’intensité de leur satisfaction et sa durée."},{"function":"La raison","sentence":"Un plaisir isolé ne suffit donc pas à garantir que les autres dimensions de notre vie nous satisfassent."},{"function":"L’exemple","sentence":"Réussir un projet longtemps désiré peut coexister avec la solitude, l’inquiétude ou la peur de perdre cette réussite."},{"function":"La portée","sentence":"Cette définition explique l’exigence du bonheur, sans prouver que nous sachions toujours quels moyens permettraient de l’atteindre."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Distinguer une satisfaction et le bonheur","reason":"Après avoir reconnu la joie d’un désir comblé, élargir l’examen à l’ensemble des inclinations et à leur durée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Le bonheur est-il inaccessible à l’homme ?","function":"Préciser la difficulté de l’idéal","reason":"Montrer pourquoi la totalité, l’intensité et la durée des satisfactions rendent le bonheur plus exigeant qu’un plaisir momentané.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"kant-apprendre-a-philosopher","code":"K12","author":"Kant","title":"Apprendre à philosopher","work":"Critique de la raison pure","locator":"Architectonique de la raison pure · A 838 / B 866","quote":"On peut seulement apprendre à philosopher, c'est-à-dire à exercer le talent de la raison dans la mise en œuvre de ses principes universels à la faveur de certaines tentatives qui se présentent, même si se trouve toujours réservé le droit qu'a la raison d'examiner ces principes eux-mêmes quant à leurs sources, pour les confirmer ou les rejeter.","notions":["raison","verite","liberte"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Apprendre les pensées des philosophes suffit-il pour savoir philosopher ?"},{"function":"L’affirmation","sentence":"Kant distingue l’apprentissage d’un système et l’exercice personnel de la raison."},{"function":"Les concepts","sentence":"Philosopher consiste à mettre des principes à l’épreuve tout en conservant le droit de les examiner eux-mêmes."},{"function":"La raison","sentence":"Celui qui ne fait que répéter une doctrine dépend encore de la raison d’autrui, même s’il la connaît parfaitement."},{"function":"L’exemple","sentence":"Retenir une démonstration ne dispense pas de comprendre ses raisons ni d’examiner l’objection qui pourrait la fragiliser."},{"function":"La portée","sentence":"Les œuvres peuvent donc former notre jugement, à condition de devenir des occasions de penser plutôt que des autorités à réciter."}],"uses":[{"subject":"Peut-on apprendre à penser ?","function":"Définir les conditions d’un apprentissage autonome","reason":"Après la transmission des connaissances, montrer que l’élève doit pouvoir examiner les principes et non seulement répéter les conclusions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Peut-on être philosophe sans être savant ?","function":"Distinguer l’érudition et l’exercice du jugement","reason":"Montrer que l’accumulation des doctrines ne suffit pas à philosopher, sans conclure que les connaissances seraient inutiles.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=146","sourceLabel":"Recueil académique · p. 146"}]},{"id":"kant-juger-le-particulier","code":"K13","author":"Kant","title":"Juger le cas particulier","work":"Critique de la faculté de juger","locator":"Introduction publiée, IV","quote":"La faculté de juger en général est le pouvoir de penser le particulier comme compris sous l'universel.","notions":["raison","science"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Juger consiste-t-il seulement à appliquer une règle déjà connue ?"},{"function":"L’affirmation","sentence":"Kant définit le jugement comme le pouvoir de penser un cas particulier sous une règle générale."},{"function":"Les concepts","sentence":"Le particulier est ce cas singulier, tandis que l’universel est la règle ou le principe sous lequel nous le comprenons."},{"function":"La raison","sentence":"Mais nous pouvons soit disposer de cette règle, soit devoir la chercher à partir du cas rencontré."},{"function":"L’exemple","sentence":"Identifier un triangle grâce à sa définition diffère ainsi de chercher une régularité parmi des phénomènes encore mal connus."},{"function":"La portée","sentence":"Juger demande donc tantôt une application, tantôt une recherche, et ne se réduit pas toujours à répéter une règle."}],"uses":[{"subject":"Peut-on apprendre à penser ?","function":"Distinguer deux exercices du jugement","reason":"Après l’apprentissage des règles, montrer que penser exige aussi de chercher celle qui convient lorsqu’elle n’est pas donnée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"L’expérience nous instruit-elle ?","function":"Expliquer le travail accompli sur les cas","reason":"Montrer que rencontrer des faits devient instructif lorsque le jugement cherche une règle qui permette de les comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"kant-plaire-sans-posseder","code":"K14","author":"Kant","title":"Plaire sans vouloir posséder","work":"Critique de la faculté de juger","locator":"§ 5 · définition du beau déduite du premier moment","quote":"Le goût est la faculté de juger un objet ou un mode de représentation par l'intermédiaire de la satisfaction ou du déplaisir, de manière désintéressée.","notions":["art"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Apprécier une beauté revient-il à désirer posséder ce qui nous plaît ?"},{"function":"L’affirmation","sentence":"Kant distingue le jugement de goût et la satisfaction liée à un intérêt pour l’objet."},{"function":"Les concepts","sentence":"Le désintéressement signifie ici que le plaisir ne dépend pas du désir de posséder l’objet ou d’en tirer avantage."},{"function":"La raison","sentence":"Je peux ainsi prendre plaisir à sa représentation sans me demander ce que son existence m’apporte."},{"function":"L’exemple","sentence":"Admirer la forme d’un palais ne revient pas à vouloir y habiter ni à approuver les dépenses de son propriétaire."},{"function":"La portée","sentence":"Le jugement de goût peut donc être désintéressé sans être indifférent, puisque la beauté nous procure précisément une satisfaction."}],"uses":[{"subject":"La valeur de l’art réside-t-elle dans son inutilité ?","function":"Distinguer le désintéressement et l’absence de valeur","reason":"Après la recherche d’une utilité, montrer qu’une satisfaction peut avoir une valeur sans dépendre d’un avantage à obtenir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"Beauté et utilité sont-elles incompatibles ?","function":"Distinguer deux façons d’apprécier le même objet","reason":"Montrer qu’un objet peut être utile, tandis que le plaisir pris à sa beauté ne dépend pas de cet usage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"kant-beau-et-universalite","code":"K15","author":"Kant","title":"Un plaisir qui demande à être partagé","work":"Critique de la faculté de juger","locator":"§ 9 · définition du beau déduite du deuxième moment","quote":"Est beau ce qui plaît universellement sans concept.","notions":["art","raison"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Dire qu’une chose est belle signifie-t-il seulement qu’elle me plaît personnellement ?"},{"function":"L’affirmation","sentence":"Kant affirme que le jugement de beauté prétend à un plaisir partageable par tous sans démonstration par concepts."},{"function":"Les concepts","sentence":"L’universalité est ici une exigence d’accord, et non le constat que chacun apprécie effectivement le même objet."},{"function":"La raison","sentence":"En disant beau plutôt qu’agréable pour moi, je sollicite l’adhésion d’autrui sans pouvoir l’imposer par une preuve."},{"function":"L’exemple","sentence":"Deux visiteurs peuvent discuter de la beauté d’un tableau alors qu’ils ne discuteraient pas de la même manière d’une préférence pour une saveur."},{"function":"La portée","sentence":"Le goût n’est donc ni un simple caprice privé ni une connaissance démontrable, et les désaccords ne disparaissent pas pour autant."}],"uses":[{"subject":"L’art est-il une affaire de goût personnel ?","function":"Dépasser l’opposition entre caprice et preuve","reason":"Après la diversité des préférences, montrer qu’un jugement esthétique peut réclamer un accord sans devenir une démonstration.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Peut-on démontrer qu’une œuvre d’art est belle ?","function":"Distinguer l’exigence d’accord et la preuve","reason":"Montrer que demander l’adhésion d’autrui ne suppose pas qu’on puisse déduire la beauté de l’œuvre à partir d’un concept.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=88","sourceLabel":"Recueil académique · p. 88"}]},{"id":"kant-beau-sans-recette","code":"K16","author":"Kant","title":"La beauté n’a pas de recette","work":"Critique de la faculté de juger","locator":"§ 17 · De l’idéal de la beauté","quote":"Il ne peut y avoir nulle règle objective du goût qui détermine par concepts ce qui est beau.","notions":["art","raison"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Une définition permettrait-elle de décider automatiquement de ce qui est beau ?"},{"function":"L’affirmation","sentence":"Kant refuse l’existence d’une règle objective qui déduirait la beauté à partir de concepts."},{"function":"Les concepts","sentence":"Une telle règle devrait imposer le jugement de goût comme une conclusion démontrée."},{"function":"La raison","sentence":"Or le plaisir esthétique doit être éprouvé par le sujet et ne peut être remplacé par un raisonnement sur des propriétés."},{"function":"L’exemple","sentence":"Connaître les proportions d’un bâtiment ne force pas à trouver sa façade belle."},{"function":"La portée","sentence":"On peut donc éduquer et discuter le goût sans posséder une formule qui dicterait nécessairement l’appréciation de chacun."}],"uses":[{"subject":"Faut-il renoncer à définir le beau ?","function":"Distinguer une réflexion et une règle de décision","reason":"Après le besoin de préciser la beauté, refuser qu’une définition dispense de l’expérience du jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Peut-on prouver qu’une œuvre d’art est belle ?","function":"Limiter la portée des arguments démonstratifs","reason":"Montrer que l’analyse des propriétés de l’œuvre peut éclairer le regard sans contraindre le plaisir comme une conclusion logique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=88","sourceLabel":"Recueil académique · p. 88"}]},{"id":"kant-sublime-et-resistance","code":"K17","author":"Kant","title":"Un plaisir qui résiste aux sens","work":"Critique de la faculté de juger","locator":"Remarque générale après le § 29 · exposition des jugements esthétiques réfléchissants","quote":"Est sublime ce qui plaît immédiatement à travers la résistance qu'il oppose à l'intérêt des sens.","notions":["nature","raison","art"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Comment pouvons-nous éprouver une satisfaction devant ce qui contrarie notre sensibilité ?"},{"function":"L’affirmation","sentence":"Kant distingue le sublime d’un plaisir qui satisferait immédiatement les sens."},{"function":"Les concepts","sentence":"Le sublime fait éprouver une résistance sensible, puis révèle dans l’esprit une capacité qui ne se mesure pas à cette résistance."},{"function":"La raison","sentence":"Face à une puissance naturelle, notre faiblesse physique peut ainsi faire ressortir une destination rationnelle qui ne se réduit pas à la force."},{"function":"L’exemple","sentence":"Observer une tempête depuis un lieu sûr peut susciter ce sentiment mêlé de recul et d’élévation."},{"function":"La portée","sentence":"Le sublime n’est donc pas le simple charme d’un spectacle, et il ne suppose ni de rechercher le danger ni d’aimer souffrir."}],"uses":[{"subject":"Faut-il prendre la nature pour modèle ?","function":"Distinguer puissance naturelle et valeur rationnelle","reason":"Après l’admiration de la nature, montrer que sa puissance peut révéler une exigence humaine qui ne consiste pas à l’imiter.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"},{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Distinguer satisfaction esthétique et agrément immédiat","reason":"Introduire, à partir de l’analyse du sublime naturel, la possibilité d’une satisfaction qui passe par une résistance sensible, sans assimiler toute œuvre au sublime.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"kant-savoir-et-savoir-faire","code":"K18","author":"Kant","title":"Savoir n’est pas encore savoir faire","work":"Critique de la faculté de juger","locator":"§ 43 · De l’art en général","quote":"Seul ce que l'on n'a pas aussitôt l'habileté de faire du simple fait qu'on le connaît de la manière la plus parfaite relève de l'art.","notions":["art","technique","travail"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Connaître parfaitement une manière de faire suffit-il pour savoir la réaliser ?"},{"function":"L’affirmation","sentence":"Kant distingue le savoir théorique et l’habileté pratique que requiert l’art."},{"function":"Les concepts","sentence":"L’art désigne ici un savoir-faire, dans un sens plus large que les seuls beaux-arts."},{"function":"La raison","sentence":"La connaissance du résultat recherché ne donne pas nécessairement la capacité de le produire."},{"function":"L’exemple","sentence":"Décrire avec précision une bonne chaussure ne rend pas capable de la fabriquer."},{"function":"La portée","sentence":"La pratique exige donc une habileté propre, sans que cela rende les connaissances inutiles à celui qui apprend un métier ou un art."}],"uses":[{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Reconnaître d’abord une dimension pratique irréductible","reason":"Avant de chercher ce qui distingue l’artiste, établir qu’une connaissance théorique ne remplace pas l’habileté de produire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"},{"subject":"L’art s’apprend-il ?","function":"Préciser ce qui doit être appris","reason":"Distinguer l’acquisition d’informations et la formation d’une habileté par l’exercice, sans prétendre que toute création se réduise à cette habileté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}]},{"id":"kant-genie-et-regles","code":"K19","author":"Kant","title":"Créer des règles par l’œuvre","work":"Critique de la faculté de juger","locator":"§ 46 · Les beaux-arts sont les arts du génie","quote":"Le génie est le talent (don naturel) qui donne à l'art ses règles.","notions":["art","nature","technique"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"L’artiste crée-t-il seulement en appliquant une méthode déjà disponible ?"},{"function":"L’affirmation","sentence":"Kant définit le génie comme un talent qui donne à l’art ses règles."},{"function":"Les concepts","sentence":"Ces règles ne sont pas une recette transmise avant l’œuvre, mais ce qui devient exemplaire à travers une création originale."},{"function":"La raison","sentence":"Une œuvre du génie ouvre ainsi une possibilité que les autres peuvent explorer sans simplement la copier."},{"function":"L’exemple","sentence":"Un poème peut inventer une manière d’associer rythme et images dont d’autres auteurs apprendront à leur tour."},{"function":"La portée","sentence":"Le génie ne se réduit donc pas à l’application technique, sans dispenser l’artiste du travail, de l’apprentissage ou du jugement."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Distinguer l’apprentissage et la création exemplaire","reason":"Après la valeur formatrice des modèles, montrer que l’originalité artistique ne consiste pas à reproduire leurs résultats.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il recourir à la notion d’inspiration pour rendre compte de la production artistique ?","function":"Donner un contenu précis au don créateur","reason":"Expliquer la nouveauté des règles par l’œuvre, sans transformer l’inspiration en absence de travail ou en intervention mystérieuse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"kant-art-et-naturel","code":"K20","author":"Kant","title":"L’art et l’apparence du naturel","work":"Critique de la faculté de juger","locator":"§ 45 · Les beaux-arts et l’apparence de la nature","quote":"La nature était belle lorsqu'en même temps elle avait l'apparence de l'art ; et l'art ne peut être appelé beau que si nous sommes conscients qu'il s'agit d'art et que celui-ci prend cependant pour nous l'apparence de la nature.","notions":["art","nature","technique"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Une œuvre doit-elle montrer la contrainte du travail qui l’a rendue possible ?"},{"function":"L’affirmation","sentence":"Kant affirme que le bel art doit paraître naturel tout en restant reconnu comme de l’art."},{"function":"Les concepts","sentence":"Le naturel désigne ici une liberté apparente à l’égard des règles, et non l’absence de fabrication."},{"function":"La raison","sentence":"Si la méthode s’impose comme une contrainte visible, l’œuvre semble exécutée mécaniquement plutôt que librement composée."},{"function":"L’exemple","sentence":"Un vers très travaillé peut sembler aller de soi sans que le lecteur ignore qu’un poète l’a composé."},{"function":"La portée","sentence":"Le naturel peut donc être un effet de l’art, sans se confondre avec une tromperie qui ferait passer l’œuvre pour un objet naturel."}],"uses":[{"subject":"L’art s’apprend-il ?","function":"Distinguer l’effort de formation et son effet sensible","reason":"Après la nécessité du travail, montrer que la réussite peut consister à ne pas donner l’impression d’une application laborieuse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"Faut-il prendre la nature pour modèle ?","function":"Préciser le sens d’un modèle naturel pour l’art","reason":"Montrer que l’artiste peut rechercher une apparence de liberté plutôt que copier les formes des objets naturels.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"kant-beaute-de-la-representation","code":"K21","author":"Kant","title":"La beauté de la représentation","work":"Critique de la faculté de juger","locator":"§ 48 · Du rapport du génie au goût","quote":"Une beauté naturelle est une belle chose ; la beauté artistique est une belle représentation d'une chose.","notions":["art","nature"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"La beauté d’une œuvre exige-t-elle que son sujet soit lui-même beau ?"},{"function":"L’affirmation","sentence":"Kant distingue une belle chose et la belle représentation d’une chose."},{"function":"Les concepts","sentence":"La beauté naturelle concerne l’objet considéré, tandis que la beauté artistique engage la manière de le présenter."},{"function":"La raison","sentence":"La valeur esthétique d’une représentation ne se déduit donc pas de l’agrément que procurerait son sujet dans la réalité."},{"function":"L’exemple","sentence":"Une peinture peut représenter avec force un visage marqué par l’âge sans chercher à l’embellir."},{"function":"La portée","sentence":"L’art peut ainsi représenter des choses déplaisantes, sans que toute représentation de la laideur devienne pour autant une belle œuvre."}],"uses":[{"subject":"La laideur peut-elle intéresser l’artiste ?","function":"Dissocier la valeur de l’œuvre et l’agrément du sujet","reason":"Après l’association spontanée de l’art et du beau, montrer qu’une chose déplaisante peut recevoir une belle représentation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"L’œuvre d’art est-elle nécessairement belle ?","function":"Préciser ce qui est jugé beau","reason":"Distinguer la beauté de la représentation et celle de son sujet, avant de discuter les œuvres qui refusent elles-mêmes la beauté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}]},{"id":"kant-vivant-et-machine","code":"K22","author":"Kant","title":"Le vivant et la machine","work":"Critique de la faculté de juger","locator":"§ 65 · Les choses en tant que fins naturelles","quote":"Un être organisé n'est donc pas simplement une machine, étant donné que la machine a exclusivement la force motrice ; mais il possède en soi une force formatrice qu'il communique aux matières qui n'en disposent pas (il les organise) : c'est donc une force formatrice qui se propage et qui ne peut être expliquée uniquement par le pouvoir moteur (par le mécanisme).","notions":["nature","science","technique"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Comprendre le vivant revient-il à décrire une machine particulièrement complexe ?"},{"function":"L’affirmation","sentence":"Kant distingue la force motrice d’une machine et la force formatrice d’un être organisé."},{"function":"Les concepts","sentence":"Le vivant ne se borne pas à transmettre des mouvements, puisqu’il assimile des matières et contribue à sa propre formation."},{"function":"La raison","sentence":"Dans une machine, les pièces ne produisent pas normalement les autres pièces, alors que l’organisation vivante entretient les conditions de son activité."},{"function":"L’exemple","sentence":"Un arbre grandit en organisant les matières qu’il reçoit, tandis qu’une montre ne fabrique pas elle-même ses rouages."},{"function":"La portée","sentence":"Cette distinction indique une difficulté du modèle mécanique chez Kant, sans établir une limite définitive de la biologie contemporaine."}],"uses":[{"subject":"Un être vivant peut-il être assimilé à une machine ?","function":"Faire apparaître la limite de l’analogie","reason":"Après les ressemblances de fonctionnement, comparer la transmission d’un mouvement et la capacité de se former et de se maintenir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=64","sourceLabel":"Recueil académique · p. 64"},{"subject":"Faut-il, pour connaître le vivant, l’assimiler à une machine ?","function":"Distinguer l’utilité d’un modèle et sa suffisance","reason":"Reconnaître l’intérêt de l’explication mécanique, puis examiner ce qu’elle laisse à comprendre de l’organisation vivante.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=64","sourceLabel":"Recueil académique · p. 64"}]},{"id":"kant-organisme-et-reciprocite","code":"K23","author":"Kant","title":"Dans le vivant, fin et moyen","work":"Critique de la faculté de juger","locator":"§ 66 · La finalité interne dans les êtres organisés","quote":"Ce principe, qui constitue en même temps la définition des êtres organisés, est le suivant : un produit organisé de la nature est celui dans lequel tout est fin et réciproquement aussi moyen.","notions":["nature","science"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Peut-on comprendre un organe en l’isolant entièrement de l’organisme ?"},{"function":"L’affirmation","sentence":"Kant propose de juger l’être organisé comme un tout dans lequel les parties sont réciproquement fins et moyens."},{"function":"Les concepts","sentence":"Une partie contribue à l’existence des autres et du tout, dont elle reçoit elle-même les conditions de son maintien."},{"function":"La raison","sentence":"Cette réciprocité conduit à comprendre chaque organe à partir de l’organisation à laquelle il participe."},{"function":"L’exemple","sentence":"Une feuille nourrit l’arbre dont les racines et les autres parties rendent possible sa propre croissance."},{"function":"La portée","sentence":"La finalité guide ici notre jugement sur le vivant, sans prouver qu’un créateur aurait consciemment conçu chaque détail de l’organisme."}],"uses":[{"subject":"Suffit-il de connaître la matière pour connaître le vivant ?","function":"Introduire la relation entre les parties et le tout","reason":"Après l’inventaire des constituants matériels, examiner leurs fonctions réciproques dans l’organisation de l’être vivant.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=134","sourceLabel":"Recueil académique · p. 134"},{"subject":"Le vivant est-il entièrement explicable ?","function":"Distinguer un principe de recherche et une explication acquise","reason":"Montrer que comprendre les organes par leurs relations guide l’étude, sans donner à lui seul l’explication de leur production.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=134","sourceLabel":"Recueil académique · p. 134"}]},{"id":"baudelaire-nature-et-signes","code":"B01","author":"Baudelaire","title":"La nature à interpréter","work":"Correspondances","locator":"v. 1–2 · p. 39","quote":"La Nature est un temple où de vivants piliers\nLaissent parfois sortir de confuses paroles;","notions":["nature","langage","art"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La nature nous livre-t-elle immédiatement ce qu’elle signifie ?"},{"function":"L’affirmation","sentence":"Le poème présente la nature comme un temple dont les paroles restent confuses."},{"function":"Les concepts","sentence":"Les piliers vivants rapprochent l’ordre naturel d’un lieu sacré, tandis que la parole suggère une présence à comprendre."},{"function":"La raison","sentence":"Mais cette parole demande une interprétation, puisque son sens ne se donne pas avec la netteté d’un message ordinaire."},{"function":"L’exemple","sentence":"Une forêt peut ainsi être perçue comme un ensemble de choses ou comme un paysage chargé de correspondances."},{"function":"La portée","sentence":"La poésie ouvre une autre attention au monde, sans démontrer que la nature possède littéralement un langage humain."}],"uses":[{"subject":"L’art peut-il nous apprendre à voir le monde autrement ?","function":"Déplacer notre manière de percevoir","reason":"Après la description des objets, montrer comment l’image poétique fait apparaître des relations que le regard habituel néglige.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il une interprétation du monde ?","function":"Distinguer interprétation et explication","reason":"Si l’on examine le sens prêté à la nature, distinguer la lecture de ses symboles et la connaissance scientifique de ses causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=11","sourceLabel":"Recueil académique · p. 11"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-art-et-temps","code":"B02","author":"Baudelaire","title":"L’œuvre exige plus de temps que la vie","work":"Le Guignon","locator":"v. 3–4 · p. 45","quote":"Bien qu’on ait du cœur à l’ouvrage,\nL’Art est long et le Temps est court.","notions":["art","temps","travail"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La bonne volonté suffit-elle à mener une œuvre à son accomplissement ?"},{"function":"L’affirmation","sentence":"Le poème oppose la longueur du travail artistique à la brièveté du temps disponible."},{"function":"Les concepts","sentence":"Avoir du cœur à l’ouvrage signifie s’y engager, sans disposer pour autant de toute la durée nécessaire."},{"function":"La raison","sentence":"L’artiste peut donc éprouver une disproportion entre son effort, l’exigence de son art et les limites de sa vie."},{"function":"L’exemple","sentence":"Un créateur peut consacrer des années à une œuvre sans lui donner encore la forme qu’il cherche."},{"function":"La portée","sentence":"La création fait ainsi rencontrer notre finitude, sans que la durée de l’effort garantisse à elle seule la valeur du résultat."}],"uses":[{"subject":"L’activité artistique est-elle un travail ?","function":"Mettre au jour l’effort de création","reason":"Après l’image de l’inspiration immédiate, faire apparaître la durée et la difficulté nécessaires à l’élaboration de l’œuvre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer l’engagement et la disponibilité du temps","reason":"Montrer que vouloir accomplir une œuvre n’abolit pas la limite de la durée dont nous disposons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-beaute-et-bien","code":"B03","author":"Baudelaire","title":"La beauté répond-elle du bien ?","work":"Hymne à la Beauté","locator":"v. 11–12 · p. 52","quote":"Tu sèmes au hasard la joie et les désastres,\nEt tu gouvernes tout et ne réponds de rien.","notions":["art","devoir"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Ce qui nous éblouit est-il nécessairement bon ?"},{"function":"L’affirmation","sentence":"La voix poétique s’adresse à une Beauté capable de produire aussi bien la joie que le désastre."},{"function":"Les concepts","sentence":"La beauté devient une puissance personnifiée dont l’efficacité ne s’accompagne d’aucune responsabilité morale."},{"function":"La raison","sentence":"Notre fascination peut donc nous soumettre à ce qui nous attire avant que nous ayons jugé ses effets."},{"function":"L’exemple","sentence":"Une forme admirable peut servir un discours violent sans perdre immédiatement son pouvoir de séduction."},{"function":"La portée","sentence":"L’expérience esthétique doit ainsi être distinguée de l’approbation morale, sans conclure que toute beauté serait mauvaise."}],"uses":[{"subject":"L’art nous rend-il meilleurs ?","function":"Contester le passage automatique du beau au bien","reason":"Après le pouvoir d’élévation prêté à l’art, examiner une fascination esthétique qui ne garantit pas une amélioration morale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"La beauté est-elle la seule fin de l’art ?","function":"Ouvrir l’examen de la responsabilité artistique","reason":"Une fois reconnue la puissance du beau, demander si cette puissance suffit à justifier ce que l’œuvre fait éprouver ou accepter.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-souvenir-et-presence","code":"B04","author":"Baudelaire","title":"Rendre le passé présent","work":"Le Balcon","locator":"v. 21–22 · p. 63","quote":"Je sais l’art d’évoquer les minutes heureuses,\nEt revis mon passé blotti dans tes genoux.","notions":["temps","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le souvenir rend-il présent ce qui a disparu ?"},{"function":"L’affirmation","sentence":"La voix poétique affirme son pouvoir d’évoquer et de revivre des instants heureux."},{"function":"Les concepts","sentence":"L’évocation est une activité de la mémoire, tandis que revivre dit l’intensité présente de ce rappel."},{"function":"La raison","sentence":"Les sensations et la proximité de l’être aimé semblent rendre au passé une présence que la chronologie lui refuse."},{"function":"L’exemple","sentence":"Un parfum familier peut faire renaître avec force l’atmosphère d’une rencontre ancienne."},{"function":"La portée","sentence":"La mémoire peut donc transformer notre expérience du présent, sans restituer matériellement l’événement ni abolir sa perte."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer le retour sensible et le retour réel","reason":"Après l’irréversibilité des événements, examiner la présence intérieure qu’un souvenir peut leur rendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Est-il possible de vivre au présent ?","function":"Montrer que le présent accueille le passé","reason":"Contester un présent réduit à l’instant isolé en analysant la manière dont le souvenir habite l’expérience actuelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-memoire-et-duree","code":"B05","author":"Baudelaire","title":"Une mémoire plus vieille que soi","work":"Spleen","locator":"LXXVI · v. 1 · p. 94","quote":"J’ai plus de souvenirs que si j’avais mille ans.","notions":["temps","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le poids d’une vie se mesure-t-il au nombre des années vécues ?"},{"function":"L’affirmation","sentence":"La voix poétique éprouve une mémoire plus chargée que ne le serait celle d’une existence millénaire."},{"function":"Les concepts","sentence":"L’hyperbole des mille ans oppose la durée comptable à l’accumulation intérieure des souvenirs."},{"function":"La raison","sentence":"Le passé ne demeure pas seulement derrière nous : il peut encombrer le présent et rendre chaque instant lourd de ce qui a été vécu."},{"function":"L’exemple","sentence":"Le poème compare ensuite le cerveau à un meuble rempli, puis à un caveau."},{"function":"La portée","sentence":"La mémoire transforme ainsi l’expérience du temps, sans que sa richesse garantisse une vie plus heureuse ou un savoir plus juste."}],"uses":[{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer âge et durée vécue","reason":"Après la mesure chronologique, examiner la densité du passé qui persiste dans le présent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"Pour se libérer du passé faut-il l’oublier ?","function":"Montrer le poids possible du souvenir","reason":"Avant de valoriser toute mémoire, examiner l’expérience d’une accumulation qui encombre le présent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-obscurite-et-memoire","code":"B06","author":"Baudelaire","title":"La nuit ne suffit pas à oublier","work":"Obsession","locator":"v. 9–10 · p. 97","quote":"Comme tu me plairais, ô nuit! sans ces étoiles\nDont la lumière parle un langage connu!","notions":["conscience","temps"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on échapper à ce qui nous habite en supprimant les signes du monde extérieur ?"},{"function":"L’affirmation","sentence":"La voix poétique désire une nuit privée des étoiles dont la lumière lui parle encore."},{"function":"Les concepts","sentence":"Le langage connu des étoiles désigne un monde qui réveille des significations et des souvenirs devenus douloureux."},{"function":"La raison","sentence":"Mais la fin du poème peuple aussi les ténèbres de figures disparues qui jaillissent du regard lui-même."},{"function":"L’exemple","sentence":"Fermer les yeux peut ainsi laisser revenir une image que la présence des choses ne suffit pas à expliquer."},{"function":"La portée","sentence":"La fuite du monde rencontre donc une mémoire intérieure, sans que cette expérience poétique établisse l’impossibilité de tout apaisement."}],"uses":[{"subject":"Peut-on se libérer du passé ?","function":"Montrer la limite d’une fuite extérieure","reason":"Après l’éloignement des lieux douloureux, examiner ce qui continue à revenir par la mémoire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"},{"subject":"Suis-je le mieux placé pour me connaître ?","function":"Interroger l’opacité de notre vie intérieure","reason":"Montrer qu’une pensée ou une image peut s’imposer à nous sans que nous maîtrisions ce qu’elle révèle de notre histoire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-monde-et-desir","code":"B07","author":"Baudelaire","title":"Quand le monde perd son attrait","work":"Le Goût du néant","locator":"v. 10 · p. 97","quote":"Le Printemps adorable a perdu son odeur!","notions":["bonheur","conscience","nature"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Suffit-il que le monde offre des plaisirs pour que nous puissions en jouir ?"},{"function":"L’affirmation","sentence":"Dans le poème, le printemps semble avoir perdu jusqu’à son odeur."},{"function":"Les concepts","sentence":"Le printemps représente le renouveau sensible, mais l’épuisement intérieur lui retire son pouvoir d’attirer."},{"function":"La raison","sentence":"Le monde n’a pas nécessairement cessé d’offrir ses biens : c’est la relation du sujet à ces biens qui s’est altérée."},{"function":"L’exemple","sentence":"Une fête peut demeurer animée et belle sans éveiller aucun plaisir chez celui qui la traverse dans le désenchantement."},{"function":"La portée","sentence":"Le bonheur suppose donc une capacité d’être affecté par ce qui arrive, sans réduire toute souffrance à une simple attitude volontaire."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Examiner la capacité de goûter les biens","reason":"Après la possession des objets souhaités, montrer que la satisfaction dépend aussi du rapport vivant que nous entretenons avec eux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"},{"subject":"De quel bonheur sommes-nous capables ?","function":"Distinguer la vie intérieure et sa maîtrise","reason":"Reconnaître le rôle de notre disposition sensible sans prétendre qu’il suffirait de décider d’être heureux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-douleur-et-transfiguration","code":"B08","author":"Baudelaire","title":"La douleur transforme ce qu’elle voit","work":"Alchimie de la douleur","locator":"v. 9–10 · p. 98","quote":"Par toi je change l’or en fer\nEt le paradis en enfers;","notions":["conscience","art"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Notre état intérieur peut-il modifier la valeur que le monde prend pour nous ?"},{"function":"L’affirmation","sentence":"La voix poétique attribue à un Hermès mystérieux la transformation de l’or en fer et du paradis en enfers."},{"function":"Les concepts","sentence":"Cette alchimie inverse la promesse d’enrichissement associée à la figure de Midas."},{"function":"La raison","sentence":"La douleur agit sur la représentation : ce qui pouvait apparaître précieux devient le signe d’un malheur."},{"function":"L’exemple","sentence":"Un paysage lumineux peut ainsi sembler funèbre à celui qui vient d’y perdre un être aimé."},{"function":"La portée","sentence":"Le poème montre une transformation du monde vécu, sans soutenir que la tristesse change matériellement la nature des choses."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer la part des affects dans la représentation","reason":"Après l’idée d’une pensée détachée des émotions, examiner la manière dont la douleur oriente ce qui est perçu et interprété.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"L’art est-il une forme de connaissance ?","function":"Reconnaître un savoir de l’expérience vécue","reason":"Montrer que l’image poétique rend intelligible la puissance de la douleur sans fournir une explication scientifique de ses causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"collection":"Les Fleurs du Mal","editionNote":"Le volume fourni porte « enfers » ; l’édition de 1861 consultée en ligne porte « enfer »."},{"id":"baudelaire-soi-et-conflit","code":"B09","author":"Baudelaire","title":"Être à la fois blessé et blessant","work":"L’Héautontimorouménos","locator":"v. 21–22 · p. 99","quote":"Je suis la plaie et le couteau!\nJe suis le soufflet et la joue!","notions":["conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le conflit intérieur suppose-t-il que deux personnes différentes s’affrontent en nous ?"},{"function":"L’affirmation","sentence":"La voix poétique s’identifie à la fois à la blessure et à l’instrument qui la produit."},{"function":"Les concepts","sentence":"La plaie et le couteau, puis le soufflet et la joue, réunissent dans un même sujet les positions opposées du patient et de l’agent."},{"function":"La raison","sentence":"L’image fait comprendre une souffrance dans laquelle celui qui éprouve le mal participe aussi à sa reprise."},{"function":"L’exemple","sentence":"Une personne peut ainsi se faire souffrir en se répétant une accusation qu’elle ne cesse de retourner contre elle-même."},{"function":"La portée","sentence":"Le sujet peut donc être divisé dans son rapport à soi, sans que cette image rende toute victime responsable de la violence subie."}],"uses":[{"subject":"Peut-on être en conflit avec soi-même ?","function":"Donner une forme précise à la division intérieure","reason":"Après l’unité de la personne, montrer comment un même sujet peut occuper des positions opposées dans son expérience de soi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"La conscience de soi est-elle trompeuse ?","function":"Interroger un rapport à soi qui se blesse","reason":"Examiner une conscience qui ne se contente pas de constater son état, mais peut entretenir une interprétation douloureuse de soi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-rencontre-et-possible","code":"B10","author":"Baudelaire","title":"L’amour qui aurait pu être","work":"À une passante","locator":"v. 13–14 · p. 114","quote":"Car j’ignore où tu fuis, tu ne sais où je vais,\nO toi que j’eusse aimée, ô toi qui le savais!","notions":["temps","bonheur","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on éprouver la perte d’une relation qui n’a jamais commencé ?"},{"function":"L’affirmation","sentence":"La voix poétique s’adresse à une inconnue disparue comme à celle qu’elle aurait pu aimer."},{"function":"Les concepts","sentence":"Le passé non réalisé de l’amour contraste avec l’affirmation d’un savoir attribué à la passante."},{"function":"La raison","sentence":"Le regard croisé suffit à faire naître un possible, mais ne donne ni connaissance de l’autre ni chemin pour la retrouver."},{"function":"L’exemple","sentence":"Dans la rue, la rencontre ne dure qu’un instant avant que leurs directions les séparent."},{"function":"La portée","sentence":"Une possibilité manquée peut ainsi marquer une vie réelle, sans que l’intensité de l’émotion prouve la réciprocité imaginée du sentiment."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Examiner le bonheur imaginé","reason":"Distinguer le bien réel d’une relation et la promesse que le désir projette sur une rencontre inconnue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"},{"subject":"Le désir est-il aveugle ?","function":"Distinguer rencontre et projection","reason":"Après la force révélatrice d’un regard, examiner le savoir réciproque que le désir imagine sans pouvoir le vérifier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-temps-et-jeu","code":"B11","author":"Baudelaire","title":"Un jeu dont le temps gagne les parties","work":"L’Horloge","locator":"v. 17–18 · p. 102","quote":"Souviens-toi que le Temps est un joueur avide\nQui gagne sans tricher, à tout coup! c’est la loi.","notions":["temps","liberte"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Pouvons-nous vaincre le temps en conduisant mieux notre vie ?"},{"function":"L’affirmation","sentence":"L’horloge personnifiée présente le temps comme un joueur dont la victoire est régulière."},{"function":"Les concepts","sentence":"L’image du jeu suggère un affrontement, mais l’absence de tricherie renvoie à une condition commune plutôt qu’à une injustice exceptionnelle."},{"function":"La raison","sentence":"Aucune habileté ne supprime l’écoulement de la durée ni la limite de la vie."},{"function":"L’exemple","sentence":"Organiser parfaitement une journée permet de mieux l’employer, sans empêcher qu’elle s’achève."},{"function":"La portée","sentence":"Le rappel de cette limite peut orienter notre usage du temps, sans imposer la conclusion que toute action serait inutile."}],"uses":[{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer organiser et abolir l’écoulement","reason":"Après les moyens de gagner du temps, montrer que l’efficacité ne supprime pas notre condition temporelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"},{"subject":"Faut-il toujours chercher à gagner du temps ?","function":"Interroger la fin de l’efficacité","reason":"Une fois reconnue la durée limitée de la vie, demander à quoi doit servir le temps rendu disponible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-ville-et-memoire","code":"B12","author":"Baudelaire","title":"La ville change, la mémoire demeure","work":"Le Cygne","locator":"I, v. 7–8 · p. 107","quote":"Le vieux Paris n’est plus (la forme d’une ville\nChange plus vite, hélas! que le cœur d’un mortel);","notions":["temps","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Changer le monde extérieur suffit-il à transformer ce que nous y vivons ?"},{"function":"L’affirmation","sentence":"Le poème oppose la transformation rapide de Paris à la lenteur des changements du cœur humain."},{"function":"Les concepts","sentence":"La ville désigne un lieu matériel, tandis que le cœur conserve les attachements et les pertes liés à ses anciennes formes."},{"function":"La raison","sentence":"Le sujet peut donc habiter simultanément une ville présente et celle que sa mémoire continue de lui rendre sensible."},{"function":"L’exemple","sentence":"Une rue reconstruite reste, pour un ancien habitant, le lieu d’une rencontre dont aucun bâtiment ne porte plus la trace."},{"function":"La portée","sentence":"Le changement matériel et le temps vécu suivent ainsi des rythmes différents, sans que la mémoire soit pour autant immobile."}],"uses":[{"subject":"Peut-on se libérer du passé ?","function":"Distinguer disparition matérielle et persistance intérieure","reason":"Après la transformation des lieux, montrer pourquoi leur effacement ne supprime pas immédiatement ce qu’ils représentent pour nous.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"},{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Faire apparaître la diversité des rythmes vécus","reason":"Opposer à la durée uniforme l’écart entre la vitesse du changement extérieur et celle des attachements.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-mort-et-consolation","code":"B13","author":"Baudelaire","title":"Une consolation qui aide à vivre","work":"La Mort des pauvres","locator":"v. 1 · p. 148","quote":"C’est la Mort qui console, hélas! et qui fait vivre;","notions":["religion","bonheur"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Ce qui met fin à la vie peut-il devenir l’objet d’une consolation pendant la vie ?"},{"function":"L’affirmation","sentence":"Le poème présente paradoxalement la Mort comme ce qui console les pauvres et leur donne la force de vivre."},{"function":"Les concepts","sentence":"La Mort personnifiée devient la promesse d’un repos et d’un accueil refusés dans leur existence présente."},{"function":"La raison","sentence":"L’espoir d’une fin de la misère peut ainsi soutenir ceux qui l’endurent, alors même que cette fin demeure inconnue."},{"function":"L’exemple","sentence":"La suite du poème évoque une auberge où il serait enfin possible de manger, de dormir et de s’asseoir."},{"function":"La portée","sentence":"Cette image permet d’examiner la fonction d’une espérance, sans prouver l’existence d’un au-delà ni présenter la mort comme un conseil."}],"uses":[{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Distinguer la fin redoutée et l’espérance de repos","reason":"Après la mort comme privation de vie, examiner la consolation que sa représentation peut offrir au sein d’une existence misérable.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"},{"subject":"La religion a-t-elle pour but de consoler les hommes ?","function":"Préciser ce que peut faire une espérance","reason":"Montrer comment une représentation de l’au-delà peut soutenir la vie, avant d’examiner si cette fonction épuise le sens de la religion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-plaisir-et-desir","code":"B14","author":"Baudelaire","title":"Le plaisir nourrit-il le désir ?","work":"Le Voyage","locator":"IV, v. 69 · p. 153","quote":"— La jouissance ajoute au désir de la force.","notions":["bonheur","liberte"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La satisfaction met-elle nécessairement fin au désir ?"},{"function":"L’affirmation","sentence":"Dans le récit du voyage, la jouissance est présentée comme ce qui accroît la force du désir."},{"function":"Les concepts","sentence":"La jouissance est la satisfaction éprouvée, tandis que le désir demeure un mouvement vers ce qui n’est pas encore obtenu."},{"function":"La raison","sentence":"Le plaisir peut entretenir ce mouvement en faisant souhaiter son retour ou une satisfaction plus intense."},{"function":"L’exemple","sentence":"Une expérience longtemps attendue peut ainsi susciter, une fois vécue, le désir de la recommencer autrement."},{"function":"La portée","sentence":"Satisfaire un désir ne signifie donc pas toujours l’éteindre, sans que tout plaisir doive nécessairement conduire à une poursuite sans limite."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Mettre en question l’extinction du manque","reason":"Après le plaisir d’obtenir l’objet souhaité, montrer que la satisfaction peut relancer le désir plutôt qu’installer un contentement durable.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"},{"subject":"Satisfaire ses désirs peut-il rendre malheureux ?","function":"Expliquer un renouvellement de la dépendance","reason":"Montrer comment le plaisir obtenu peut devenir l’exigence d’une répétition ou d’une intensification toujours nouvelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-douleur-et-dialogue","code":"B15","author":"Baudelaire","title":"Parler à sa douleur","work":"Recueillement","locator":"v. 1 · p. 200","quote":"Sois sage, ô ma Douleur, et tiens-toi plus tranquille.","notions":["conscience","liberte"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Faut-il supprimer une souffrance pour modifier le rapport que nous entretenons avec elle ?"},{"function":"L’affirmation","sentence":"La voix poétique s’adresse à sa Douleur comme à une compagne qu’elle cherche à apaiser."},{"function":"Les concepts","sentence":"La personnification distingue celui qui parle et ce qu’il éprouve, sans les rendre étrangers l’un à l’autre."},{"function":"La raison","sentence":"Mettre la douleur en mots peut ouvrir une distance qui ne se confond ni avec son effacement ni avec son déni."},{"function":"L’exemple","sentence":"La suite du poème transforme cette adresse en une marche commune à l’écart de la fête et de ses remords."},{"function":"La portée","sentence":"L’apaisement peut donc passer par une autre relation à sa souffrance, sans faire de la poésie un remède universel."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Distinguer suppression et mise à distance","reason":"Après la maîtrise conçue comme lutte, examiner la liberté qui peut naître d’une relation plus réfléchie à ce que nous éprouvons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"Le langage nous éloigne-t-il du réel ?","function":"Montrer une médiation qui transforme l’expérience","reason":"Analyser comment parler à sa douleur peut modifier la manière de la vivre, sans prétendre qu’elle n’existe plus.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"collection":"Nouvelles Fleurs du Mal"},{"id":"baudelaire-boue-et-or","code":"B16","author":"Baudelaire","title":"Faire œuvre avec ce qui déplaît","work":"Ébauche d’un épilogue pour la deuxième édition des « Fleurs du Mal »","locator":"deux derniers vers · p. 214","quote":"Car j’ai de chaque chose extrait la quintessence,\nTu m’as donné ta boue et j’en ai fait de l’or.","notions":["art","nature"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"L’art doit-il choisir une matière déjà belle pour produire de la beauté ?"},{"function":"L’affirmation","sentence":"Dans cette ébauche adressée à Paris, le poète affirme avoir changé la boue reçue en or."},{"function":"Les concepts","sentence":"La boue désigne une matière dépréciée, tandis que l’or figure la valeur que le travail poétique lui donne."},{"function":"La raison","sentence":"La création ne se borne donc pas à reproduire son objet : elle en extrait et en compose une forme nouvelle."},{"function":"L’exemple","sentence":"Une scène urbaine pénible peut devenir, par le rythme et les images, une expérience sensible qui donne à penser."},{"function":"La portée","sentence":"L’art peut ainsi transfigurer sa matière, sans rendre moralement bons les maux qu’il représente."}],"uses":[{"subject":"La laideur peut-elle intéresser l’artiste ?","function":"Distinguer la matière et la valeur de l’œuvre","reason":"Après l’identification de l’art aux beaux objets, montrer que la création peut donner une forme précieuse à une matière dépréciée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"L’art peut-il nous apprendre à voir le monde autrement ?","function":"Définir une transformation du regard","reason":"Montrer comment une œuvre fait apparaître des rapports et une valeur que l’objet ne livrait pas au regard ordinaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"racine-pouvoir-et-peur","code":"R01","author":"Racine","title":"Faire peur et devoir tout craindre","work":"Britannicus","locator":"Acte IV, scène III","quote":"Craint de tout l'univers, il vous faudra tout craindre,\nToujours punir, toujours trembler dans vos projets,","notions":["etat","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le pouvoir de faire peur délivre-t-il de la peur ?"},{"function":"L’affirmation","sentence":"Burrhus annonce que Néron, craint de tous, devra lui-même vivre dans une crainte continuelle."},{"function":"Les concepts","sentence":"Le retour de craindre inverse les positions du maître redouté et de celui qui se sent menacé."},{"function":"La raison","sentence":"La violence appelle des vengeurs et conduit à de nouvelles violences pour contenir les ennemis qu’elle produit."},{"function":"L’exemple","sentence":"Burrhus explique que le meurtre de Britannicus susciterait des défenseurs auxquels d’autres succéderaient."},{"function":"La portée","sentence":"La domination peut donc enfermer celui qui l’exerce, sans que cette conséquence dispense de juger aussi le tort fait à ses victimes."}],"uses":[{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Expliquer un enchaînement de violences","reason":"Montrer comment un premier crime peut rendre nécessaires, aux yeux du tyran, de nouvelles répressions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Distinguer domination et liberté","reason":"Opposer le pouvoir d’imposer sa volonté à la dépendance croissante envers la peur et la défense de sa position.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"speaker":"Burrhus","situation":"Burrhus avertit Néron que le meurtre de Britannicus l’enfermerait dans une suite de violences."},{"id":"racine-passion-et-destin","code":"R02","author":"Racine","title":"Se livrer à ce qui nous entraîne","work":"Andromaque","locator":"Acte I, scène I","quote":"Je me livre en aveugle au destin qui m’entraîne.","notions":["liberte","conscience"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une passion devient-elle un destin dès lors que nous ne réussissons pas à lui résister ?"},{"function":"L’affirmation","sentence":"Oreste présente son retour vers Hermione comme l’abandon d’une résistance devenue vaine."},{"function":"Les concepts","sentence":"Le destin nomme ce qui l’entraîne, mais le verbe se livrer conserve la trace de sa propre participation."},{"function":"La raison","sentence":"La réplique associe donc l’expérience d’une contrainte intérieure et le geste de céder à cette contrainte."},{"function":"L’exemple","sentence":"Oreste ne vient pas seulement subir une rencontre : il annonce qu’il cherchera à fléchir Hermione ou à l’enlever."},{"function":"La portée","sentence":"La passion peut ainsi être vécue comme une fatalité, sans que cette présentation suffise à abolir toute responsabilité dans les actes."}],"uses":[{"subject":"Le désir est-il un obstacle à la liberté ?","function":"Distinguer subir un désir et s’y abandonner","reason":"Après la force éprouvée de la passion, examiner la participation du sujet à ce qui l’entraîne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=43","sourceLabel":"Recueil académique · p. 43"},{"subject":"Est-ce l’ignorance de ce que nous sommes qui fait la force de nos passions ?","function":"Limiter la suffisance de la lucidité","reason":"Montrer qu’un personnage peut reconnaître son attachement sans parvenir pour autant à lui résister.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=131","sourceLabel":"Recueil académique · p. 131"}],"speaker":"Oreste","situation":"Oreste explique à Pylade son retour auprès d’Hermione malgré ses efforts pour l’oublier."},{"id":"racine-amour-et-merite","code":"R03","author":"Racine","title":"Aimer au-delà des raisons d’aimer","work":"Andromaque","locator":"Acte IV, scène V","quote":"Je t’aimais inconstant, qu’aurais-je fait fidèle?","notions":["bonheur","raison"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"L’attachement amoureux se mesure-t-il aux qualités de la personne aimée ?"},{"function":"L’affirmation","sentence":"Hermione affirme avoir aimé Pyrrhus malgré son inconstance et imagine la force d’un amour récompensé par sa fidélité."},{"function":"Les concepts","sentence":"L’opposition entre inconstant et fidèle sépare la conduite réelle de l’être aimé et celle qu’elle attendait de lui."},{"function":"La raison","sentence":"L’amour peut persister lorsque les raisons de faire confiance à l’autre sont démenties par ses actes."},{"function":"L’exemple","sentence":"Hermione reproche à Pyrrhus son abandon tout en avouant qu’elle doute encore de ne plus l’aimer."},{"function":"La portée","sentence":"Le désir ne suit donc pas mécaniquement notre jugement sur l’autre, sans que sa persistance justifie d’accepter toute conduite."}],"uses":[{"subject":"Ne désirons-nous que les choses que nous estimons bonnes ?","function":"Distinguer l’attachement et le jugement","reason":"Après le désir orienté vers un bien, examiner un amour qui survit à la condamnation de la conduite de l’être aimé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=92","sourceLabel":"Recueil académique · p. 92"},{"subject":"La raison s’oppose-t-elle nécessairement au désir ?","function":"Préciser un conflit intérieur","reason":"Montrer que le jugement porté sur une personne peut entrer en conflit avec un attachement qui ne disparaît pas sur commande.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"}],"speaker":"Hermione","situation":"Hermione reproche à Pyrrhus de l’abandonner pour épouser Andromaque."},{"id":"racine-separation-et-avenir","code":"R04","author":"Racine","title":"Un avenir rendu sensible par l’absence","work":"Bérénice","locator":"Acte IV, scène 5","quote":"Dans un mois, dans un an, comment souffrirons-nous,\nSeigneur, que tant de mers me séparent de vous?","notions":["temps","bonheur"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Un avenir encore absent peut-il déjà nous faire souffrir ?"},{"function":"L’affirmation","sentence":"Bérénice interroge Titus sur la manière dont ils supporteront leur séparation dans les mois et les années à venir."},{"function":"Les concepts","sentence":"La succession du mois et de l’an donne une durée à l’absence, tandis que les mers en font sentir la distance."},{"function":"La raison","sentence":"Imaginer le futur transporte ainsi dans le présent une douleur dont l’événement n’a pas encore eu lieu."},{"function":"L’exemple","sentence":"Bérénice prolonge sa question en évoquant des journées qui recommenceront sans qu’ils puissent se revoir."},{"function":"La portée","sentence":"Le temps vécu dépend donc aussi de l’anticipation, sans que l’image du malheur à venir en fixe définitivement l’expérience réelle."}],"uses":[{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer calendrier et absence vécue","reason":"À la mesure des mois et des années, opposer ce que leur durée signifie pour ceux qui anticipent une séparation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"Le bonheur est-il inaccessible à l’homme ?","function":"Examiner la souffrance anticipée","reason":"Montrer comment le présent peut être troublé par une perte à venir, sans conclure de cette possibilité à l’impossibilité de tout bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"speaker":"Bérénice","situation":"Bérénice fait éprouver à Titus la durée de leur séparation annoncée."},{"id":"racine-amour-et-domination","code":"R05","author":"Racine","title":"Prendre plaisir au pouvoir sur l’autre","work":"Britannicus","locator":"Acte II, scène II","quote":"J'aimais jusqu'à ses pleurs que je faisais couler.","notions":["liberte","devoir"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Tout plaisir éprouvé auprès d’un être aimé est-il un signe d’amour pour lui ?"},{"function":"L’affirmation","sentence":"Néron avoue aimer jusqu’aux pleurs de Junie dont il se sait la cause."},{"function":"Les concepts","sentence":"Le plaisir ne porte plus seulement sur sa présence, mais sur la manifestation de sa dépendance et de sa souffrance."},{"function":"La raison","sentence":"La situation fait apparaître une satisfaction de domination qui utilise l’autre au lieu de rechercher son bien."},{"function":"L’exemple","sentence":"Néron raconte à Narcisse avoir mêlé les soupirs et la menace dans le dialogue qu’il imaginait avec Junie."},{"function":"La portée","sentence":"Le nom d’amour peut donc couvrir une jouissance du pouvoir, sans que cette réplique autorise à identifier tout attachement à la cruauté."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer le plaisir et sa justification morale","reason":"Après le caractère agréable d’une satisfaction, examiner ce qu’elle prend pour objet et ce qu’elle fait subir à autrui.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Montrer la limite du bon plaisir","reason":"Opposer à la satisfaction de celui qui peut agir la liberté de la personne sur laquelle il exerce ce pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"speaker":"Néron","situation":"Néron raconte à Narcisse sa fascination pour Junie qu’il a fait enlever."},{"id":"racine-geste-et-mensonge","code":"R06","author":"Racine","title":"Un même geste, deux intentions","work":"Britannicus","locator":"Acte IV, scène III","quote":"J'embrasse mon rival, mais c'est pour l'étouffer.","notions":["verite","langage"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le sens d’un geste se lit-il immédiatement dans son apparence ?"},{"function":"L’affirmation","sentence":"Néron annonce qu’il emploiera le geste de l’embrassement pour préparer la destruction de son rival."},{"function":"Les concepts","sentence":"L’embrassade signifie ordinairement l’accord, mais le but avoué lui donne ici une fonction opposée."},{"function":"La raison","sentence":"La confiance produite par le signe peut ainsi devenir l’instrument qui empêche l’autre de se défendre."},{"function":"L’exemple","sentence":"La réconciliation annoncée à Britannicus doit masquer le projet que Néron confie à Burrhus."},{"function":"La portée","sentence":"Interpréter une action demande donc d’examiner son contexte et son intention, sans conclure que toute marque d’affection serait mensongère."}],"uses":[{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer le signe visible et l’intention","reason":"Après la confiance dans l’apparence d’un geste, montrer comment le même signe peut servir une intention contraire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"Le langage trahit-il la pensée ?","function":"Étendre l’examen aux gestes qui signifient","reason":"Montrer qu’un signe de réconciliation peut produire une croyance destinée à cacher le projet véritable de celui qui l’emploie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"speaker":"Néron","situation":"Néron révèle à Burrhus que sa réconciliation avec Britannicus cache un projet meurtrier."},{"id":"racine-regner-et-vivre","code":"R07","author":"Racine","title":"La fonction publique et la vie personnelle","work":"Bérénice","locator":"Acte IV, scène 5","quote":"Mais il ne s'agit plus de vivre, il faut régner.","notions":["devoir","etat","bonheur"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une fonction publique peut-elle exiger le sacrifice de ce qui donne sens à la vie personnelle ?"},{"function":"L’affirmation","sentence":"Titus oppose la nécessité de régner à la possibilité de vivre auprès de Bérénice."},{"function":"Les concepts","sentence":"Vivre désigne ici la vie affective qui lui est chère, tandis que régner renvoie à l’obligation politique qu’il revendique."},{"function":"La raison","sentence":"Son rôle d’empereur lui paraît imposer une décision que son amour refuse."},{"function":"L’exemple","sentence":"Il reconnaît la souffrance de la séparation au moment même où il l’annonce à Bérénice."},{"function":"La portée","sentence":"La réplique rend sensible un conflit entre devoir et bonheur, sans prouver que la nécessité invoquée par le souverain soit incontestable."}],"uses":[{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Faire apparaître le coût d’une obligation","reason":"Après le bonheur d’accomplir son devoir, examiner une décision qui paraît exiger le renoncement à une vie heureuse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"},{"subject":"L’État est-il, par définition, indifférent aux intérêts particuliers ?","function":"Examiner le conflit entre rôle et attachement","reason":"Montrer qu’une responsabilité publique peut être vécue comme une exigence opposée aux désirs de la personne qui l’exerce.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"speaker":"Titus","situation":"Titus explique à Bérénice pourquoi il renonce à leur union au nom de Rome."},{"id":"racine-aimer-et-quitter","code":"R08","author":"Racine","title":"Se séparer sans cesser d’aimer","work":"Bérénice","locator":"Acte V, scène dernière","quote":"Je l'aime, je le fuis; Titus m'aime, il me quitte.","notions":["liberte","devoir","bonheur"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La séparation prouve-t-elle que l’amour a disparu ?"},{"function":"L’affirmation","sentence":"Bérénice affirme que Titus et elle se quittent alors même qu’ils s’aiment encore."},{"function":"Les concepts","sentence":"Le parallélisme des deux propositions distingue la persistance du sentiment et la décision de renoncer à l’union."},{"function":"La raison","sentence":"L’action peut ainsi contredire le désir sans que celui-ci soit simplement effacé."},{"function":"L’exemple","sentence":"Bérénice transforme leur séparation en exemple douloureux et demande à Antiochus de poursuivre sa vie."},{"function":"La portée","sentence":"Aimer et choisir de partir peuvent donc coexister, sans faire de toute séparation la preuve d’un libre accord heureux."}],"uses":[{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Distinguer le désir et la conduite","reason":"Après la liberté d’accomplir ses souhaits, examiner la décision de s’en séparer lorsqu’une autre exigence intervient.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Maintenir les deux exigences dans la décision","reason":"Montrer qu’un renoncement peut laisser entier l’attachement sacrifié, au lieu de résoudre le conflit par sa disparition.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}],"speaker":"Bérénice","situation":"Bérénice annonce sa séparation d’avec Titus et exhorte Antiochus à vivre."},{"id":"racine-desir-et-fuite","code":"R09","author":"Racine","title":"Prolonger le péril que l’on fuit","work":"Mithridate","locator":"Acte II, scène VI","quote":"Plus je vous parle, et plus, trop faible que je suis,\nJe cherche à prolonger le péril que je fuis.","notions":["liberte","conscience","raison"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Savoir qu’une situation nous met en danger suffit-il à vouloir y mettre fin ?"},{"function":"L’affirmation","sentence":"Monime reconnaît que sa conversation avec Xipharès prolonge précisément le péril auquel elle veut échapper."},{"function":"Les concepts","sentence":"Le péril désigne ici le risque de céder à son amour et de trahir l’engagement qui la lie à Mithridate."},{"function":"La raison","sentence":"La lucidité accompagne donc le plaisir au lieu de l’abolir : parler encore permet de différer la séparation jugée nécessaire."},{"function":"L’exemple","sentence":"Monime finit pourtant par partir et demande à Xipharès de l’éviter."},{"function":"La portée","sentence":"Le sujet peut connaître sa contradiction et agir pour y résister, sans que le seul aveu de faiblesse garantisse la maîtrise de ses choix."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Distinguer lucidité et maîtrise","reason":"Après la reconnaissance d’une passion, examiner l’effort nécessaire pour interrompre une situation qui la nourrit.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"La raison s’oppose-t-elle nécessairement au désir ?","function":"Montrer une raison présente dans le conflit","reason":"La conscience du risque peut coexister avec le plaisir de le prolonger : la raison n’est pas simplement absente du désir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"}],"speaker":"Monime","situation":"Monime fait ses adieux à Xipharès pour rester fidèle à son engagement envers Mithridate."},{"id":"racine-oracle-et-interpretation","code":"R10","author":"Racine","title":"L’autorité d’une parole et son interprétation","work":"Iphigénie","locator":"Acte IV, scène IV","quote":"Un oracle dit-il tout ce qu'il semble dire?","notions":["religion","raison","langage"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Respecter une parole tenue pour sacrée impose-t-il d’accepter immédiatement le sens qu’on lui donne ?"},{"function":"L’affirmation","sentence":"Clytemnestre met en doute l’interprétation de l’oracle invoqué pour sacrifier Iphigénie."},{"function":"Les concepts","sentence":"Elle distingue ce que la parole semble dire et le sens qu’un examen pourrait faire apparaître."},{"function":"La raison","sentence":"L’autorité accordée à l’oracle ne supprime donc pas la responsabilité de ceux qui décident de son application."},{"function":"L’exemple","sentence":"La mère oppose à la lecture meurtrière la question d’un ciel juste qui demanderait le sang de l’innocence."},{"function":"La portée","sentence":"La croyance peut ainsi appeler un travail d’interprétation, sans que le doute garantisse à lui seul la lecture que nous préférons."}],"uses":[{"subject":"Croire, est-ce renoncer à la raison ?","function":"Distinguer croire et accepter une lecture sans examen","reason":"Après l’autorité reconnue à une parole, montrer que son interprétation demeure une tâche de la raison.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Peut-on interpréter sans inventer ?","function":"Examiner la responsabilité de l’interprète","reason":"Montrer que la gravité d’une décision oblige à discuter le sens d’une parole, sans autoriser des interprétations arbitraires.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=110","sourceLabel":"Recueil académique · p. 110"}],"speaker":"Clytemnestre","situation":"Clytemnestre conteste devant Agamemnon l’oracle invoqué pour sacrifier leur fille."},{"id":"racine-innocence-et-preuve","code":"R11","author":"Racine","title":"L’innocence vécue ne fait pas preuve","work":"Phèdre","locator":"Acte IV, scène 2","quote":"Le jour n’est pas plus pur que le fond de mon cœur.","notions":["justice","conscience","verite"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La certitude intime d’être innocent suffit-elle à convaincre celui qui nous accuse ?"},{"function":"L’affirmation","sentence":"Hippolyte affirme la pureté de son cœur en la comparant à la clarté du jour."},{"function":"Les concepts","sentence":"La lumière rend sensible une innocence qu’il éprouve, mais que son père ne peut pas directement voir."},{"function":"La raison","sentence":"L’écart entre l’assurance du fils et la défiance de Thésée montre la difficulté de communiquer une vérité sur soi."},{"function":"L’exemple","sentence":"Thésée prend même la rigueur morale d’Hippolyte pour un orgueil qui renforcerait sa culpabilité."},{"function":"La portée","sentence":"Une conviction intérieure peut donc être fondée sans constituer une preuve publique suffisante, ce qui oblige aussi l’accusateur à examiner ses préjugés."}],"uses":[{"subject":"La certitude est-elle une garantie de vérité ?","function":"Distinguer certitude vécue et preuve pour autrui","reason":"Examiner une certitude fondée qui ne suffit pourtant pas à établir publiquement la vérité du jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Comment savoir ce qui est juste ?","function":"Distinguer le sentiment et l’établissement de l’innocence","reason":"Montrer que la conscience du sujet doit être confrontée aux faits, sans présumer pour autant que le refus de le croire soit juste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Hippolyte","situation":"Accusé par Œnone, Hippolyte affirme son innocence devant Thésée, qui ne le croit pas."},{"id":"racine-passion-et-corps","code":"R12","author":"Racine","title":"Le corps précède la maîtrise","work":"Phèdre","locator":"Acte I, scène 3","quote":"Je le vis, je rougis, je pâlis à sa vue;","notions":["conscience","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Sommes-nous maîtres de tout ce que notre corps manifeste ?"},{"function":"L’affirmation","sentence":"Phèdre raconte sa rencontre avec Hippolyte par une succession immédiate de réactions corporelles."},{"function":"Les concepts","sentence":"Voir, rougir et pâlir rapprochent la perception de l’autre et une émotion qui transforme le corps."},{"function":"La raison","sentence":"La rapidité des verbes fait éprouver un bouleversement qui n’attend pas une décision réfléchie."},{"function":"L’exemple","sentence":"Le récit permet ainsi à Phèdre de reconnaître après coup ce qu’elle a éprouvé lors de cette première rencontre."},{"function":"La portée","sentence":"La passion peut donc se manifester avant notre maîtrise consciente, sans que toute réaction involontaire détermine nécessairement nos actions futures."}],"uses":[{"subject":"Sommes-nous conscients de ce que nous désirons ?","function":"Distinguer manifestation et compréhension du désir","reason":"Après la conscience immédiate d’une émotion, examiner le travail nécessaire pour reconnaître ce qui nous affecte.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"Le désir est-il un obstacle à la liberté ?","function":"Distinguer l’émotion reçue et la décision","reason":"Reconnaître les réactions involontaires du corps sans conclure qu’elles commandent entièrement la conduite à venir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=43","sourceLabel":"Recueil académique · p. 43"}],"speaker":"Phèdre","situation":"Phèdre raconte à Œnone sa première rencontre avec Hippolyte."},{"id":"racine-conscience-et-justification","code":"R13","author":"Racine","title":"Se croire dans son devoir","work":"Athalie","locator":"Acte II, scène V","quote":"Ce que j’ai fait, Abner, j’ai cru le devoir faire.","notions":["conscience","devoir","justice"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Croire avoir accompli son devoir suffit-il à justifier ses actes ?"},{"function":"L’affirmation","sentence":"Athalie présente les violences de son règne comme des actions qu’elle croyait nécessaires."},{"function":"Les concepts","sentence":"La réplique affirme une conviction personnelle, mais n’établit pas encore la justice de ce qui a été fait."},{"function":"La raison","sentence":"Le sentiment du devoir peut devenir une manière de soustraire ses actes au jugement d’autrui."},{"function":"L’exemple","sentence":"Athalie déclare aussitôt qu’elle ne reconnaît pas le peuple comme juge de sa conduite."},{"function":"La portée","sentence":"La bonne conscience doit donc être distinguée de la justification morale, sans supposer qu’une conviction sincère serait toujours mensongère."}],"uses":[{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Distinguer conviction et justification","reason":"Après la sincérité de l’intention, exiger l’examen des raisons et des conséquences de l’action.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Peut-on toujours savoir comment agir avec justice ?","function":"Examiner une certitude qui protège de l’examen","reason":"Montrer comment une personne peut se croire fondée à agir tout en refusant les objections de ceux qui subissent ses décisions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Athalie","situation":"Athalie justifie devant Abner et Mathan les violences qui ont établi son pouvoir."},{"id":"racine-justice-et-surete","code":"R14","author":"Racine","title":"La sûreté contre la justice","work":"Athalie","locator":"Acte II, scène V","quote":"Est-ce aux rois à garder cette lente justice?\nLeur sûreté souvent dépend d’un prompt supplice.","notions":["etat","justice"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La sécurité du pouvoir autorise-t-elle à supprimer les garanties de la justice ?"},{"function":"L’affirmation","sentence":"Mathan oppose la lenteur de la justice à la rapidité du supplice qu’il recommande."},{"function":"Les concepts","sentence":"La sûreté désigne ici la protection du souverain, tandis que la justice suppose un examen qui retarde la sanction."},{"function":"La raison","sentence":"Présenter cette attente comme un danger permet de traiter le soupçon comme une raison suffisante de tuer."},{"function":"L’exemple","sentence":"Mathan propose ainsi de supprimer l’enfant caché dans le Temple avant que son identité soit pleinement établie."},{"function":"La portée","sentence":"La réplique expose une justification de la violence politique, sans constituer une approbation de cette justification par Racine."}],"uses":[{"subject":"L’État doit-il préférer l’injustice au désordre ?","function":"Mettre à l’épreuve l’argument de l’urgence","reason":"Après la nécessité de protéger l’ordre public, distinguer une menace établie et un soupçon exploité pour supprimer les garanties du jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"La justice met-elle fin à la loi du plus fort ?","function":"Examiner ce que la rapidité sacrifie","reason":"Montrer que raccourcir le jugement peut revenir à le remplacer par la volonté de celui qui dispose de la force.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Mathan","situation":"Mathan conseille à Athalie de supprimer l’enfant caché dans le Temple."},{"id":"racine-pouvoir-et-flatterie","code":"R15","author":"Racine","title":"Le pouvoir peut perdre le jugement","work":"Athalie","locator":"Acte IV, scène III","quote":"De l’absolu pouvoir vous ignorez l’ivresse,\nEt des lâches flatteurs la voix enchanteresse.","notions":["etat","verite","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Disposer d’un pouvoir sans obstacle rend-il plus capable de bien juger ?"},{"function":"L’affirmation","sentence":"Joad avertit Joas que le pouvoir absolu et les flatteries peuvent l’enivrer."},{"function":"Les concepts","sentence":"L’ivresse figure une perte de mesure, tandis que la voix enchanteresse des flatteurs rend cette perte agréable."},{"function":"La raison","sentence":"Celui qui peut tout entendre confirmer risque de confondre ses désirs avec ce qui est juste."},{"function":"L’exemple","sentence":"Joad annonce que des conseillers présenteront au jeune roi les lois comme des contraintes réservées au peuple."},{"function":"La portée","sentence":"Limiter le pouvoir et préserver la contradiction deviennent donc des conditions du jugement, sans garantir qu’un souverain conseillé soit toujours lucide."}],"uses":[{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Expliquer un mécanisme de démesure","reason":"Après les capacités que donne le pouvoir, examiner l’affaiblissement du jugement lorsque la flatterie remplace les objections.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Toute vérité est-elle bonne à dire ?","function":"Montrer le besoin d’une parole qui résiste","reason":"Après le risque de déplaire, montrer ce qu’un détenteur de pouvoir perd lorsque son entourage ne lui dit plus que ce qu’il veut entendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=72","sourceLabel":"Recueil académique · p. 72"}],"speaker":"Joad","situation":"Joad avertit le jeune Joas des dangers du pouvoir et des flatteurs."},{"id":"racine-naissance-et-consentement","code":"R16","author":"Racine","title":"Le titre suffit-il à légitimer le pouvoir ?","work":"La Thébaïde","locator":"Acte II, scène 3","quote":"Est-ce au peuple, Madame, à se choisir un maître?\nSitôt qu’il hait un roi, doit-on cesser de l’être?","notions":["etat","justice","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le droit de gouverner peut-il se passer de l’accord de ceux qui sont gouvernés ?"},{"function":"L’affirmation","sentence":"Polynice refuse de faire dépendre son titre royal du choix ou de l’hostilité du peuple."},{"function":"Les concepts","sentence":"Il oppose la légitimité qu’il tire de sa naissance à une volonté collective qu’il réduit au caprice."},{"function":"La raison","sentence":"Son raisonnement suppose que la possession du titre suffit à fonder l’obéissance, même lorsque les sujets le rejettent."},{"function":"L’exemple","sentence":"Jocaste lui objecte alors qu’un prince imposé à un peuple hostile risque de devenir un tyran."},{"function":"La portée","sentence":"Le passage permet donc d’interroger le fondement de l’autorité, sans confondre la prétention dynastique du personnage avec une démonstration de sa justice."}],"uses":[{"subject":"De quel droit l’État exerce-t-il un pouvoir ?","function":"Distinguer le titre et l’accord des gouvernés","reason":"Après la possession reconnue d’une fonction, examiner si son origine suffit à rendre l’obéissance légitime.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Le pouvoir politique peut-il appartenir à ceux qui sont gouvernés ?","function":"Distinguer l’examen d’un jugement et le droit de choisir","reason":"Montrer que contester une décision collective ne suffit pas à démontrer que les gouvernés ne doivent avoir aucun choix.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"speaker":"Polynice","situation":"Polynice revendique son droit au trône malgré l’hostilité des Thébains."},{"id":"racine-justice-et-information","code":"R17","author":"Racine","title":"Un bon juge peut être trompé","work":"Esther","locator":"Acte III, scène dernière","quote":"On peut des plus grands rois surprendre la justice.","notions":["justice","verite","etat"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La volonté d’être juste suffit-elle à empêcher une décision injuste ?"},{"function":"L’affirmation","sentence":"Le chœur affirme qu’il est possible de tromper la justice même des plus grands rois."},{"function":"Les concepts","sentence":"Surprendre signifie ici abuser le jugement en lui présentant des raisons ou des faits trompeurs."},{"function":"La raison","sentence":"Une autorité bien intentionnée peut donc commettre l’injustice si elle dépend d’une information manipulée."},{"function":"L’exemple","sentence":"Dans la pièce, Aman a obtenu d’Assuérus une décision contre les Juifs en abusant de sa confiance."},{"function":"La portée","sentence":"La justice exige ainsi l’examen des témoignages et des intérêts qui les orientent, sans que la bonne intention dispense de cette vigilance."}],"uses":[{"subject":"Être juste, est-ce être neutre ?","function":"Ajouter l’exigence d’une information examinée","reason":"Après l’absence de parti pris, montrer qu’un jugement peut encore être faussé par les faits qu’on lui présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"Peut-on toujours savoir comment agir avec justice ?","function":"Distinguer volonté et effet de la décision","reason":"Examiner une injustice produite par un jugement trompé, sans effacer la responsabilité de vérifier ce qui est affirmé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Une Israélite du chœur","situation":"Après la chute d’Aman, le chœur médite sur les pièges tendus aux rois."},{"id":"corneille-liberte-dans-les-liens","code":"CO01","author":"Corneille","title":"Être libre jusque dans l’attachement","work":"La Place Royale","locator":"Acte I, scène IV","quote":"Je veux la liberté dans le milieu des fers.","speaker":"Alidor","situation":"Alidor explique à Cléandre pourquoi il veut rompre avec Angélique, qui l’aime.","notions":["liberte","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on aimer sans rien perdre de sa liberté ?"},{"function":"L’affirmation","sentence":"Alidor veut conserver, au sein même de l’attachement amoureux, une entière disposition de lui-même."},{"function":"Les concepts","sentence":"Les fers figurent le lien passionnel, tandis que la liberté désigne le pouvoir d’aimer et de cesser d’aimer à volonté."},{"function":"La raison","sentence":"Il exige ainsi que le sentiment dépende de sa décision, au lieu de découvrir une volonté déjà engagée par ce qu’elle aime."},{"function":"L’exemple","sentence":"Il prépare la rupture avec Angélique alors même qu’elle l’aime et qu’il reconnaît sa perfection."},{"function":"La portée","sentence":"La réplique interroge une liberté comprise comme absence de dépendance, sans justifier les violences commises pour la préserver."}],"uses":[{"subject":"L’indépendance suffit-elle à définir la liberté ?","function":"Éprouver une liberté sans attachement","reason":"Après l’indépendance prise pour modèle, examiner ce qu’une volonté perd lorsqu’elle refuse tout lien qui pourrait la transformer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Faut-il combattre les passions pour être libre ?","function":"Distinguer maîtrise et refus de l’attachement","reason":"Faire apparaître le risque de combattre le sentiment jusqu’à traiter la personne aimée comme un obstacle à supprimer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-temps-et-promesse","code":"CO02","author":"Corneille","title":"Promettre malgré le changement","work":"La Place Royale","locator":"Acte I, scène IV","quote":"Du temps, qui change tout, les révolutions\nNe changent-elles pas nos résolutions ?","speaker":"Alidor","situation":"Alidor invoque le changement des sentiments pour refuser de se lier par le mariage.","notions":["temps","devoir","liberte"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Comment engager son avenir si nos sentiments peuvent changer ?"},{"function":"L’affirmation","sentence":"Alidor invoque les transformations du temps pour mettre en doute la permanence de nos résolutions."},{"function":"Les concepts","sentence":"Les révolutions désignent les changements qui nous affectent, et les résolutions les décisions par lesquelles nous prétendons orienter notre conduite."},{"function":"La raison","sentence":"Le retour sonore des deux mots rapproche ce qui nous arrive et ce que nous croyons décider durablement."},{"function":"L’exemple","sentence":"Alidor craint de demeurer marié lorsque la beauté ou son propre goût ne soutiendront plus son amour."},{"function":"La portée","sentence":"La promesse doit donc être pensée avec la possibilité du changement, sans conclure que toute fidélité serait impossible ou sans valeur."}],"uses":[{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer décision présente et maîtrise de l’avenir","reason":"Au moment d’examiner nos projets, montrer que décider aujourd’hui ne garantit pas la permanence des sentiments qui motivent la décision.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"},{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Introduire la durée de l’engagement","reason":"Après un accord présent du désir et du devoir, demander ce qui soutient l’engagement lorsque cet accord se défait.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-amour-et-trahison","code":"CO03","author":"Corneille","title":"Quand l’amour agit comme la haine","work":"La Place Royale","locator":"Acte IV, scène V","quote":"Si mon feu la trahit, que lui ferait ma haine ?","speaker":"Alidor","situation":"Alidor éprouve des remords après avoir organisé l’enlèvement d’Angélique au profit de son ami.","notions":["devoir","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le sentiment d’aimer garantit-il que nous agissions pour le bien de l’autre ?"},{"function":"L’affirmation","sentence":"Alidor s’étonne que son amour conduise à trahir Angélique comme pourrait le faire la haine."},{"function":"Les concepts","sentence":"Le feu désigne la passion amoureuse, dont les effets contredisent ici la bienveillance attendue."},{"function":"La raison","sentence":"Le rapprochement de l’amour et de la haine oblige à juger une conduite autrement que par le nom du sentiment invoqué."},{"function":"L’exemple","sentence":"Pour retrouver sa liberté, Alidor a favorisé l’enlèvement de celle qui lui demeure attachée."},{"function":"La portée","sentence":"La lucidité du remords met au jour une contradiction de l’action, sans suffire à réparer le mal ni à transformer immédiatement la conduite."}],"uses":[{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Examiner les actes derrière le sentiment","reason":"Dans l’étude de la bienveillance, distinguer aimer quelqu’un et traiter effectivement ses intérêts avec respect.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Évaluer une intention par ses effets","reason":"Montrer que le nom honorable donné à son sentiment ne dispense pas d’examiner la trahison qu’il accompagne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-victoire-et-merite","code":"CO04","author":"Corneille","title":"Ce que coûte une victoire","work":"Le Cid","locator":"Acte II, scène II","quote":"A vaincre sans péril, on triomphe sans gloire.","speaker":"Le Comte","situation":"Le Comte tente de dissuader Rodrigue de l’affronter en duel.","notions":["devoir","justice"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Toute victoire mérite-t-elle l’admiration ?"},{"function":"L’affirmation","sentence":"Le Comte affirme qu’une victoire sans danger n’apporte aucune gloire."},{"function":"Les concepts","sentence":"Vaincre désigne le résultat du combat, tandis que la gloire renvoie à la reconnaissance d’une valeur manifestée."},{"function":"La raison","sentence":"La difficulté compte donc dans l’appréciation de l’exploit : le seul succès ne dit pas encore ce que le vainqueur a accompli."},{"function":"L’exemple","sentence":"Le Comte croit qu’affronter le jeune Rodrigue serait pour lui un combat trop inégal."},{"function":"La portée","sentence":"Le vers distingue réussite et mérite, mais l’assurance du personnage rappelle qu’on peut aussi mal évaluer le danger et sa propre supériorité."}],"uses":[{"subject":"Être juste, est-ce être neutre ?","function":"Prendre en compte l’inégalité des situations","reason":"Pour juger un résultat, examiner si une même victoire représente le même effort selon les forces initiales des adversaires.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"Une inégalité peut-elle être juste ?","function":"Évaluer une différence de mérite","reason":"Distinguer deux succès semblables par la difficulté rencontrée, puis examiner si cette différence peut justifier une reconnaissance inégale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-patrie-et-humanite","code":"CO05","author":"Corneille","title":"Garder l’humain dans le devoir","work":"Horace","locator":"Acte II, scène III","quote":"Je rends grâces aux Dieux de n'être pas Romain,\nPour conserver encore quelque chose d'humain.","speaker":"Curiace","situation":"Curiace refuse l’insensibilité d’Horace alors que leurs cités les obligent à se combattre.","notions":["devoir","etat"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le dévouement à la patrie exige-t-il de ne plus éprouver de compassion ?"},{"function":"L’affirmation","sentence":"Curiace préfère conserver une sensibilité humaine plutôt que d’adopter l’insensibilité présentée par Horace comme une vertu romaine."},{"function":"Les concepts","sentence":"Le rapprochement de Romain et d’humain oppose une identité politique à une exigence qui dépasse l’appartenance civique."},{"function":"La raison","sentence":"Il peut accepter son devoir tout en refusant de tenir la souffrance devant le meurtre d’un proche pour une faiblesse honteuse."},{"function":"L’exemple","sentence":"Désigné pour combattre Horace, il ne se dérobe pas, mais reconnaît l’horreur de leur affrontement."},{"function":"La portée","sentence":"La compassion peut ainsi accompagner le courage, sans que la seule émotion suffise à décider quel devoir doit l’emporter."}],"uses":[{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Interroger le contenu du devoir invoqué","reason":"Avant de traiter l’obéissance comme une nécessité absolue, demander si l’appartenance politique autorise à étouffer toute objection humaine.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"},{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Préserver la sensibilité dans l’action juste","reason":"Après le sacrifice du bonheur, examiner si le devoir exige aussi la disparition de la compassion et du trouble moral.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-pouvoir-et-maitrise-de-soi","code":"CO06","author":"Corneille","title":"La souveraineté sur sa colère","work":"Cinna","locator":"Acte V, scène III","quote":"Je suis maître de moi comme de l'univers ;","speaker":"Auguste","situation":"Auguste renonce à se venger des conjurés et leur accorde son pardon.","notions":["liberte","etat","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le pouvoir sur les autres suffit-il à faire de nous les maîtres de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Auguste affirme sa maîtrise intérieure au moment de renoncer à la vengeance."},{"function":"Les concepts","sentence":"Le même mot de maître rapproche la souveraineté politique et le gouvernement de sa propre colère."},{"function":"La raison","sentence":"Pourtant, pouvoir punir et pouvoir retenir sa colère ne sont pas une seule puissance : le second exige de résister à une impulsion."},{"function":"L’exemple","sentence":"Auguste choisit le pardon alors que les conjurés lui ont donné des raisons de s’indigner."},{"function":"La portée","sentence":"La liberté apparaît dans la manière d’exercer son pouvoir, sans que cette proclamation efface les violences antérieures du souverain."}],"uses":[{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Distinguer toute-puissance et maîtrise de soi","reason":"Après la possibilité d’assouvir sa colère, présenter une décision qui consiste à ne pas exercer la violence disponible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Examiner une retenue possible du pouvoir","reason":"Faire du pardon un cas de limitation volontaire, sans en déduire qu’un pouvoir sans contrôle serait toujours bien exercé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-desir-et-attente","code":"CO07","author":"Corneille","title":"L’attente nourrit le désir","work":"Polyeucte","locator":"Acte I, scène I","quote":"Et le désir s'accroît quand l'effet se recule.","speaker":"Polyeucte","situation":"Polyeucte explique à Néarque que différer son baptême n’affaiblit pas son désir de le recevoir.","notions":["bonheur","temps"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"L’éloignement d’une satisfaction affaiblit-il nécessairement le désir ?"},{"function":"L’affirmation","sentence":"Polyeucte affirme que le report de son baptême accroît l’ardeur avec laquelle il le souhaite."},{"function":"Les concepts","sentence":"L’effet est ici l’accomplissement attendu, tandis que le désir demeure tourné vers ce qui n’a pas encore lieu."},{"function":"La raison","sentence":"La distance peut entretenir la représentation d’un bien et renforcer l’élan qui porte vers lui."},{"function":"L’exemple","sentence":"Néarque interprète au contraire ce délai comme le signe d’une ferveur qui risque de s’éteindre."},{"function":"La portée","sentence":"La scène oppose donc deux devenirs possibles de l’attente, sans établir que tout obstacle augmente toujours le désir."}],"uses":[{"subject":"Ne désirons-nous que ce qui nous manque ?","function":"Examiner le rôle de la distance","reason":"Après le manque qui déclenche le désir, montrer comment le délai peut encore l’entretenir en maintenant son objet à venir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Interroger la valeur de l’attente","reason":"Distinguer le mouvement du désir, parfois intensifié par le report, et l’état de satisfaction qu’il vise.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-croire-et-voir","code":"CO08","author":"Corneille","title":"L’évidence vécue de la foi","work":"Polyeucte","locator":"Acte V, scène V","quote":"Je vois, je sais, je crois, je suis désabusée :","speaker":"Pauline","situation":"Après le supplice de Polyeucte, Pauline proclame devant Félix sa conversion au christianisme.","notions":["religion","verite","raison"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une conviction vécue comme une évidence vaut-elle une preuve pour tous ?"},{"function":"L’affirmation","sentence":"Pauline présente sa conversion comme une ouverture des yeux et une sortie de l’erreur."},{"function":"Les concepts","sentence":"Voir, savoir et croire s’enchaînent dans un même élan, sans que leurs différences soient examinées."},{"function":"La raison","sentence":"Le rythme de l’affirmation fait entendre une certitude intérieure dont la force ne constitue pas encore une démonstration partageable."},{"function":"L’exemple","sentence":"Le supplice de Polyeucte devient pour Pauline le signe qui transforme sa manière de comprendre sa vie."},{"function":"La portée","sentence":"Le vers permet de distinguer expérience de la foi et justification publique, sans réduire la conversion du personnage à une simple tromperie."}],"uses":[{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer voir un événement et lui donner un sens","reason":"L’événement perçu peut soutenir une croyance sans imposer à tous l’interprétation religieuse qu’en tire le personnage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"La certitude est-elle une garantie de vérité ?","function":"Distinguer intensité et justification","reason":"Après la force intime d’une conviction, demander quelles raisons pourraient en établir la vérité pour autrui.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-mensonge-et-memoire","code":"CO09","author":"Corneille","title":"La mémoire nécessaire au mensonge","work":"Le Menteur","locator":"Acte IV, scène V","quote":"Il faut bonne mémoire après qu'on a menti.","speaker":"Cliton","situation":"Cliton rappelle à Dorante la difficulté de maintenir la cohérence de ses inventions.","notions":["langage","verite","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Inventer librement une histoire nous dispense-t-il de toute contrainte ?"},{"function":"L’affirmation","sentence":"Cliton rappelle que mentir oblige à se souvenir de ce qu’on a déjà raconté."},{"function":"Les concepts","sentence":"La mémoire maintient la continuité entre plusieurs affirmations, même lorsqu’elles ne correspondent pas aux faits."},{"function":"La raison","sentence":"Chaque invention engage ainsi le menteur dans une histoire dont il doit ensuite préserver la cohérence."},{"function":"L’exemple","sentence":"Dorante répond qu’il compte sur son esprit pour réparer ses défauts de mémoire."},{"function":"La portée","sentence":"La cohérence peut donc être fabriquée au service du faux, sans que la vérité se reconnaisse toujours à un récit hésitant ou assuré."}],"uses":[{"subject":"La cohérence d’une pensée suffit-elle à garantir sa vérité ?","function":"Montrer une cohérence mensongère","reason":"Après la non-contradiction exigée du discours vrai, rappeler qu’un récit inventé peut lui aussi rester cohérent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Le langage trahit-il la pensée ?","function":"Examiner la difficulté de la dissimulation","reason":"Distinguer le mensonge voulu et les contradictions involontaires par lesquelles une invention risque de se découvrir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-scene-et-realite","code":"CO10","author":"Corneille","title":"Les ennemis sur scène, les amis après","work":"L’Illusion comique","locator":"Acte V, scène V","quote":"Le traître et le trahi, le mort et le vivant,\nSe trouvent à la fin amis comme devant.","speaker":"Alcandre","situation":"Alcandre révèle à Pridamant que la mort de son fils était une représentation théâtrale.","notions":["art","verite"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une émotion réelle exige-t-elle que l’événement représenté ait réellement eu lieu ?"},{"function":"L’affirmation","sentence":"Alcandre révèle que les ennemis montrés sur scène se retrouvent amis une fois la représentation achevée."},{"function":"Les concepts","sentence":"Le mort et le vivant désignent des rôles, tandis que les amis sont les acteurs qui les interprètent."},{"function":"La raison","sentence":"Le spectateur peut donc éprouver une douleur véritable devant une mort qui appartient à la fiction."},{"function":"L’exemple","sentence":"Pridamant a cru voir assassiner son fils avant de le découvrir partageant la recette avec ses compagnons."},{"function":"La portée","sentence":"La vérité de l’émotion se distingue de la réalité de l’événement, sans que toute illusion soit pour autant dépourvue d’effets ou de risques."}],"uses":[{"subject":"L’art est-il indifférent à la vérité ?","function":"Distinguer fiction et tromperie","reason":"Après l’inexactitude des faits représentés, examiner une fiction dont le dispositif peut finalement être reconnu par le spectateur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=10","sourceLabel":"Recueil académique · p. 10"},{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Examiner le plaisir d’une émotion douloureuse","reason":"Montrer qu’une représentation tragique peut produire de la peine et contribuer pourtant à l’expérience artistique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-cite-et-legitimite","code":"CO11","author":"Corneille","title":"Où demeure une cité ?","work":"Sertorius","locator":"Acte III, scène I","quote":"Rome n'est plus dans Rome, elle est toute où je suis.","speaker":"Sertorius","situation":"Sertorius oppose à Pompée la légitimité républicaine des Romains rassemblés autour de lui en exil.","notions":["etat","justice"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une communauté politique se confond-elle avec le lieu où siège son pouvoir ?"},{"function":"L’affirmation","sentence":"Sertorius affirme que la vraie Rome demeure auprès des républicains qui l’accompagnent en exil."},{"function":"Les concepts","sentence":"Le premier nom de Rome désigne une communauté et ses principes, le second l’espace matériel de la ville."},{"function":"La raison","sentence":"La répétition du même mot rend sensible l’écart possible entre l’occupation d’un territoire et la fidélité à un ordre politique."},{"function":"L’exemple","sentence":"Sertorius oppose les soutiens réunis autour de lui aux proscriptions exercées sous l’autorité de Sylla."},{"function":"La portée","sentence":"Le vers permet d’interroger la légitimité au-delà du pouvoir établi, sans prouver que le personnage incarne à lui seul toute la cité."}],"uses":[{"subject":"De quel droit l’État exerce-t-il un pouvoir ?","function":"Distinguer possession et légitimité","reason":"Après l’autorité installée dans ses institutions, demander ce qui rend légitime celui qui prétend parler au nom de la communauté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Le pouvoir politique peut-il appartenir à ceux qui sont gouvernés ?","function":"Distinguer communauté et gouvernants","reason":"Examiner si une communauté peut maintenir ses exigences politiques lorsqu’elle conteste ceux qui occupent le pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-naissance-et-valeur","code":"CO12","author":"Corneille","title":"Ce que nous ne choisissons pas","work":"Othon","locator":"Acte II, scène II","quote":"Un pur hasard sans nous règle notre naissance ;","speaker":"Martian","situation":"L’affranchi Martian répond au mépris de Plautine pour son origine servile.","notions":["justice","liberte"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Ce qui nous a été donné sans choix peut-il mesurer notre valeur ?"},{"function":"L’affirmation","sentence":"Martian rappelle que notre naissance dépend d’un hasard auquel nous n’avons pas pris part."},{"function":"Les concepts","sentence":"La naissance désigne ici l’origine sociale, dont le personnage refuse de faire un mérite personnel."},{"function":"La raison","sentence":"Il oppose à cette condition reçue la valeur qu’il prétend avoir acquise par ses actions."},{"function":"L’exemple","sentence":"Ancien esclave, il répond au mépris de Plautine en faisant valoir sa puissance présente."},{"function":"La portée","sentence":"Le vers détache la dignité de l’origine, mais le contexte oblige aussi à distinguer mérite réel et réussite dans les intrigues du pouvoir."}],"uses":[{"subject":"Être juste, est-ce être neutre ?","function":"Distinguer origine et mérite","reason":"Avant de juger également les réussites, examiner les différences de départ et refuser d’attribuer un mérite à la naissance elle-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"Toutes les inégalités sont-elles des injustices ?","function":"Interroger la justification des rangs","reason":"Distinguer le fait d’une différence de naissance et le droit qu’on prétend en tirer sur autrui.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=33","sourceLabel":"Recueil académique · p. 33"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-devoir-et-desir","code":"CO13","author":"Corneille","title":"Ce que l’on se doit contre ce que l’on désire","work":"Pulchérie","locator":"Acte I, scène I","quote":"Ce qu'on se doit combat ce qu'on se veut donner :","speaker":"Pulchérie","situation":"Pulchérie explique à Léon le conflit entre leur amour et les exigences de son rang.","notions":["devoir","bonheur"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Tout ce que nous désirons nous paraît-il compatible avec l’idée que nous avons de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Pulchérie oppose les exigences de son rang au bonheur amoureux qu’elle voudrait s’accorder."},{"function":"Les concepts","sentence":"Ce qu’on se doit désigne une obligation revendiquée, tandis que se donner évoque la satisfaction consentie à son propre désir."},{"function":"La raison","sentence":"Le conflit traverse donc un même sujet, partagé entre son attachement et une dignité qu’il estime devoir préserver."},{"function":"L’exemple","sentence":"Pulchérie aime Léon mais refuse d’abord un mariage qui ne lui conserverait pas le rang impérial."},{"function":"La portée","sentence":"Le vers éclaire un désaccord du désir et du devoir, sans identifier automatiquement l’orgueil social à une exigence morale juste."}],"uses":[{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Faire apparaître le conflit intérieur","reason":"Après leur accord possible, examiner le cas où une même personne s’attache à deux exigences qu’elle ne parvient pas à satisfaire ensemble.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"},{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Examiner le devoir que l’on s’impose","reason":"Avant de valoriser le sacrifice, demander si l’obligation revendiquée relève de la justice ou de la préservation d’un rang.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-amour-et-duree-douloureuse","code":"CO14","author":"Corneille","title":"L’amour dans une mort qui dure","work":"Suréna","locator":"Acte I, scène III","quote":"Je veux, sans que la mort ose me secourir,\nToujours aimer, toujours souffrir, toujours mourir.","speaker":"Eurydice","situation":"Promise à Pacorus, Eurydice refuse que la mort abrège son amour douloureux pour Suréna.","notions":["temps","bonheur"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on vouloir prolonger une souffrance plutôt que renoncer à ce qui la fait naître ?"},{"function":"L’affirmation","sentence":"Eurydice souhaite continuer d’aimer et de souffrir sans que la mort interrompe cette fidélité."},{"function":"Les concepts","sentence":"Toujours mourir ne désigne pas des décès répétés, mais une douleur qui semble recommencer à chaque instant."},{"function":"La raison","sentence":"La reprise du même adverbe lie l’amour, la souffrance et la durée dans un mouvement sans repos."},{"function":"L’exemple","sentence":"Promise à Pacorus, Eurydice demande ensuite à Suréna de ne pas épouser Mandane."},{"function":"La portée","sentence":"Le passage montre un attachement dont la valeur ne se réduit pas au plaisir, sans faire de la souffrance une preuve nécessaire de l’amour."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Examiner le prix du renoncement","reason":"Montrer qu’un sujet peut refuser l’apaisement s’il lui paraît signifier l’abandon d’un attachement essentiel.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Faire sentir une durée affective","reason":"Après le temps mesuré, examiner une douleur où chaque moment semble reconduire la même épreuve.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-silence-et-aveu","code":"CO15","author":"Corneille","title":"Quand le silence révèle","work":"Suréna","locator":"Acte IV, scène IV","quote":"Le soin de le cacher découvre ce qu'il cache,\nEt son silence dit tout ce qu'il craint qu'on sache.","speaker":"Pacorus","situation":"Pacorus soupçonne l’amour secret de Suréna malgré les précautions prises pour le dissimuler.","notions":["langage","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Se taire suffit-il à garder un secret ?"},{"function":"L’affirmation","sentence":"Pacorus affirme que les précautions prises pour cacher un amour finissent par le révéler."},{"function":"Les concepts","sentence":"Le silence ne vaut plus absence de signe : il devient une conduite susceptible d’être interprétée."},{"function":"La raison","sentence":"Le souci de dissimuler modifie les gestes et les refus, qui peuvent attirer précisément l’attention que l’on voulait éviter."},{"function":"L’exemple","sentence":"Pacorus juge trop préparées les raisons par lesquelles Suréna refuse d’épouser Mandane."},{"function":"La portée","sentence":"Le langage déborde ainsi les paroles prononcées, sans que tout silence autorise une interprétation certaine ni une intrusion dans la vie d’autrui."}],"uses":[{"subject":"Le langage trahit-il la pensée ?","function":"Examiner les signes involontaires","reason":"Après la parole maîtrisée, montrer qu’une précaution ou un silence peut exprimer ce que le sujet voulait taire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Le langage n’est-il qu’un outil ?","function":"Interroger la maîtrise des signes","reason":"Faire apparaître des significations produites par une conduite qui échappe en partie à l’usage volontaire du langage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-service-et-ingratitude","code":"CO16","author":"Corneille","title":"Le bienfait qui devient une menace","work":"Suréna","locator":"Acte V, scène II","quote":"Plus on sert des ingrats, plus on s'en fait haïr :\nTout ce qu'on fait pour eux ne fait que nous trahir.","speaker":"Suréna","situation":"Suréna explique à Eurydice pourquoi ses services rendus au roi se retournent contre lui.","notions":["etat","devoir"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Rendre service assure-t-il la reconnaissance de celui qui en bénéficie ?"},{"function":"L’affirmation","sentence":"Suréna explique que ses services ont accru la haine du roi au lieu de lui garantir sa faveur."},{"function":"Les concepts","sentence":"Le service crée une dette, mais aussi la conscience d’une dépendance envers celui dont le mérite devient difficile à égaler."},{"function":"La raison","sentence":"Le souverain peut alors éprouver comme une humiliation ce qui devrait l’engager à la gratitude."},{"function":"L’exemple","sentence":"Suréna estime que sa gloire et les victoires qui ont soutenu le roi sont devenues son véritable crime."},{"function":"La portée","sentence":"La gratitude dépend donc du rapport au bienfaiteur, sans que cette situation permette de déclarer tout service vain ou toute reconnaissance impossible."}],"uses":[{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Examiner la peur du mérite d’autrui","reason":"Montrer comment un souverain peut transformer son besoin d’être aidé en désir d’abaisser celui dont il dépend.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-amour-et-contrainte","code":"CO17","author":"Corneille","title":"L’amour ne se commande pas","work":"Suréna","locator":"Acte IV, scène IV","quote":"Il hait tous les emplois où la force l'appelle :\nDès qu'on le violente, on en fait un rebelle ;","speaker":"Suréna","situation":"Suréna explique à Pacorus que l’amour ne peut obéir aux ordres du pouvoir.","notions":["liberte","etat"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le pouvoir de commander les actes donne-t-il celui de commander les sentiments ?"},{"function":"L’affirmation","sentence":"Suréna affirme que l’amour se révolte contre les tâches auxquelles la force veut l’employer."},{"function":"Les concepts","sentence":"La personnification fait de l’amour un sujet rebelle, distinct de l’obéissance qu’un souverain peut exiger."},{"function":"La raison","sentence":"La contrainte peut obtenir une conduite extérieure sans produire l’attachement qui lui donnerait un autre sens."},{"function":"L’exemple","sentence":"Pacorus exige que Suréna intervienne pour changer les sentiments d’Eurydice, alors qu’il ne maîtrise pas davantage les siens."},{"function":"La portée","sentence":"Le passage révèle une limite du commandement, sans faire de toute passion une liberté déjà réfléchie ni de tout refus un droit sans condition."}],"uses":[{"subject":"La liberté exclut-elle l’obéissance ?","function":"Distinguer conduite et adhésion","reason":"Après l’obéissance extérieure, examiner ce qu’un ordre ne peut produire par lui-même dans le sentiment du sujet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"L’État est-il, par définition, indifférent aux intérêts particuliers ?","function":"Délimiter la prétention du pouvoir","reason":"Montrer le conflit né lorsqu’un projet politique exige non seulement des actes, mais la transformation des attachements privés.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-alliance-et-interet","code":"CO18","author":"Corneille","title":"L’allié et l’ennemi de l’ennemi","work":"Nicomède","locator":"Acte IV, scène V","quote":"Rome ne m'aime pas : elle hait Nicomède ;","speaker":"Attale","situation":"Attale reconnaît devant Flaminius que Rome le soutient pour affaiblir son frère Nicomède.","notions":["etat","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le soutien d’une puissance prouve-t-il qu’elle recherche notre bien ?"},{"function":"L’affirmation","sentence":"Attale comprend que Rome le favorise pour affaiblir Nicomède plutôt que par attachement à sa personne."},{"function":"Les concepts","sentence":"L’opposition entre aimer et haïr sépare le bénéficiaire apparent de l’action et sa cible véritable."},{"function":"La raison","sentence":"Une aide peut donc servir celui qui la reçoit tout en restant subordonnée à un intérêt qui lui est extérieur."},{"function":"L’exemple","sentence":"Flaminius soutient les ambitions d’Attale, mais refuse qu’elles conduisent à l’union politique qui renforcerait le royaume."},{"function":"La portée","sentence":"La convergence provisoire des intérêts ne suffit pas à établir une fidélité, sans rendre pour autant toute coopération mensongère."}],"uses":[{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Distinguer aide et bienveillance","reason":"Lorsqu’une action profite à autrui, examiner si ce profit constitue sa fin ou le moyen d’atteindre un autre adversaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La recherche du bonheur est-elle un idéal égoïste ?","function":"Examiner un avantage partagé sans désintéressement","reason":"Distinguer une convergence d’intérêts et la volonté de rechercher le bien de l’autre pour lui-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"bachelard-lumiere-et-ombres","code":"BA01","author":"Bachelard","title":"La connaissance éclaire et laisse des ombres","quote":"La connaissance du réel est une lumière qui projette toujours quelque part des ombres.","locator":"Chapitre I, section I","notions":["science","verite","raison"],"commentary":[{"function":"Le problème","sentence":"Connaître un aspect du réel signifie-t-il dissiper toute obscurité ?"},{"function":"L’affirmation","sentence":"Bachelard affirme que la connaissance éclaire tout en laissant subsister des zones d’ombre."},{"function":"Les concepts","sentence":"La lumière désigne une compréhension déterminée, tandis que l’ombre marque ses limites et les difficultés qu’elle peut masquer."},{"function":"La raison","sentence":"Un savoir acquis peut devenir un obstacle lorsqu’on le prend pour une explication complète et qu’on cesse de l’interroger."},{"function":"L’exemple","sentence":"Une généralisation utile peut ainsi empêcher de remarquer les phénomènes qui exigent de la modifier."},{"function":"La portée","sentence":"L’image invite à prolonger la recherche et à rectifier le savoir, sans conclure que toutes les connaissances seraient illusoires."}],"uses":[{"subject":"Faut-il attendre de la science qu’elle ait réponse à tout ?","function":"Limiter une attente de savoir total","reason":"Distinguer une connaissance fondée de la prétention à dissiper d’un seul coup toutes les difficultés.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Les progrès de la connaissance nous rapprochent-ils d’une vérité définitive ?","function":"Interroger l’idée d’achèvement","reason":"Montrer qu’un progrès peut faire apparaître des limites nouvelles et appeler une nouvelle enquête.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=72","sourceLabel":"Recueil académique · p. 72"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-question-et-connaissance","code":"BA02","author":"Bachelard","title":"Le savoir répond à un problème","quote":"Pour un esprit scientifique, toute connaissance est une réponse à une question.","locator":"Chapitre I, section I","notions":["science","raison","verite"],"commentary":[{"function":"Le problème","sentence":"Suffit-il d’accumuler des faits pour posséder un savoir ?"},{"function":"L’affirmation","sentence":"Bachelard rapporte la connaissance scientifique à la question qui lui donne son sens."},{"function":"Les concepts","sentence":"La question est ici un problème construit, et la réponse une proposition dont on peut comprendre la nécessité et les conditions."},{"function":"La raison","sentence":"Sans problème précis, un fait risque de rester une curiosité ou de confirmer une opinion déjà installée."},{"function":"L’exemple","sentence":"Demander comment varie une résistance électrique permet d’organiser des mesures plutôt que de collectionner des étincelles spectaculaires."},{"function":"La portée","sentence":"La recherche demande donc une activité de l’esprit, sans que cette construction dispense de contrôler expérimentalement la réponse."}],"uses":[{"subject":"Les faits parlent-ils d’eux-mêmes ?","function":"Établir la nécessité d’une question","reason":"Expliquer pourquoi un fait ne devient instructif qu’à l’intérieur d’un problème qui précise ce qu’il permet de vérifier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"La connaissance scientifique progresse-t-elle par l’accumulation des observations ?","function":"Distinguer accumulation et recherche","reason":"Montrer que multiplier les observations ne remplace pas la formulation d’un problème et le choix des observations pertinentes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-formation-et-reforme","code":"BA03","author":"Bachelard","title":"Apprendre exige de se corriger","quote":"L'esprit scientifique doit se former en se réformant.","locator":"Chapitre II, section I","notions":["science","raison","verite"],"commentary":[{"function":"Le problème","sentence":"L’esprit devient-il scientifique en ajoutant simplement des connaissances à ce qu’il sait déjà ?"},{"function":"L’affirmation","sentence":"Bachelard affirme que sa formation exige une transformation de ses façons de penser."},{"function":"Les concepts","sentence":"Se former signifie acquérir une capacité, tandis que se réformer implique de corriger des habitudes et des convictions antérieures."},{"function":"La raison","sentence":"Les premières explications ne sont pas seulement incomplètes, car elles peuvent empêcher de poser les questions utiles."},{"function":"L’exemple","sentence":"L’élève qui admire une expérience spectaculaire doit apprendre à isoler la relation précise qu’elle permet d’étudier."},{"function":"La portée","sentence":"La correction participe ainsi du progrès, sans faire de toute erreur une découverte ni de toute nouveauté une vérité."}],"uses":[{"subject":"L’erreur a-t-elle un rôle dans l’élaboration de la vérité ?","function":"Montrer une correction formatrice","reason":"Présenter l’erreur analysée comme ce qui oblige à modifier une manière de connaître, plutôt que comme un simple manque de résultat.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"La connaissance commune est-elle, pour la connaissance scientifique, un point d’appui ou un obstacle ?","function":"Décrire une transformation du savoir premier","reason":"Expliquer pourquoi passer à une enquête scientifique peut exiger de réformer les évidences de l’expérience quotidienne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-concept-et-deformation","code":"BA04","author":"Bachelard","title":"Un concept fécond peut se transformer","quote":"En effet, d'après nous, la richesse d'un concept scientifique se mesure à sa puissance de déformation.","locator":"Chapitre III, section III","notions":["science","raison"],"commentary":[{"function":"Le problème","sentence":"Un concept est-il d’autant plus solide qu’il reste identique en toute circonstance ?"},{"function":"L’affirmation","sentence":"Bachelard mesure sa richesse à sa capacité de transformation."},{"function":"Les concepts","sentence":"La déformation désigne une modification réglée du concept pour intégrer des conditions nouvelles, et non une déformation arbitraire des faits."},{"function":"La raison","sentence":"Une définition trop rigide peut réunir des ressemblances apparentes tout en empêchant d’étudier les différences pertinentes."},{"function":"L’exemple","sentence":"L’étude de la fermentation progresse lorsqu’elle distingue les processus et leurs conditions, au lieu d’expliquer tout changement par un même mot."},{"function":"La portée","sentence":"La rigueur consiste donc aussi à rendre les concepts révisables, sans renoncer à leur précision."}],"uses":[{"subject":"Les vérités scientifiques sont-elles définitives ?","function":"Distinguer rigueur et immobilité","reason":"Montrer comment la transformation d’un concept peut accroître la précision du savoir au lieu de simplement le rendre incertain.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"Une théorie scientifique doit-elle se prémunir contre toute critique ?","function":"Donner une fonction positive à la révision","reason":"Expliquer pourquoi protéger un concept de toute modification peut diminuer sa capacité à rendre compte de nouveaux phénomènes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-concept-et-realisation","code":"BA05","author":"Bachelard","title":"La technique participe au concept scientifique","quote":"Un concept est devenu scientifique dans la proportion où il est devenu technique, où il est accompagné d'une technique de réalisation.","locator":"Chapitre III, section III","notions":["science","technique","raison"],"commentary":[{"function":"Le problème","sentence":"La technique intervient-elle seulement après que la science a produit ses connaissances ?"},{"function":"L’affirmation","sentence":"Bachelard lie le caractère scientifique d’un concept à une technique qui permet de le réaliser."},{"function":"Les concepts","sentence":"Réaliser signifie ici produire ou isoler un phénomène dans des conditions déterminées, pour éprouver ce que le concept affirme."},{"function":"La raison","sentence":"Les opérations techniques donnent aux distinctions théoriques une prise sur des phénomènes contrôlables."},{"function":"L’exemple","sentence":"Les procédés de stérilisation permettent ainsi de préciser les conditions de la fermentation et de distinguer ce qui la rend possible."},{"function":"La portée","sentence":"La technique peut donc contribuer à la construction du savoir, sans que toute recette efficace constitue déjà une science."}],"uses":[{"subject":"La technique n’est-elle qu’une application de la science ?","function":"Renverser une dépendance à sens unique","reason":"Montrer que certaines opérations techniques permettent de définir et de contrôler le phénomène dont la science forme le concept.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"Le progrès scientifique est-il lié à l’évolution des techniques ?","function":"Expliquer une dépendance concrète","reason":"Relier un progrès de conceptualisation à de nouvelles possibilités de production, d’isolement ou de contrôle des phénomènes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-metaphores-et-raison","code":"BA06","author":"Bachelard","title":"Une image séduisante peut arrêter la pensée","quote":"Qu'on le veuille ou non, les métaphores séduisent la raison.","locator":"Chapitre IV, section III","notions":["langage","raison","science"],"commentary":[{"function":"Le problème","sentence":"Une image qui rend un phénomène familier nous en donne-t-elle l’explication ?"},{"function":"L’affirmation","sentence":"Bachelard souligne le pouvoir de séduction des métaphores sur la raison elle-même."},{"function":"Les concepts","sentence":"La séduction produit une adhésion, tandis que l’explication doit établir des relations contrôlables."},{"function":"La raison","sentence":"En projetant les propriétés d’un objet connu sur un phénomène différent, une image peut faire croire que la question est résolue."},{"function":"L’exemple","sentence":"Comparer l’air à une éponge suggère qu’il absorbe des matières sans expliquer les conditions précises de cette absorption."},{"function":"La portée","sentence":"La critique vise l’image prise pour une preuve, sans supprimer la valeur poétique des métaphores ni leur usage pédagogique contrôlé."}],"uses":[{"subject":"Le langage peut-il être un obstacle à la recherche de la vérité ?","function":"Analyser une fausse explication","reason":"Montrer comment une métaphore familière peut donner l’impression de comprendre et interrompre l’enquête.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35"},{"subject":"La démarche scientifique exclut-elle tout recours à l’imagination ?","function":"Distinguer suggestion et justification","reason":"Examiner l’utilité d’une image en exigeant que ses suggestions soient reprises et contrôlées par un travail conceptuel.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=59","sourceLabel":"Recueil académique · p. 59"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-passion-et-erreur","code":"BA07","author":"Bachelard","title":"Une passion vraie peut protéger une idée fausse","quote":"C'est alors la passion vraie qui forme obstacle à la rectification de l'idée fausse.","locator":"Chapitre VII, section III","notions":["verite","conscience","raison"],"commentary":[{"function":"Le problème","sentence":"La sincérité d’un sentiment garantit-elle la vérité du jugement qu’il soutient ?"},{"function":"L’affirmation","sentence":"Bachelard montre qu’une passion réellement éprouvée peut empêcher de corriger une idée fausse."},{"function":"Les concepts","sentence":"Vraie qualifie ici l’existence de la passion, non la justesse de la croyance qui lui est associée."},{"function":"La raison","sentence":"Le sujet peut prendre le réconfort qu’il ressent pour une preuve de la propriété qu’il attribue à un objet."},{"function":"L’exemple","sentence":"La joie de posséder de l’or a ainsi été confondue avec une prétendue efficacité médicale de cette matière."},{"function":"La portée","sentence":"Il faut donc distinguer authenticité affective et validation objective, sans nier la réalité de l’expérience vécue."}],"uses":[{"subject":"La certitude est-elle une garantie de vérité ?","function":"Distinguer force de conviction et preuve","reason":"Expliquer pourquoi une conviction peut être intense parce qu’elle protège une satisfaction, plutôt que parce qu’elle est fondée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Suffit-il de connaître la vérité pour renoncer à ses préjugés ?","function":"Identifier une résistance affective","reason":"Montrer qu’un attachement peut survivre à l’objection parce que l’abandon de l’idée coûterait aussi une satisfaction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=75","sourceLabel":"Recueil académique · p. 75"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-mesure-et-reflexion","code":"BA08","author":"Bachelard","title":"Mesurer demande de penser","quote":"Il faut réfléchir pour mesurer et non pas mesurer pour réfléchir.","locator":"Chapitre XI, section II","notions":["science","raison","technique"],"commentary":[{"function":"Le problème","sentence":"Une mesure chiffrée est-elle objective du seul fait qu’elle donne un nombre ?"},{"function":"L’affirmation","sentence":"Bachelard subordonne la mesure à une réflexion préalable sur ses conditions."},{"function":"Les concepts","sentence":"Mesurer suppose de définir la grandeur pertinente, la méthode employée et le degré de précision accessible."},{"function":"La raison","sentence":"Des décimales supplémentaires ne donnent aucun savoir si elles dépassent la sensibilité de l’appareil ou la stabilité de l’objet."},{"function":"L’exemple","sentence":"Calculer très précisément le rayon d’un arbre à partir d’une circonférence approximative fabrique une exactitude illusoire."},{"function":"La portée","sentence":"L’objectivité demande donc une précision justifiée, sans confondre l’approximation maîtrisée avec une mesure négligente."}],"uses":[{"subject":"Une vérité scientifique peut-elle être approximative ?","function":"Justifier une approximation réglée","reason":"Distinguer la connaissance des limites d’une mesure et l’accumulation trompeuse de chiffres.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"N’y a-t-il de science que de ce qui est mathématisable ?","function":"Préciser ce que signifie quantifier","reason":"Montrer que la présence de nombres ne suffit pas : il faut établir ce qui est mesuré et avec quelle validité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-instrument-et-objectivite","code":"BA09","author":"Bachelard","title":"L’instrument transforme l’observation","quote":"La connaissance devient objective dans la proportion où elle devient instrumentale.","locator":"Chapitre XI, section III","notions":["science","technique","raison"],"commentary":[{"function":"Le problème","sentence":"L’instrument remplace-t-il simplement un sens humain moins précis ?"},{"function":"L’affirmation","sentence":"Bachelard lui attribue un rôle dans la constitution même de l’objectivité."},{"function":"Les concepts","sentence":"Une connaissance instrumentale repose sur un dispositif construit, étalonné et soumis à des contrôles."},{"function":"La raison","sentence":"L’appareil ne donne un résultat fiable que si ses conditions de fonctionnement sont définies et ses erreurs repérées."},{"function":"L’exemple","sentence":"Une bulle d’air oubliée dans un baromètre suffit à modifier sa hauteur et à fausser les comparaisons."},{"function":"La portée","sentence":"La technique rend donc l’observation contrôlable, sans assurer par sa seule présence la vérité de toute interprétation."}],"uses":[{"subject":"Peut-on dire que la connaissance scientifique consiste à substituer à la sensibilité de l’homme celle d’un instrument de mesure ?","function":"Dépasser l’idée d’un simple remplacement","reason":"Expliquer que l’instrument impose aussi une méthode, des conditions de comparaison et un contrôle des erreurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Le progrès scientifique est-il lié à l’évolution des techniques ?","function":"Montrer une condition de l’observation objective","reason":"Étudier comment un instrument mieux construit permet de définir plus précisément le phénomène étudié.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-resultats-et-demonstration","code":"BA10","author":"Bachelard","title":"Savoir les résultats ne suffit pas","quote":"Mais l'enseignement des résultats de la science n'est jamais un enseignement scientifique.","locator":"Chapitre XI, section VII","notions":["science","raison","verite"],"commentary":[{"function":"Le problème","sentence":"Connaître les conclusions d’une science suffit-il pour penser scientifiquement ?"},{"function":"L’affirmation","sentence":"Bachelard distingue la transmission des résultats et la formation à leur démarche de production."},{"function":"Les concepts","sentence":"Le résultat est une proposition retenue, tandis que l’enseignement scientifique rend compréhensibles les raisons qui l’établissent."},{"function":"La raison","sentence":"Sans ces raisons, l’élève risque de rattacher la formule apprise à des images ou à des explications personnelles erronées."},{"function":"L’exemple","sentence":"Retenir que l’orbite terrestre est une ellipse ne fait pas comprendre le rôle de ses foyers ni la loi du mouvement."},{"function":"La portée","sentence":"Apprendre une science demande donc de pouvoir reconstruire et discuter ses raisons, au-delà de la récitation de ses acquis."}],"uses":[{"subject":"Savoir, est-ce ne rien croire ?","function":"Distinguer savoir personnel et confiance reçue","reason":"Examiner le statut d’un résultat admis sur l’autorité d’un cours, puis la compréhension des raisons qui permet de se l’approprier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Les résultats des sciences sont-ils indiscutables ?","function":"Réintroduire les raisons du résultat","reason":"Montrer qu’une conclusion ne devient pas scientifique en étant soustraite à l’explication et à l’examen.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-enseigner-et-apprendre","code":"BA11","author":"Bachelard","title":"Transmettre met le savoir à l’épreuve","quote":"Une instruction qu'on reçoit sans la transmettre forme des esprits sans dynamisme, sans autocritique.","locator":"Chapitre XII, section II","notions":["science","langage","raison"],"commentary":[{"function":"Le problème","sentence":"Recevoir une connaissance assure-t-il qu’on puisse en répondre par soi-même ?"},{"function":"L’affirmation","sentence":"Bachelard fait de la transmission un exercice qui développe l’activité et la critique de l’esprit."},{"function":"Les concepts","sentence":"Transmettre demande de rendre des raisons accessibles à autrui, et l’autocritique consiste à examiner ses propres insuffisances."},{"function":"La raison","sentence":"Les difficultés d’un interlocuteur obligent à reprendre ce qui paraissait évident et à préciser les étapes laissées implicites."},{"function":"L’exemple","sentence":"Un élève qui explique une démonstration à un camarade découvre parfois qu’il en connaissait la conclusion sans maîtriser un passage."},{"function":"La portée","sentence":"L’apprentissage gagne ainsi à devenir réciproque, sans réduire la vérité à l’accord du groupe ni dévaloriser tout travail solitaire."}],"uses":[{"subject":"A-t-on besoin des autres pour trouver la vérité ?","function":"Donner une fonction au contrôle réciproque","reason":"Montrer comment expliquer à autrui peut révéler une difficulté et conduire à rectifier son propre raisonnement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=75","sourceLabel":"Recueil académique · p. 75"},{"subject":"Pourquoi échanger des idées ?","function":"Dépasser la simple circulation des opinions","reason":"Présenter l’échange comme une mise à l’épreuve des raisons de chacun, qui peut modifier leur compréhension.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-objet-et-transformation","code":"BA12","author":"Bachelard","title":"Connaître transforme celui qui connaît","quote":"Si l'objet m'instruit, il me modifie.","locator":"Chapitre XII, section II","notions":["science","conscience","raison"],"commentary":[{"function":"Le problème","sentence":"Connaître change-t-il seulement ce que nous savons du monde ?"},{"function":"L’affirmation","sentence":"Bachelard affirme que l’objet instruit en transformant aussi l’esprit qui l’étudie."},{"function":"Les concepts","sentence":"L’instruction n’est pas ici une simple information ajoutée, mais une modification de nos manières de comprendre."},{"function":"La raison","sentence":"Un phénomène qui résiste à nos prévisions oblige à réviser nos concepts et les attentes qui guidaient l’enquête."},{"function":"L’exemple","sentence":"La découverte d’un mouvement que le modèle prévu n’explique pas peut imposer de nouvelles relations mathématiques."},{"function":"La portée","sentence":"La connaissance possède ainsi une force formatrice, sans que le réel se réduise à ce que le sujet souhaite y trouver."}],"uses":[{"subject":"Avons-nous quelque chose à apprendre de nos erreurs ?","function":"Montrer une transformation du sujet","reason":"Expliquer qu’une erreur instruite peut modifier les habitudes de pensée qui la produisaient.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=76","sourceLabel":"Recueil académique · p. 76"},{"subject":"La science nous éloigne-t-elle de la réalité ?","function":"Distinguer rencontre et projection","reason":"Montrer qu’atteindre le réel peut demander de renoncer à nos représentations familières plutôt que de les retrouver partout.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-maitre-et-contradiction","code":"BA13","author":"Bachelard","title":"Continuer une pensée en la contredisant","quote":"Dans l'œuvre de la science seulement on peut aimer ce qu'on détruit, on peut continuer le passé en le niant, on peut vénérer son maître en le contredisant.","locator":"Chapitre XII, section III","notions":["science","verite","raison","temps"],"commentary":[{"function":"Le problème","sentence":"Respecter un héritage intellectuel exige-t-il de le conserver intact ?"},{"function":"L’affirmation","sentence":"Bachelard présente la contradiction scientifique comme une manière de prolonger ce que l’on admire."},{"function":"Les concepts","sentence":"Détruire et nier désignent ici la critique de résultats ou de cadres explicatifs, tandis que continuer signifie reprendre leur exigence de recherche."},{"function":"La raison","sentence":"On peut rester fidèle à la démarche d’un maître précisément en refusant de transformer ses réponses en dogmes."},{"function":"L’exemple","sentence":"Une théorie nouvelle peut limiter la validité d’une théorie ancienne tout en expliquant pourquoi celle-ci réussissait dans certaines conditions."},{"function":"La portée","sentence":"La fidélité devient alors un travail critique, sans faire de toute rupture un progrès ni de cette formule une loi de toute activité humaine."}],"uses":[{"subject":"Y a-t-il contradiction entre la prétention des sciences à la vérité et le fait qu’elles ont une histoire ?","function":"Penser une continuité par rectification","reason":"Montrer que la reprise critique du passé peut conserver ses problèmes et expliquer ses réussites en limitant ses prétentions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"},{"subject":"Peut-on remettre en question une vérité établie scientifiquement ?","function":"Distinguer critique et rejet arbitraire","reason":"Présenter une contestation appuyée sur des raisons comme la poursuite du travail scientifique lui-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"freud-souvenirs-remanies","code":"F01","author":"Freud","title":"Se souvenir, c’est aussi remanier","quote":"Nos souvenirs d’enfance ne nous montrent pas les premières années de la vie telles qu’elles étaient, mais telles qu’elles sont apparues au cours de périodes d’éveil ultérieures.","locator":"Conclusion du texte (1899)","notions":["temps","conscience","inconscient"],"commentary":[{"function":"Le problème","sentence":"Nos souvenirs nous donnent-ils un accès intact à ce que nous avons vécu ?"},{"function":"L’affirmation","sentence":"Freud soutient que les souvenirs d’enfance portent la marque de remaniements ultérieurs."},{"function":"Les concepts","sentence":"Le passé vécu se distingue de sa présentation psychique, qui peut être réorganisée par des désirs et des préoccupations plus tardifs."},{"function":"La raison","sentence":"Un détail conservé peut prendre sa force dans une situation postérieure et servir de substitut à un autre contenu."},{"function":"L’exemple","sentence":"Dans le souvenir de la prairie, les fleurs et le pain prennent sens lorsque Freud les rapproche des préoccupations ultérieures de son interlocuteur."},{"function":"La portée","sentence":"La mémoire devient ainsi un objet d’interprétation, sans que cela autorise à déclarer tout souvenir inventé."}],"uses":[{"subject":"Pourquoi cherchons-nous à connaître notre passé ?","function":"Distinguer souvenir et connaissance de soi","reason":"Montrer que l’enquête sur le passé doit aussi examiner la manière dont le souvenir s’est constitué.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"La conscience de soi est-elle une connaissance ?","function":"Limiter l’évidence du souvenir","reason":"Expliquer pourquoi un souvenir présent à la conscience peut demander une interprétation au lieu de fournir immédiatement la vérité du passé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"work":"Les souvenirs-écrans","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Olivier Mannoni","editionNote":"Traduction de 2019 ; référence au texte original, repris dans ce recueil."},{"id":"freud-repeter-sans-savoir","code":"F02","author":"Freud","title":"Le passé peut revenir dans l’action","quote":"Il ne le reproduit pas comme souvenir, mais comme acte, il le réitère, sans savoir bien entendu qu’il le répète.","locator":"L’agir dans la cure (1914)","notions":["inconscient","conscience","liberte","temps"],"commentary":[{"function":"Le problème","sentence":"Un passé oublié cesse-t-il pour autant d’agir dans le présent ?"},{"function":"L’affirmation","sentence":"Freud décrit un patient qui reproduit dans ses actes ce qu’il ne se remémore pas."},{"function":"Les concepts","sentence":"Le pronom renvoie au contenu oublié ou refoulé, et la répétition désigne son retour dans une conduite présente."},{"function":"La raison","sentence":"Le sujet peut donc éprouver comme une réaction actuelle ce qui reprend une ancienne manière d’entrer en relation."},{"function":"L’exemple","sentence":"Dans la cure, il peut se montrer méfiant envers l’analyste sans reconnaître le retour d’une défiance ancienne envers une figure d’autorité."},{"function":"La portée","sentence":"L’oubli ne suffit donc pas à libérer du passé, sans que toute conduite répétée prouve à elle seule un refoulement."}],"uses":[{"subject":"Pour se libérer du passé faut-il l’oublier ?","function":"Contester la suffisance de l’oubli","reason":"Montrer que l’absence de souvenir conscient peut coexister avec la persistance d’une conduite héritée du passé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"L’inconscient pèse-t-il sur nous comme un destin ?","function":"Distinguer contrainte méconnue et fatalité","reason":"Présenter la répétition comme une détermination à reconnaître et à travailler, sans conclure qu’elle serait irréversible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=28","sourceLabel":"Recueil académique · p. 28"}],"work":"Remémoration, répétition et perlaboration","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Olivier Mannoni","editionNote":"Traduction de 2019 ; référence au texte original, repris dans ce recueil."},{"id":"freud-modele-et-limites","code":"F03","author":"Freud","title":"Une analogie éclaire sans tout expliquer","quote":"Il faut bien que l’analogie d’un appareil supplétif de ce type avec l’organe modèle prenne fin quelque part.","locator":"Les limites du modèle (1925)","notions":["science","technique","raison"],"commentary":[{"function":"Le problème","sentence":"Un appareil qui ressemble à un fonctionnement psychique permet-il de l’expliquer entièrement ?"},{"function":"L’affirmation","sentence":"Freud reconnaît une limite à l’analogie qu’il construit avec le bloc magique."},{"function":"Les concepts","sentence":"L’appareil supplétif est un support externe de mémoire, tandis que l’organe modèle désigne l’appareil psychique qu’il aide à penser."},{"function":"La raison","sentence":"La comparaison rend certaines relations intelligibles sans garantir que tous les fonctionnements se correspondent."},{"function":"L’exemple","sentence":"Le bloc magique associe une surface disponible pour de nouvelles inscriptions et des traces durables, mais ne reproduit pas par lui-même ces traces de manière vivante."},{"function":"La portée","sentence":"Un modèle doit donc être jugé aussi par ses limites, sans perdre pour autant toute valeur explicative."}],"uses":[{"subject":"L’imagination a-t-elle une place dans la connaissance scientifique ?","function":"Délimiter la valeur d’une analogie","reason":"Montrer qu’un modèle imaginé peut rendre un problème intelligible si l’on précise ce qu’il permet et ce qu’il ne reproduit pas.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=59","sourceLabel":"Recueil académique · p. 59"},{"subject":"Le vivant est-il un objet comme les autres ?","function":"Limiter la comparaison avec un appareil","reason":"Examiner ce que l’analogie technique fait comprendre d’une fonction vivante et ce qu’elle laisse sans équivalent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"}],"work":"Note sur le « bloc magique »","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Olivier Mannoni","editionNote":"Traduction de 2019 ; référence au texte original, repris dans ce recueil."},{"id":"freud-moi-et-inconscient","code":"F04","author":"Freud","title":"Le moi déborde la conscience","quote":"Il est certain qu’une grande part du moi est elle-même inconsciente, précisément ce que l’on peut nommer le noyau du moi ; le terme de préconscient ne recouvre qu’une petite partie du moi.","locator":"Chapitre III, passage sur la résistance (formulation remaniée en 1921)","notions":["inconscient","conscience"],"commentary":[{"function":"Le problème","sentence":"Le moi coïncide-t-il avec ce dont le sujet a conscience ?"},{"function":"L’affirmation","sentence":"Freud affirme qu’une part importante du moi demeure elle-même inconsciente."},{"function":"Les concepts","sentence":"Le moi désigne une organisation psychique, tandis que conscient et préconscient qualifient des modes d’accès aux contenus psychiques."},{"function":"La raison","sentence":"Les défenses qui maintiennent certains contenus à distance peuvent agir sans être reconnues par celui qui les exerce."},{"function":"L’exemple","sentence":"Dans la cure, le patient peut résister à une association sans connaître le motif de cette résistance."},{"function":"La portée","sentence":"L’inconscient ne se réduit donc pas à un second personnage opposé au moi, et cette distinction demande une enquête au-delà de l’introspection immédiate."}],"uses":[{"subject":"L’hypothèse de l’inconscient psychique revient-elle à admettre un autre moi en moi ?","function":"Écarter le dédoublement en personnages","reason":"Distinguer la part inconsciente du moi et l’image trompeuse d’un étranger intérieur qui déciderait à sa place.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=29","sourceLabel":"Recueil académique · p. 29"},{"subject":"Peut-on parvenir à une complète conscience de soi ?","function":"Identifier une difficulté de l’introspection","reason":"Montrer que le sujet ne reconnaît pas immédiatement les mécanismes par lesquels il se défend contre certaines pensées.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"work":"Au-delà du principe de plaisir","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Jean Laplanche et J.-B. Pontalis","editionNote":"Extrait d’Au-delà du principe de plaisir, dans la traduction publiée chez Payot en 2010 et reprise dans ce recueil ; les trois premiers essais du recueil ont un autre traducteur."},{"id":"freud-jeu-et-deplaisir","code":"F05","author":"Freud","title":"Le jeu peut reprendre une expérience pénible","quote":"On observe aussi que le caractère déplaisant de l’expérience vécue ne la rend pas toujours inutilisable pour le jeu.","locator":"Chapitre II, le jeu de la bobine","notions":["inconscient","art","conscience"],"commentary":[{"function":"Le problème","sentence":"Jouer consiste-t-il seulement à reproduire des expériences agréables ?"},{"function":"L’affirmation","sentence":"Freud observe qu’une expérience pénible peut aussi fournir la matière d’un jeu."},{"function":"Les concepts","sentence":"Le déplaisir de ce qui a été subi se distingue du plaisir possible à le reprendre activement."},{"function":"La raison","sentence":"Le changement de position permet d’envisager un gain de maîtrise, même si cette interprétation ne suffit pas à trancher tous les cas."},{"function":"L’exemple","sentence":"L’enfant qui fait disparaître et revenir une bobine reprend ainsi la situation de l’absence maternelle en devenant l’auteur du mouvement."},{"function":"La portée","sentence":"Le jeu ne reflète donc pas seulement un plaisir passé, sans constituer à lui seul une preuve de pulsion de mort ni une guérison assurée."}],"uses":[{"subject":"Nos désirs s’expliquent-ils seulement par la recherche du plaisir ?","function":"Distinguer plaisir immédiat et reprise d’une épreuve","reason":"Examiner comment le retour d’un événement pénible peut aussi viser une position plus active, sans prouver l’absence de toute satisfaction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"L’art est-il un divertissement ?","function":"Proposer une comparaison avec le jeu","reason":"Distinguer le caractère pénible d’un événement et l’intérêt de sa reprise dans une représentation, sans confondre jeu enfantin et œuvre d’art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"work":"Au-delà du principe de plaisir","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Jean Laplanche et J.-B. Pontalis","editionNote":"Extrait d’Au-delà du principe de plaisir, dans la traduction publiée chez Payot en 2010 et reprise dans ce recueil ; les trois premiers essais du recueil ont un autre traducteur."},{"id":"freud-pulsion-et-objet","code":"F06","author":"Freud","title":"L’objet ne suffit pas à expliquer le désir","quote":"Il est probable que la pulsion sexuelle commence par être indépendante de son objet et que ce n’est pas non plus aux charmes de celui-ci qu’elle doit sa genèse.","locator":"Premier essai, « Déduction »","notions":["nature","inconscient","conscience"],"commentary":[{"function":"Le problème","sentence":"Désirons-nous un objet uniquement parce qu’il possède des qualités attirantes ?"},{"function":"L’affirmation","sentence":"Freud avance que la pulsion sexuelle ne naît probablement pas de l’objet auquel elle s’attache."},{"function":"Les concepts","sentence":"La pulsion est une poussée, tandis que l’objet est ce par quoi elle cherche une satisfaction."},{"function":"La raison","sentence":"La diversité des attachements conduit à desserrer le lien apparemment naturel et nécessaire entre les deux."},{"function":"L’exemple","sentence":"Des personnes peuvent investir des objets différents, sans que les propriétés de ces objets suffisent à expliquer l’existence même de la poussée."},{"function":"La portée","sentence":"La proposition invite à examiner l’histoire des attachements, sans faire de tout désir un choix volontaire ni nier toute qualité des objets."}],"uses":[{"subject":"L’objet du désir en est-il la cause ?","function":"Distinguer poussée et objet d’attachement","reason":"Contester l’idée que les seules qualités de l’objet suffisent à produire et à expliquer le désir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Les hommes savent-ils ce qu’ils désirent ?","function":"Séparer objet désigné et origine du désir","reason":"Montrer que nommer ce qu’on désire ne signifie pas connaître les processus qui nous y attachent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-amour-et-autorite","code":"F07","author":"Freud","title":"L’amour peut donner autorité","quote":"La crédulité de l’amour devient ainsi une source importante, sinon originaire, de l’autorité.","locator":"Premier essai, « Surestimation de l’objet sexuel »","notions":["raison","conscience","liberte"],"commentary":[{"function":"Le problème","sentence":"Accordons-nous toujours notre confiance à quelqu’un parce que ses jugements sont fondés ?"},{"function":"L’affirmation","sentence":"Freud montre que l’attachement amoureux peut devenir une source d’autorité."},{"function":"Les concepts","sentence":"La crédulité désigne une adhésion insuffisamment examinée, et l’autorité le pouvoir reconnu à la parole d’une personne."},{"function":"La raison","sentence":"La surestimation de l’être aimé peut s’étendre de ses qualités désirées à ses capacités intellectuelles et à ses opinions."},{"function":"L’exemple","sentence":"On peut ainsi accepter le jugement d’une personne admirée dans un domaine où aucune compétence ne lui est pourtant reconnue."},{"function":"La portée","sentence":"L’analyse éclaire une origine affective de l’obéissance, sans réduire toute autorité à l’amour ni toute confiance à la crédulité."}],"uses":[{"subject":"La certitude est-elle une garantie de vérité ?","function":"Examiner une adhésion affective","reason":"Montrer comment l’assurance reçue d’une personne aimée peut être confondue avec une raison de tenir son jugement pour vrai.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Le désir est-il aveugle ?","function":"Décrire une extension de l’idéalisation","reason":"Analyser le passage de l’attrait amoureux à une confiance intellectuelle qui échappe à l’examen.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-pulsion-et-corps","code":"F08","author":"Freud","title":"Le psychisme ne se sépare pas simplement du corps","quote":"Pulsion est ainsi l’un des concepts de la démarcation entre le psychique et le corporel.","locator":"Premier essai, « Pulsions partielles et zones érogènes » (ajout de 1915)","notions":["nature","conscience","inconscient"],"commentary":[{"function":"Le problème","sentence":"Une poussée corporelle est-elle déjà une pensée, ou reste-t-elle étrangère au psychisme ?"},{"function":"L’affirmation","sentence":"Freud situe le concept de pulsion à la limite du corporel et du psychique."},{"function":"Les concepts","sentence":"La pulsion désigne la représentance psychique d’une excitation interne continue, plutôt qu’un simple stimulus extérieur."},{"function":"La raison","sentence":"Un processus organique peut ainsi imposer une exigence au travail psychique sans être directement connu par la conscience."},{"function":"L’exemple","sentence":"Le besoin de satisfaction mobilise des représentations et des conduites, au lieu de rester une modification locale d’un organe."},{"function":"La portée","sentence":"Le concept oblige donc à articuler corps et vie psychique, sans réduire cette dernière à la conscience ni expliquer toutes ses opérations par la physiologie."}],"uses":[{"subject":"La notion d’inconscient psychique est-elle contradictoire ?","function":"Distinguer psychique et conscient","reason":"Montrer pourquoi une force peut participer à la vie psychique par ses représentations et ses effets sans être immédiatement consciente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=28","sourceLabel":"Recueil académique · p. 28"},{"subject":"Sommes-nous conscients de ce que nous désirons ?","function":"Distinguer exigence et connaissance","reason":"Expliquer que subir une poussée et en connaître les sources ou les objets ne constituent pas une même opération.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-plaisir-et-relance","code":"F09","author":"Freud","title":"Le plaisir peut relancer le désir","quote":"Comment se fait-il que le plaisir ressenti suscite le besoin d’un plaisir plus grand ?","locator":"Troisième essai, « La tension sexuelle »","notions":["bonheur","raison","conscience"],"commentary":[{"function":"Le problème","sentence":"Le plaisir apaise-t-il nécessairement le besoin qui l’a fait rechercher ?"},{"function":"L’affirmation","sentence":"Freud demande pourquoi un plaisir peut au contraire susciter la recherche d’un plaisir accru."},{"function":"Les concepts","sentence":"Il distingue un plaisir qui stimule l’excitation et un plaisir de satisfaction qui met momentanément fin à la tension."},{"function":"La raison","sentence":"Une même expérience peut donc être agréable tout en faisant naître une exigence nouvelle."},{"function":"L’exemple","sentence":"Dans son analyse du plaisir préliminaire, une stimulation plaisante accroît l’excitation au lieu de l’éteindre."},{"function":"La portée","sentence":"Cette difficulté empêche d’identifier toute jouissance à un repos, sans établir que toute satisfaction humaine serait impossible."}],"uses":[{"subject":"Le désir nous condamne-t-il à l’insatisfaction ?","function":"Distinguer deux effets du plaisir","reason":"Montrer qu’un plaisir peut relancer la demande sans que tout plaisir ait nécessairement cet effet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Interroger la suffisance de la satisfaction ponctuelle","reason":"Examiner le cas où obtenir un plaisir augmente la demande, puis distinguer cette relance d’un bonheur durable.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-trouvaille-et-retrouvaille","code":"F10","author":"Freud","title":"Le nouveau porte la trace d’un ancien bonheur","quote":"La trouvaille d’objet est proprement une re-trouvaille.","locator":"Troisième essai, « La trouvaille d’objet »","notions":["temps","inconscient","conscience"],"commentary":[{"function":"Le problème","sentence":"Le premier objet d’un amour est-il entièrement nouveau pour celui qui le désire ?"},{"function":"L’affirmation","sentence":"Freud soutient que la trouvaille d’un objet reprend le modèle d’une satisfaction antérieure."},{"function":"Les concepts","sentence":"La retrouvaille désigne une relation à des traces psychiques, et non le retour nécessaire de la même personne."},{"function":"La raison","sentence":"L’attachement nouveau peut être orienté par les premières expériences de soin et de satisfaction, même lorsque celles-ci ne sont pas remémorées."},{"function":"L’exemple","sentence":"Freud prend pour modèle la satisfaction initiale de l’enfant nourri au sein et les relations qui se construisent dans son prolongement."},{"function":"La portée","sentence":"Aimer engage ainsi une histoire, sans condamner chacun à reproduire à l’identique ses attachements infantiles."}],"uses":[{"subject":"Tous nos désirs sont-ils personnels ?","function":"Examiner l’histoire singulière des attachements","reason":"Montrer comment un désir présent peut porter la trace d’expériences anciennes, sans être pour autant un choix transparent du sujet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=92","sourceLabel":"Recueil académique · p. 92"},{"subject":"Mon passé détermine-t-il mon avenir ?","function":"Distinguer modèle et fatalité","reason":"Présenter les traces du passé comme des conditions des attachements futurs, sans assimiler leur influence à un scénario intégralement fixé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=67","sourceLabel":"Recueil académique · p. 67"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-beaute-et-desir","code":"F11","author":"Freud","title":"Le beau et le désir peuvent avoir une histoire commune","quote":"Il me semble indubitable que le concept de « beau » s’enracine dans le terreau de l’excitation sexuelle et signifie originairement ce qui est sexuellement stimulant (« die Reize »).","locator":"Premier essai, « Palper et regarder », note 27 (ajout de 1915)","notions":["art","nature","conscience"],"commentary":[{"function":"Le problème","sentence":"Le jugement de beauté peut-il être compris sans examiner ses liens avec le désir ?"},{"function":"L’affirmation","sentence":"Freud propose de chercher une origine du beau dans l’excitation sexuelle."},{"function":"Les concepts","sentence":"S’enraciner désigne une genèse, tandis que signifier originairement ne revient pas à définir tous les usages ultérieurs du mot."},{"function":"La raison","sentence":"Une recherche sur la provenance d’un intérêt esthétique se distingue de l’affirmation que tout jugement de goût viserait une satisfaction sexuelle immédiate."},{"function":"L’exemple","sentence":"Dans la même note, Freud souligne que les organes les plus excitants ne sont pas nécessairement jugés beaux."},{"function":"La portée","sentence":"L’hypothèse ouvre donc une enquête sur les transformations du désir, sans suffire à réduire toute beauté à l’agrément sensuel."}],"uses":[{"subject":"Pourquoi sommes-nous sensibles à la beauté ?","function":"Proposer une hypothèse sur l’origine de l’intérêt esthétique","reason":"Distinguer la genèse pulsionnelle proposée par Freud et la valeur ou le sens d’une expérience esthétique particulière.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"},{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Distinguer origine et finalité","reason":"Examiner un enracinement possible de l’intérêt pour le beau dans le plaisir, sans en déduire que toute œuvre ne poursuit que cette fin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-parole-et-presence","code":"F12","author":"Freud","title":"Une voix rend le proche présent","quote":"Ça ne fait rien, répondit l’enfant, quand quelqu’un parle, il fait jour.","locator":"Troisième essai, « Angoisse infantile », note 17","notions":["langage","conscience"],"commentary":[{"function":"Le problème","sentence":"Une parole agit-elle seulement par les informations qu’elle transmet ?"},{"function":"L’affirmation","sentence":"Freud rapporte la réponse d’un enfant que la voix de sa tante rassure dans l’obscurité."},{"function":"Les concepts","sentence":"Le jour désigne ici une présence ressentie, et non un changement de l’éclairage matériel."},{"function":"La raison","sentence":"Entendre une personne aimée peut modifier la situation vécue en donnant un signe sensible que l’on n’est pas seul."},{"function":"L’exemple","sentence":"L’enfant demande à sa tante de parler alors même qu’il sait qu’il ne pourra pas la voir."},{"function":"La portée","sentence":"Cette scène éclaire la portée relationnelle de la parole, sans prouver qu’elle suffise à dissiper toute peur."}],"uses":[{"subject":"La parole a-t-elle le pouvoir de changer les choses ?","function":"Distinguer situation matérielle et expérience vécue","reason":"Montrer qu’une voix peut modifier le sentiment de solitude sans transformer la lumière ni les objets présents.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Le langage ne sert-il qu’à communiquer ?","function":"Préciser ce qui se joue dans la parole","reason":"Élargir l’analyse au signe de présence et au lien affectif, sans exclure que cette présence soit elle aussi communiquée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée.","speaker":"Un garçon de trois ans","situation":"Freud rapporte les paroles d’un enfant qui demande à sa tante de le rassurer en parlant dans le noir."},{"id":"simondon-culture-et-rencontre","code":"SI01","author":"Simondon","title":"La culture rapproche des vies éloignées","quote":"Car la culture est le seul moyen que nous ayons de participer à la vie des temps révolus et des sociétés étrangères de manière à les rendre moins révolus et moins étrangères.","locator":"« Humanisme culturel, humanisme négatif, humanisme nouveau » (1953)","notions":["raison","temps"],"commentary":[{"function":"Le problème","sentence":"La différence des époques et des coutumes condamne-t-elle les hommes à rester étrangers les uns aux autres ?"},{"function":"L’affirmation","sentence":"Simondon affirme que la culture permet de participer à des vies éloignées de la nôtre."},{"function":"Les concepts","sentence":"Participer signifie ici comprendre une expérience humaine, sans avoir à adopter toutes ses croyances."},{"function":"La raison","sentence":"Les œuvres et les savoirs transmis rendent accessibles des façons de vivre que notre seule expérience ne nous ferait pas rencontrer."},{"function":"L’exemple","sentence":"Lire une tragédie antique permet ainsi de reconnaître une épreuve humaine dans un monde très différent du nôtre."},{"function":"La portée","sentence":"La culture ouvre donc une possibilité de rapprochement, dont la réalisation exige un effort de compréhension."}],"uses":[{"subject":"La culture sépare-t-elle ou rapproche-t-elle les hommes ?","function":"Construire la possibilité du rapprochement","reason":"Montrer que la différence culturelle peut devenir l’occasion de comprendre une autre expérience humaine plutôt qu’un obstacle définitif.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=85","sourceLabel":"Recueil académique · p. 85"},{"subject":"La culture libère-t-elle des préjugés ?","function":"Préciser une condition de la libération","reason":"Expliquer que rencontrer des vies éloignées peut défaire la croyance selon laquelle nos propres usages seraient la seule mesure de l’humanité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=84","sourceLabel":"Recueil académique · p. 84"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-langage-perfectible","code":"SI02","author":"Simondon","title":"Le langage reste à inventer","quote":"Pour démystifier le langage, il faut le montrer inachevé, perfectible, en voie de constitution.","locator":"« Les encyclopédies et l’esprit encyclopédique » (vers 1950)","notions":["langage","raison"],"commentary":[{"function":"Le problème","sentence":"Les mots imposent-ils à la pensée un cadre définitivement fixé ?"},{"function":"L’affirmation","sentence":"Simondon invite à comprendre le langage comme une œuvre humaine encore perfectible."},{"function":"Les concepts","sentence":"Démystifier consiste à retirer aux mots leur apparence de réalités immuables et mystérieuses."},{"function":"La raison","sentence":"Retrouver leur histoire et les inventions de sens qu’ils conservent permet de les examiner et de les transformer."},{"function":"L’exemple","sentence":"Préciser le sens du mot liberté dans une discussion peut ainsi défaire une opposition qui semblait insurmontable."},{"function":"La portée","sentence":"Le langage peut être travaillé par la pensée, même si cette pensée doit partir de mots déjà disponibles."}],"uses":[{"subject":"Le langage trahit-il la pensée ?","function":"Dépasser la plainte contre les mots","reason":"Montrer que les limites du vocabulaire appellent un travail de précision et d’invention plutôt qu’un abandon du langage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Le langage détermine-t-il notre rapport au réel ?","function":"Limiter le caractère définitif de la détermination","reason":"Reconnaître que les mots orientent notre compréhension tout en soutenant que leur sens peut être repris et transformé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-technique-et-invention","code":"SI03","author":"Simondon","title":"La technique possède sa pensée propre","quote":"C’est refuser de comprendre la nature de l’être technique que de le considérer comme un sous-produit de la pensée scientifique ou un instrument au service des fins morales.","locator":"« L’ordre des objets techniques comme paradigme d’universalité axiologique dans la relation interhumaine » (vers 1956)","notions":["technique","science","devoir"],"commentary":[{"function":"Le problème","sentence":"Comprend-on une machine en connaissant seulement les lois qu’elle applique ou le but qu’elle sert ?"},{"function":"L’affirmation","sentence":"Simondon refuse de réduire l’être technique à l’application d’un savoir ou à un simple moyen."},{"function":"Les concepts","sentence":"L’être technique est ici un fonctionnement organisé qui relie des contraintes naturelles à des possibilités d’action."},{"function":"La raison","sentence":"Son invention exige de rendre compatibles plusieurs nécessités que la connaissance séparée des lois ne réunit pas encore."},{"function":"L’exemple","sentence":"Concevoir un moteur suppose ainsi d’organiser ensemble combustion, refroidissement et transmission du mouvement."},{"function":"La portée","sentence":"Cette autonomie de l’invention oblige à comprendre les techniques, sans les soustraire à la responsabilité morale."}],"uses":[{"subject":"La technique n’est-elle qu’une application de la science ?","function":"Contester la réduction à la science appliquée","reason":"Distinguer la connaissance des lois de l’invention d’un fonctionnement qui les fait agir ensemble.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"La technique est-elle moralement neutre ?","function":"Distinguer compréhension technique et évaluation morale","reason":"Établir qu’un objet possède une organisation propre avant d’examiner les fins qu’il permet de servir, sans conclure à son innocence morale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=63","sourceLabel":"Recueil académique · p. 63"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-liberte-et-relation","code":"SI04","author":"Simondon","title":"Agir librement entre soi et les autres","quote":"Un pur individualisme ou un pur sociologisme font évanouir la liberté de l’acte.","locator":"« L’ordre des objets techniques comme paradigme d’universalité axiologique dans la relation interhumaine » (vers 1956)","notions":["liberte","devoir"],"commentary":[{"function":"Le problème","sentence":"La liberté vient-elle seulement de l’individu ou des règles de la société ?"},{"function":"L’affirmation","sentence":"Simondon refuse d’expliquer l’acte libre exclusivement par l’un de ces deux termes."},{"function":"Les concepts","sentence":"L’individualisme isole les exigences personnelles, tandis que le sociologisme ramène l’action aux déterminations sociales."},{"function":"La raison","sentence":"L’acte libre invente une manière de rendre compatibles des exigences que les règles déjà établies ne suffisaient pas à accorder."},{"function":"L’exemple","sentence":"Dans un travail commun, proposer une nouvelle répartition des tâches peut concilier initiative personnelle et engagements collectifs."},{"function":"La portée","sentence":"La liberté se pense ainsi comme une invention dans la relation, dont la valeur reste à justifier."}],"uses":[{"subject":"Les hommes peuvent-ils s’associer sans renoncer à leur liberté ?","function":"Chercher une liberté dans l’action commune","reason":"Montrer qu’une association peut permettre l’invention de rapports nouveaux plutôt que la seule soumission à des règles déjà fixées.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"La vie en société favorise-elle la liberté ?","function":"Distinguer cadre social et initiative","reason":"Examiner comment une initiative transforme une relation sociale, au lieu de faire de la société la cause suffisante ou l’ennemie nécessaire de la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-juger-et-reparer","code":"SI05","author":"Simondon","title":"Le jugement moral engage un geste","quote":"Le vrai jugement moral, comme le vrai jugement technique, est inadéquat s’il vise à être une pure expertise : il ne peut se dissocier du début du geste réparateur.","locator":"« L’ordre des objets techniques comme paradigme d’universalité axiologique dans la relation interhumaine » (vers 1956)","notions":["justice","devoir"],"commentary":[{"function":"Le problème","sentence":"Juger moralement consiste-t-il seulement à établir un diagnostic sur une personne ou sur son acte ?"},{"function":"L’affirmation","sentence":"Simondon affirme qu’un jugement moral adéquat doit amorcer une réparation."},{"function":"Les concepts","sentence":"La pure expertise désigne ici une évaluation qui constate et classe sans commencer à transformer la situation."},{"function":"La raison","sentence":"La comparaison avec la technique invite à chercher comment rendre possible un fonctionnement meilleur plutôt qu’à fixer une identité définitive."},{"function":"L’exemple","sentence":"Reconnaître une faute dans un groupe peut ainsi conduire à réparer le dommage et à modifier l’organisation qui l’a favorisée."},{"function":"La portée","sentence":"Cette exigence élargit le jugement à la responsabilité pratique, sans effacer la faute ni remplacer les procédures judiciaires."}],"uses":[{"subject":"Un homme peut-il en juger un autre ?","function":"Proposer une condition du jugement moral","reason":"Distinguer l’étiquette définitive portée sur une personne d’une appréciation qui engage une possibilité de réparation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=32","sourceLabel":"Recueil académique · p. 32"},{"subject":"Pourquoi demander justice ?","function":"Élargir la demande au-delà du constat","reason":"Introduire l’exigence de réparation du tort, en précisant que cette thèse sur le jugement moral ne définit pas à elle seule la justice judiciaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-matiere-et-forme","code":"SI06","author":"Simondon","title":"La matière contribue à la forme","quote":"La qualité de la matière est source de forme, élément de forme que l’opération technique fait changer d’échelle.","locator":"Première partie, chap. I « Forme et matière », I, 1, p. 39","notions":["travail","technique","nature"],"commentary":[{"function":"Le problème","sentence":"Travailler une matière consiste-t-il à lui imposer une forme qu’elle ne possède aucunement ?"},{"function":"L’affirmation","sentence":"Simondon soutient que les propriétés de la matière contribuent à la forme obtenue."},{"function":"Les concepts","sentence":"La qualité désigne ici des propriétés physiques, et l’opération technique le travail concret qui les met en œuvre."},{"function":"La raison","sentence":"Le moule ne suffit pas à produire une brique : l’argile doit pouvoir se déformer puis conserver le contour reçu."},{"function":"L’exemple","sentence":"L’artisan prépare donc la terre en la broyant, en la mouillant et en la pétrissant."},{"function":"La portée","sentence":"Le travail apparaît ainsi comme une mise en œuvre de possibilités naturelles, qui exige aussi de connaître leurs limites."}],"uses":[{"subject":"Le travail n’est-il qu’une lutte avec la nature ?","function":"Contester la seule logique de la lutte","reason":"Montrer que l’efficacité du travail vient aussi de propriétés naturelles dont l’artisan apprend à se servir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=47","sourceLabel":"Recueil académique · p. 47"},{"subject":"Travailler, est-ce seulement mettre en œuvre une technique ?","function":"Éclairer l’intelligence de la situation concrète","reason":"Distinguer l’application mécanique d’une recette de l’attention aux propriétés de la matière effectivement travaillée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=69","sourceLabel":"Recueil académique · p. 69"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"simondon-individu-et-relations","code":"SI07","author":"Simondon","title":"L’individu se forme dans la relation","quote":"L’individu est réalité d’une relation constituante, non intériorité d’un terme constitué.","locator":"Première partie, chap. I « Forme et matière », III, 1, p. 60","notions":["conscience","nature"],"commentary":[{"function":"Le problème","sentence":"Faut-il concevoir l’individu comme un être déjà achevé avant toute relation ?"},{"function":"L’affirmation","sentence":"Simondon propose de comprendre l’individu par la relation qui le constitue."},{"function":"Les concepts","sentence":"Une relation constituante fait naître une réalité, tandis qu’un terme constitué serait déjà donné avant elle."},{"function":"La raison","sentence":"Dans l’individuation physique étudiée ici, matière, énergie et milieu participent à une même opération de formation."},{"function":"L’exemple","sentence":"Le cristal se forme ainsi dans des conditions de milieu dont sa croissance ne peut être séparée."},{"function":"La portée","sentence":"Cette thèse invite à repenser aussi la formation du sujet dans ses relations, sans réduire sa vie psychique à un processus physique."}],"uses":[{"subject":"Peut-on se connaître soi-même sans l’aide d’autrui ?","function":"Questionner le modèle d’un moi déjà achevé","reason":"Ouvrir la recherche sur les relations qui nous forment ; leur importance pour la connaissance de soi demande ensuite un argument propre au sujet humain.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=82","sourceLabel":"Recueil académique · p. 82"},{"subject":"Suis-je ce que mon passé a fait de moi ?","function":"Introduire la formation plutôt qu’une essence fixe","reason":"Penser l’individu à partir de sa genèse, sans faire du résultat passé une identité définitivement close.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=67","sourceLabel":"Recueil académique · p. 67"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"simondon-animal-et-pensee","code":"SI08","author":"Simondon","title":"La pensée ne trace pas une frontière simple","quote":"Ceci ne signifie pas qu’il y ait des êtres seulement vivants et d’autres vivants et pensants : il est probable que les animaux se trouvent parfois en situation psychique.","locator":"Deuxième partie, chap. I, I, 2, p. 163, note 6","notions":["nature","raison","conscience"],"commentary":[{"function":"Le problème","sentence":"La pensée permet-elle de séparer absolument l’homme des autres vivants ?"},{"function":"L’affirmation","sentence":"Simondon envisage que les animaux puissent eux aussi rencontrer des situations psychiques."},{"function":"Les concepts","sentence":"Le psychisme désigne ici la recherche d’une résolution quand les régulations vitales ne suffisent plus."},{"function":"La raison","sentence":"La différence porte alors sur la fréquence et les possibilités de cette recherche plutôt que sur deux essences entièrement séparées."},{"function":"L’exemple","sentence":"Selon la note, les ressources du symbolisme permettent à l’homme de faire plus souvent appel au psychisme."},{"function":"La portée","sentence":"Présentée comme probable, cette hypothèse conteste une séparation absolue sans effacer les différences ni constituer une preuve expérimentale."}],"uses":[{"subject":"Y a-t-il une différence de nature entre l’homme et l’animal ?","function":"Mettre en question une frontière absolue","reason":"Opposer à la distinction de deux essences l’hypothèse de situations psychiques possibles chez les animaux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=48","sourceLabel":"Recueil académique · p. 48"},{"subject":"Prétendre distinguer l’homme de l’animal, est-ce légitime ?","function":"Préciser ce que la distinction peut signifier","reason":"Distinguer des possibilités et des fréquences d’activité sans réserver toute pensée à l’humanité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=48","sourceLabel":"Recueil académique · p. 48"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"simondon-ethique-et-vie-courante","code":"SI09","author":"Simondon","title":"La morale se construit dans la vie","quote":"Une véritable éthique serait celle qui tiendrait compte de la vie courante sans s’assoupir dans le courant de cette vie, qui saurait définir à travers les normes un sens qui les dépasse.","locator":"Conclusion, p. 244","notions":["devoir","raison"],"commentary":[{"function":"Le problème","sentence":"La morale doit-elle quitter la vie quotidienne ou se conformer à ses habitudes ?"},{"function":"L’affirmation","sentence":"Simondon cherche une éthique attentive à la vie courante et capable de dépasser ses règles établies."},{"function":"Les concepts","sentence":"Les normes sont ici les règles d’une situation donnée, tandis que leur sens permet de les interroger et de les transformer."},{"function":"La raison","sentence":"Une morale séparée de la vie perd sa prise sur l’action, mais l’obéissance aux usages ne justifie pas leur valeur."},{"function":"L’exemple","sentence":"Une règle de coopération peut être révisée lorsque son application empêche certains membres du groupe de participer."},{"function":"La portée","sentence":"L’exigence morale se cherche ainsi dans la transformation réfléchie des pratiques, plutôt que dans leur simple répétition."}],"uses":[{"subject":"Faire son devoir, est-ce là toute la morale ?","function":"Interroger les règles du devoir","reason":"Distinguer l’exécution d’une règle déjà reçue de la recherche du sens qui permet de l’évaluer et de la transformer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=24","sourceLabel":"Recueil académique · p. 24"},{"subject":"Les conventions sociales peuvent-elles tenir lieu de morale ?","function":"Dépasser la conformité aux usages","reason":"Montrer qu’une éthique doit prendre appui sur la vie commune tout en gardant la capacité d’en interroger les normes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=118","sourceLabel":"Recueil académique · p. 118"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"alain-obeir-et-resister","code":"AN01","author":"Alain","title":"Obéir et résister","work":"Propos","locator":"4 septembre 1912 · recueil des textes du bac, p. 689","quote":"Résistance et obéissance, voilà les deux vertus du citoyen.","notions":["etat","liberte","devoir"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=689","quoteSourceLabel":"Lire le texte du bac · p. 689","commentary":[{"function":"Le problème","sentence":"Comment préserver la liberté sans détruire l’ordre commun ?"},{"function":"L’affirmation","sentence":"Alain demande au citoyen d’associer l’obéissance aux lois et la résistance à l’arbitraire."},{"function":"Les concepts","sentence":"L’obéissance rend possible une vie réglée, tandis que la résistance désigne ici la vigilance et la critique du pouvoir."},{"function":"La raison","sentence":"Un ordre soustrait à toute contestation menace les libertés qu’il devrait protéger."},{"function":"L’exemple","sentence":"Un citoyen peut respecter une décision publique tout en la critiquant et en demandant sa révision."},{"function":"La portée","sentence":"La formule permet ainsi de penser une citoyenneté active, sans transformer toute désobéissance en vertu."}],"uses":[{"subject":"Obéir, est-ce nécessairement se soumettre ?","function":"Distinguer deux formes d’obéissance","reason":"Montrer qu’une obéissance accompagnée de vigilance et de contestation ne livre pas son jugement au pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"},{"subject":"L’État est-il menacé quand les citoyens discutent les lois ?","function":"Renverser une objection","reason":"Soutenir que la critique peut protéger les libertés et maintenir un ordre légitime plutôt que le détruire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Date du propos vérifiée dans l’édition de l’Association des Amis d’Alain."},{"id":"alain-la-distance-a-soi","code":"AN02","author":"Alain","title":"La distance à soi","work":"Vigiles de l’esprit","locator":"« L’inconscient », 17 juin 1923 · recueil des textes du bac, p. 1071","quote":"Pour prendre conscience, il faut se diviser soi-même.","notions":["conscience","liberte","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1071","quoteSourceLabel":"Lire le texte du bac · p. 1071","commentary":[{"function":"Le problème","sentence":"Peut-on prendre conscience de ses actes en se laissant entièrement absorber par eux ?"},{"function":"L’affirmation","sentence":"Alain affirme que la réflexion exige une distance à l’égard de soi."},{"function":"Les concepts","sentence":"Se diviser signifie devenir pour soi un objet d’examen, sans se transformer en deux personnes."},{"function":"La raison","sentence":"Celui qui s’interroge sur son impulsion cesse déjà de lui obéir sans réserve."},{"function":"L’exemple","sentence":"Au moment de répondre avec colère, se demander pourquoi l’on s’emporte ouvre une possibilité de retenue."},{"function":"La portée","sentence":"La conscience apparaît ainsi comme un exercice critique, et non comme une connaissance immédiate et complète de soi."}],"uses":[{"subject":"Prendre conscience de soi, est-ce devenir étranger à soi ?","function":"Préciser une condition de la réflexion","reason":"Distinguer la distance nécessaire à l’examen de soi et la perte de son identité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"},{"subject":"La conscience de soi rend-elle libre ?","function":"Établir une possibilité de libération","reason":"Expliquer comment l’examen d’une impulsion permet de suspendre une réaction, sans garantir une maîtrise totale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"}],"editionNote":"Titre et date vérifiés dans Vigiles de l’esprit (1942), section L ; le sujet ne précise pas ce recueil."},{"id":"bergson-inventer-prend-temps","code":"AN03","author":"Bergson","title":"Inventer prend du temps","work":"L’Évolution créatrice","locator":"Chapitre IV · recueil des textes du bac, p. 1019","quote":"Le temps d’invention ne fait qu’un ici avec l’invention même.","notions":["temps","art","travail"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1019","quoteSourceLabel":"Lire le texte du bac · p. 1019","commentary":[{"function":"Le problème","sentence":"Le temps consacré à créer est-il seulement un délai avant le résultat ?"},{"function":"L’affirmation","sentence":"Bergson soutient que l’invention se forme dans une durée qui appartient à son contenu."},{"function":"Les concepts","sentence":"Inventer diffère d’assembler un résultat déjà donné, car l’idée se transforme en se réalisant."},{"function":"La raison","sentence":"Réduire cette durée pourrait donc modifier l’œuvre elle-même et pas seulement avancer sa livraison."},{"function":"L’exemple","sentence":"Un peintre découvre dans son travail des rapports de couleurs qu’aucun plan initial ne fixait entièrement."},{"function":"La portée","sentence":"Le temps peut ainsi produire du nouveau, sans que toute lenteur soit pour autant créatrice."}],"uses":[{"subject":"Faut-il toujours chercher à gagner du temps ?","function":"Contester une règle générale","reason":"Montrer qu’accélérer une invention peut en modifier le contenu, au lieu de donner le même résultat plus vite.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"La création artistique est-elle un travail ?","function":"Caractériser le travail créateur","reason":"Distinguer la maturation d’une œuvre de l’exécution d’un modèle entièrement fixé à l’avance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"}]},{"id":"comte-les-limites-de-lintrospection","code":"AN04","author":"Comte","title":"Les limites de l’introspection","work":"Cours de philosophie positive","locator":"Première leçon · recueil des textes du bac, p. 529","quote":"L’individu pensant ne saurait se partager en deux dont l’un raisonnerait, tandis que l’autre regarderait raisonner.","notions":["conscience","science","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=529","quoteSourceLabel":"Lire le texte du bac · p. 529","commentary":[{"function":"Le problème","sentence":"Peut-on observer son raisonnement pendant qu’on le produit ?"},{"function":"L’affirmation","sentence":"Comte conteste la possibilité d’une observation intérieure simultanée des opérations intellectuelles."},{"function":"Les concepts","sentence":"L’introspection prétend faire du même esprit le sujet qui pense et l’observateur de cette pensée."},{"function":"La raison","sentence":"Or l’attention consacrée à observer risque de transformer ou d’interrompre l’activité étudiée."},{"function":"L’exemple","sentence":"Chercher à surveiller chaque étape d’un calcul peut faire perdre le fil du calcul lui-même."},{"function":"La portée","sentence":"Cette difficulté invite à examiner les méthodes de connaissance de soi, sans prouver que toute réflexion intérieure serait impossible."}],"uses":[{"subject":"Peut-on se connaître soi-même ?","function":"Soulever une difficulté de méthode","reason":"Interroger la possibilité de s’observer pendant que l’on pense ; distinguer cette difficulté de toute connaissance rétrospective.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"L’esprit peut-il être objet de science ?","function":"Mettre à l’épreuve une méthode","reason":"Montrer pourquoi l’observation intérieure immédiate demande un examen critique avant de servir de méthode scientifique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"}]},{"id":"diderot-le-bon-despote","code":"AN05","author":"Diderot","title":"Le bon despote","work":"Réfutation suivie de l’ouvrage d’Helvétius","locator":"Passage sur le gouvernement arbitraire · recueil des textes du bac, p. 266","quote":"Le gouvernement arbitraire d’un prince juste et éclairé est toujours mauvais.","notions":["etat","justice","liberte"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=266","quoteSourceLabel":"Lire le texte du bac · p. 266","commentary":[{"function":"Le problème","sentence":"Les qualités d’un gouvernant suffisent-elles à rendre son pouvoir légitime ?"},{"function":"L’affirmation","sentence":"Diderot condamne même le pouvoir arbitraire d’un prince bien intentionné."},{"function":"Les concepts","sentence":"L’arbitraire tient à l’absence de limites et de droit d’opposition, non à la seule cruauté du chef."},{"function":"La raison","sentence":"Une autorité bienfaisante habitue ses sujets à la dépendance et les expose aux décisions de ses successeurs."},{"function":"L’exemple","sentence":"Un prince généreux peut accorder un avantage que le suivant retirera sans recours possible."},{"function":"La portée","sentence":"La liberté exige donc des garanties durables, au-delà de la confiance accordée à une personne."}],"uses":[{"subject":"L’État doit-il reconnaître des limites à sa puissance ?","function":"Justifier une limite institutionnelle","reason":"Expliquer que la bienveillance du pouvoir ne remplace ni les droits des citoyens ni leur possibilité de s’opposer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"L’État doit-il garantir le bonheur des citoyens ?","function":"Écarter une justification insuffisante","reason":"Montrer qu’un bonheur dispensé par un pouvoir sans limites peut installer une dépendance politiquement dangereuse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"}],"editionNote":"Le titre est celui du recueil actuel, confirmé dans l’œuvre ; l’ancienne compilation attribuait à tort ce passage à une Lettre à Helvétius."},{"id":"durkheim-des-pouvoirs-qui-se-limitent","code":"AN06","author":"Durkheim","title":"Des pouvoirs qui se limitent","work":"Une révision de l’idée socialiste","locator":"Article de 1899 · recueil des textes du bac, p. 420","quote":"Ce qui libère l’individu, ce n’est pas la suppression de tout centre régulateur, c’est leur multiplication, pourvu que ces centres multiples soient coordonnés et subordonnés les uns aux autres.","notions":["etat","liberte","justice"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=420","quoteSourceLabel":"Lire le texte du bac · p. 420","commentary":[{"function":"Le problème","sentence":"La liberté demande-t-elle de supprimer toute autorité sociale ?"},{"function":"L’affirmation","sentence":"Durkheim soutient qu’elle peut dépendre de plusieurs pouvoirs capables de se limiter mutuellement."},{"function":"Les concepts","sentence":"Les centres régulateurs sont l’État et les groupes organisés, notamment territoriaux ou professionnels."},{"function":"La raison","sentence":"L’État protège contre l’oppression des groupes, tandis que leur autonomie freine les empiétements du pouvoir central."},{"function":"L’exemple","sentence":"Une organisation professionnelle peut défendre ses membres face à l’administration tout en restant soumise à des règles communes."},{"function":"La portée","sentence":"La pluralité protège donc à condition d’être organisée, et non par la simple accumulation d’autorités concurrentes."}],"uses":[{"subject":"L’État est-il l’ennemi de l’individu ?","function":"Dépasser une opposition trop simple","reason":"Examiner comment l’État et les groupes intermédiaires peuvent protéger l’individu en limitant réciproquement leur puissance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"La liberté consiste-t-elle à n’obéir à personne ?","function":"Proposer une autre condition de la liberté","reason":"Montrer que des autorités coordonnées peuvent empêcher la domination d’une autorité unique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"editionNote":"Le sujet donne le titre L’État et la société civile ; le passage est retrouvé dans l’article Une révision de l’idée socialiste (1899)."},{"id":"montesquieu-commerce-et-paix","code":"AN07","author":"Montesquieu","title":"Commerce et paix","work":"De l’Esprit des lois","locator":"Livre XX, chapitre II · recueil des textes du bac, p. 693","quote":"L’effet naturel du commerce est de porter à la paix.","notions":["etat","justice","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=693","quoteSourceLabel":"Lire le texte du bac · p. 693","commentary":[{"function":"Le problème","sentence":"Des intérêts économiques peuvent-ils rapprocher des peuples que tout oppose ?"},{"function":"L’affirmation","sentence":"Montesquieu montre que le commerce peut favoriser des relations pacifiques."},{"function":"Les concepts","sentence":"L’échange crée une dépendance réciproque entre celui qui souhaite acheter et celui qui souhaite vendre."},{"function":"La raison","sentence":"La guerre risque alors de détruire un avantage que chacun trouve dans la relation."},{"function":"L’exemple","sentence":"Deux pays qui dépendent de leurs débouchés respectifs ont un motif de préserver leurs échanges."},{"function":"La portée","sentence":"Il s’agit d’une raison de préférer la paix, sans garantie que l’intérêt économique suffise à empêcher toute guerre."}],"uses":[{"subject":"Le commerce favorise-t-il la paix ?","function":"Expliquer un mécanisme pacificateur","reason":"Relier les besoins réciproques à l’intérêt de maintenir les relations, puis examiner les limites de ce mécanisme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=97","sourceLabel":"Recueil académique · p. 97"},{"subject":"Les échanges nous rapprochent-ils toujours les uns des autres ?","function":"Distinguer rapprochement et vertu","reason":"Montrer qu’une dépendance utile peut unir des nations sans produire nécessairement la générosité entre les personnes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=97","sourceLabel":"Recueil académique · p. 97"}],"editionNote":"Le texte poursuit en distinguant l’union des nations et les rapports entre particuliers ; sa réserve est conservée dans l’explication."},{"id":"tocqueville-la-limite-de-la-majorite","code":"AN08","author":"Tocqueville","title":"La limite de la majorité","work":"De la démocratie en Amérique","locator":"Première Démocratie (1835), deuxième partie, chapitre VII · recueil des textes du bac, p. 627","quote":"La justice forme donc la borne du droit de chaque peuple.","notions":["etat","justice","liberte"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=627","quoteSourceLabel":"Lire le texte du bac · p. 627","commentary":[{"function":"Le problème","sentence":"Une décision devient-elle juste dès lors que la majorité l’approuve ?"},{"function":"L’affirmation","sentence":"Tocqueville oppose une limite de justice au pouvoir souverain d’un peuple."},{"function":"Les concepts","sentence":"La souveraineté désigne l’autorité de décider, tandis que la justice permet de juger la décision elle-même."},{"function":"La raison","sentence":"Une majorité peut poursuivre ses intérêts contre une minorité aussi bien qu’un individu abuse de sa force."},{"function":"L’exemple","sentence":"Un vote qui prive une minorité de droits ne devient pas juste par le seul nombre de ses partisans."},{"function":"La portée","sentence":"Le principe majoritaire doit donc s’accompagner de limites, sans que toute opposition particulière incarne automatiquement la justice."}],"uses":[{"subject":"La consultation des citoyens suffit-elle à faire la démocratie ?","function":"Montrer une condition supplémentaire","reason":"Expliquer pourquoi le vote ne suffit pas si la majorité peut supprimer les droits d’une minorité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=121","sourceLabel":"Recueil académique · p. 121"},{"subject":"Pour être juste, suffit-il d’obéir aux lois ?","function":"Distinguer légalité et justice","reason":"Montrer qu’une loi voulue par la majorité peut rester soumise à une exigence de justice qui en limite l’autorité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=33","sourceLabel":"Recueil académique · p. 33"}]},{"id":"rousseau-le-bonheur-despere","code":"AN09","author":"Rousseau","title":"Le bonheur d’espérer","work":"Julie ou La Nouvelle Héloïse","locator":"Sixième partie, lettre VIII · recueil des textes du bac, p. 607","quote":"On jouit moins de ce qu’on obtient que de ce qu’on espère et l’on n’est heureux qu’avant d’être heureux.","notions":["bonheur","conscience","temps"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=607","quoteSourceLabel":"Lire le texte du bac · p. 607","commentary":[{"function":"Le problème","sentence":"Le bonheur dépend-il davantage de la possession ou de l’attente ?"},{"function":"L’affirmation","sentence":"Rousseau fait exprimer à Julie le plaisir que l’espoir ajoute à l’objet désiré."},{"function":"Les concepts","sentence":"L’imagination embellit ce qui manque et permet d’en jouir avant de le posséder."},{"function":"La raison","sentence":"L’obtention confronte au contraire l’objet réel à la richesse de ce qu’on avait imaginé."},{"function":"L’exemple","sentence":"Un voyage longtemps rêvé peut perdre une partie de son charme une fois confronté à ses conditions concrètes."},{"function":"La portée","sentence":"La formule éclaire la déception du désir satisfait, sans établir que toute satisfaction réelle serait malheureuse."}],"uses":[{"subject":"Le bonheur n’est-il que dans l’attente du bonheur ?","function":"Soutenir une réponse paradoxale","reason":"Montrer comment l’espérance produit dès maintenant une jouissance que la possession peut dissiper.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Contester une condition suffisante","reason":"Distinguer l’objet obtenu et le plaisir que l’imagination lui ajoutait pendant l’attente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}],"speaker":"Julie de Wolmar","situation":"Dans une lettre à Saint-Preux, Julie examine le désir et la déception de la possession."},{"id":"pascal-etre-ou-paraitre-courageux","code":"AN10","author":"Pascal","title":"Être ou paraître courageux","work":"Pensées","locator":"Fragment 147, numérotation Brunschvicg · recueil des textes du bac, p. 1115","quote":"Nous serions de bon cœur poltrons pour en acquérir la réputation d’être vaillants.","notions":["conscience","devoir","liberte"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1115","quoteSourceLabel":"Lire le texte du bac · p. 1115","commentary":[{"function":"Le problème","sentence":"Préférons-nous posséder une vertu ou être reconnus pour elle ?"},{"function":"L’affirmation","sentence":"Pascal décrit le renversement par lequel la réputation devient plus précieuse que la qualité réelle."},{"function":"Les concepts","sentence":"L’être imaginaire est l’image de nous qui vit dans l’esprit des autres."},{"function":"La raison","sentence":"À vouloir embellir cette image, nous pouvons sacrifier la conduite qui justifierait réellement l’estime."},{"function":"L’exemple","sentence":"Un soldat pourrait éviter le danger tout en s’attribuant les exploits d’un autre pour passer pour courageux."},{"function":"La portée","sentence":"La recherche de reconnaissance demande donc un examen moral, sans que toute estime publique soit trompeuse."}],"uses":[{"subject":"Ne fait-on son devoir que par crainte du regard d’autrui ?","function":"Mettre en évidence un mobile ambigu","reason":"Montrer que le souci du jugement public peut pousser à rechercher les signes de la vertu plutôt qu’à agir vertueusement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"},{"subject":"Puis-je être moi-même sans le regard d’autrui ?","function":"Examiner un risque de dépendance","reason":"Expliquer comment l’image sociale peut prendre tant de valeur que l’on sacrifie sa conduite réelle pour la préserver.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"}]},{"id":"leibniz-condition-et-essence","code":"AN11","author":"Leibniz","title":"Condition et essence","work":"Sur ce qui passe les sens et la matière","locator":"Texte français, daté de juin 1702 par l’édition critique · recueil des textes du bac, p. 1050","quote":"Mais ce qui est nécessaire pour quelque chose, n’en fait point l’essence pour cela.","notions":["raison","science","verite"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1050","quoteSourceLabel":"Lire le texte du bac · p. 1050","commentary":[{"function":"Le problème","sentence":"Ce dont une chose dépend suffit-il à définir ce qu’elle est ?"},{"function":"L’affirmation","sentence":"Leibniz distingue une condition nécessaire et l’essence de ce qu’elle rend possible."},{"function":"Les concepts","sentence":"La condition doit être présente pour qu’une chose existe, tandis que l’essence dit ce qui la constitue."},{"function":"La raison","sentence":"Les sens peuvent ainsi être indispensables à notre pensée sans expliquer à eux seuls les vérités nécessaires du raisonnement."},{"function":"L’exemple","sentence":"L’air est nécessaire à notre vie, mais notre vie ne se confond pas avec l’air que nous respirons."},{"function":"La portée","sentence":"Cette distinction oblige à examiner ce qu’une explication établit vraiment, sans nier le rôle des conditions sensibles."}],"uses":[{"subject":"L’expérience est-elle la seule source du savoir ?","function":"Distinguer condition et fondement","reason":"Accorder que les sens sont nécessaires à notre pensée, puis demander s’ils suffisent à rendre compte des vérités nécessaires.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"La raison est-elle plus fiable que l’expérience ?","function":"Préciser les contributions respectives","reason":"Éviter de confondre le rôle des sensations dans l’acquisition des connaissances et la justification rationnelle de leur nécessité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"}],"editionNote":"Datation de l’édition critique de Münster : début à mi-juin 1702 ; la date de 1704 parfois donnée en ligne n’est pas retenue."},{"id":"weil-des-hommes-traites-en-choses","code":"AN12","author":"Simone Weil","title":"Des hommes traités en choses","work":"La Condition ouvrière","locator":"Passage sur les rapports dans l’usine · recueil des textes du bac, p. 105","quote":"Les choses jouent le rôle des hommes, les hommes jouent le rôle des choses ; c’est la racine du mal.","notions":["travail","technique","justice"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=105","quoteSourceLabel":"Lire le texte du bac · p. 105","commentary":[{"function":"Le problème","sentence":"Que devient le travailleur quand la production compte davantage que sa personne ?"},{"function":"L’affirmation","sentence":"Simone Weil décrit une organisation où l’ouvrier est traité comme un élément interchangeable."},{"function":"Les concepts","sentence":"L’inversion oppose les produits suivis et identifiés aux personnes réduites à une fonction et à un rythme imposés."},{"function":"La raison","sentence":"Lorsque la compréhension de l’ensemble est réservée aux dirigeants, l’exécutant perd la maîtrise du sens de son activité."},{"function":"L’exemple","sentence":"Un ouvrier déplacé d’une machine à l’autre sans explication peut être géré comme une pièce disponible."},{"function":"La portée","sentence":"La critique vise cette organisation du travail, et ne condamne pas toute activité industrielle à déshumaniser."}],"uses":[{"subject":"Le travail fait-il violence à notre humanité ?","function":"Identifier une forme de déshumanisation","reason":"Analyser le traitement des travailleurs comme éléments interchangeables, au lieu de réduire la violence à la seule pénibilité physique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"},{"subject":"La technique résout-elle tous les problèmes qui se posent au travail ?","function":"Déplacer le problème vers l’organisation","reason":"Montrer qu’une production techniquement efficace peut laisser intacte la dépossession des exécutants.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=69","sourceLabel":"Recueil académique · p. 69"}],"editionNote":"Le sujet porte la date 1942 ; La Condition ouvrière est un recueil posthume publié en 1951."},{"id":"weil-leffort-et-la-maitrise-de-soi","code":"AN13","author":"Simone Weil","title":"L’effort et la maîtrise de soi","work":"Réflexions sur les causes de la liberté et de l’oppression sociale","locator":"Texte rédigé en 1934 · recueil des textes du bac, p. 86","quote":"Ce sont les obstacles auxquels on se heurte et qu’il faut surmonter qui fournissent l’occasion de se vaincre soi-même.","notions":["travail","liberte","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=86","quoteSourceLabel":"Lire le texte du bac · p. 86","commentary":[{"function":"Le problème","sentence":"L’absence d’obstacles suffirait-elle à nous rendre maîtres de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Simone Weil voit dans l’effort demandé par le réel une occasion de discipliner ses propres impulsions."},{"function":"Les concepts","sentence":"Se vaincre signifie ici apprendre à régler sa conduite plutôt que suivre chaque caprice."},{"function":"La raison","sentence":"Une difficulté extérieure impose une exigence que notre fantaisie ne peut pas supprimer à volonté."},{"function":"L’exemple","sentence":"Un apprenti ajuste patiemment son geste à la résistance du matériau au lieu d’abandonner à la première contrariété."},{"function":"La portée","sentence":"Le travail peut ainsi former la liberté, sans que toute souffrance ou toute oppression devienne pour autant éducative."}],"uses":[{"subject":"Le travail peut-il rendre libre ?","function":"Expliquer une formation de la liberté","reason":"Montrer comment l’effort réglé par les exigences d’une tâche peut libérer de la soumission au caprice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=69","sourceLabel":"Recueil académique · p. 69"},{"subject":"Tout travail est-il un travail sur soi ?","function":"Établir une possibilité à examiner","reason":"Décrire ce que l’effort peut transformer dans le sujet, puis demander quelles conditions de travail permettent cette formation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"}]},{"id":"mill-choisir-au-lieu-de-suivre","code":"AN14","author":"Mill","title":"Choisir au lieu de suivre","work":"De la liberté","locator":"Chapitre III · recueil des textes du bac, p. 264","quote":"Celui qui n’agit jamais que suivant la coutume ne fait pas de choix.","notions":["liberte","raison","devoir"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":"Non indiqué dans le recueil","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=264","quoteSourceLabel":"Lire le texte du bac · p. 264","commentary":[{"function":"Le problème","sentence":"Une conduite correcte suffit-elle à prouver que l’on agit librement ?"},{"function":"L’affirmation","sentence":"Mill distingue suivre une coutume et choisir soi-même sa conduite."},{"function":"Les concepts","sentence":"La coutume transmet une expérience collective, tandis que le choix exerce le jugement personnel."},{"function":"La raison","sentence":"Même une règle adaptée ne développe pas ce jugement lorsqu’on la suit uniquement parce que tous la suivent."},{"function":"L’exemple","sentence":"Reprendre le métier familial sans en examiner les raisons ne constitue pas le même acte que le choisir après réflexion."},{"function":"La portée","sentence":"La liberté demande donc un exercice du discernement, sans imposer de rejeter toutes les traditions."}],"uses":[{"subject":"Peut-on choisir sa vie ?","function":"Préciser ce que signifie choisir","reason":"Distinguer adopter une manière de vivre après examen et reproduire un modèle uniquement parce qu’il est reçu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=44","sourceLabel":"Recueil académique · p. 44"},{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Interroger l’origine de la volonté","reason":"Demander si ce que l’on veut résulte d’un jugement personnel ou de la seule imitation des usages.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"editionNote":"Phrase également attestée dans la traduction de Charles Brook Dupont-White (1860) ; le recueil ne précise pas la traduction de son extrait."},{"id":"arendt-un-espace-pour-la-liberte","code":"AN15","author":"Arendt","title":"Un espace pour la liberté","work":"La Crise de la culture","locator":"« Qu’est-ce que la liberté ? » · recueil des textes du bac, p. 124","quote":"Sans une vie publique politiquement garantie, il manque à la liberté l’espace du monde où faire son apparition.","notions":["liberte","etat","langage"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":"Non indiqué dans le recueil","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=124","quoteSourceLabel":"Lire le texte du bac · p. 124","commentary":[{"function":"Le problème","sentence":"La liberté peut-elle devenir effective si chacun reste enfermé dans sa vie privée ?"},{"function":"L’affirmation","sentence":"Arendt affirme que la liberté politique a besoin d’un espace public garanti."},{"function":"Les concepts","sentence":"Cet espace permet à des personnes différentes de parler et d’agir ensemble devant d’autres."},{"function":"La raison","sentence":"Une aspiration intérieure ne suffit pas à produire une action libre lorsque toute initiative publique est interdite."},{"function":"L’exemple","sentence":"Pouvoir discuter d’une décision commune et proposer une action rend la liberté visible dans le monde partagé."},{"function":"La portée","sentence":"La formule distingue donc la liberté politique de son seul désir intérieur, sans nier l’existence de ce désir sous la contrainte."}],"uses":[{"subject":"Y a-t-il d’autres formes de liberté que la liberté politique ?","function":"Définir une forme particulière de liberté","reason":"Distinguer l’aspiration intime et la liberté qui se manifeste par l’action et la parole dans un monde commun.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"L’État est-il le garant de ma liberté ?","function":"Énoncer une condition politique","reason":"Examiner les garanties qui rendent possibles l’expression et l’initiative publiques, au-delà de la simple absence d’entraves privées.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Formulation française exacte du sujet : « l’espace du monde » ; l’ancienne compilation porte une autre variante, « l’espace mondain »."},{"id":"la-fontaine-accuser-le-miroir","code":"LF01","author":"La Fontaine","title":"Accuser le miroir","work":"L’Homme et son Image","collection":"Fables choisies mises en vers","locator":"Livre I, fable XI · p. 44 (PDF p. 110)","quote":"Il accusait toujours les miroirs d’être faux,\nVivant plus que content dans son erreur profonde.","verse":true,"notions":["conscience","verite","bonheur"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Un homme épris de lui-même refuse les reflets qui contredisent la haute opinion qu’il a de sa beauté.","commentary":[{"function":"Le problème","sentence":"Pourquoi la connaissance de soi rencontre-t-elle parfois une résistance en nous-mêmes ?"},{"function":"L’affirmation","sentence":"La Fontaine peint un homme qui préfère condamner les miroirs plutôt que corriger son jugement."},{"function":"Les concepts","sentence":"Le miroir représente ici un témoignage extérieur, tandis que l’erreur entretient une satisfaction intérieure."},{"function":"La raison","sentence":"Ce qui déplaît au personnage lui paraît faux parce qu’il confond son désir d’être beau avec une preuve."},{"function":"L’exemple","sentence":"De même, un reproche justifié peut être rejeté comme malveillant lorsqu’il blesse notre amour-propre."},{"function":"La portée","sentence":"Le récit fait donc voir un obstacle affectif à la connaissance de soi, sans établir que toute critique serait vraie."}],"uses":[{"subject":"Peut-on se voir tel que l’on est ?","function":"Montrer une résistance à la connaissance de soi","reason":"L’homme dispose de reflets, mais refuse leur témoignage : l’obstacle tient à l’accueil du jugement autant qu’au manque d’informations.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Mettre à l’épreuve un bonheur fondé sur l’illusion","reason":"La satisfaction du personnage dépend d’une erreur entretenue ; examiner sa fragilité plutôt que supposer que toute vérité rend heureux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"}]},{"id":"la-fontaine-appeler-la-mort-retenir-la-vie","code":"LF02","author":"La Fontaine","title":"Appeler la mort, retenir la vie","work":"La Mort et le Bûcheron","collection":"Fables choisies mises en vers","locator":"Livre I, fable XVI · p. 50 (PDF p. 118)","quote":"C’est, dit-il, afin de m’aider\nA recharger ce bois; tu ne tarderas guère.","verse":true,"notions":["conscience","bonheur","liberte"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Bûcheron","situation":"Épuisé, le bûcheron appelle la Mort ; lorsqu’elle paraît, il lui demande seulement de l’aider à porter son bois.","commentary":[{"function":"Le problème","sentence":"Savons-nous toujours ce que nous désirons lorsque nous exprimons notre détresse ?"},{"function":"L’affirmation","sentence":"Le bûcheron qui appelait la Mort lui demande finalement de l’aider à poursuivre sa vie."},{"function":"Les concepts","sentence":"Vouloir la fin d’une souffrance se distingue alors de vouloir la fin de son existence."},{"function":"La raison","sentence":"La présence de la Mort révèle un attachement à la vie que la plainte semblait avoir effacé."},{"function":"L’exemple","sentence":"Dans cette scène, le bois rechargé représente le retour à une condition pénible que le personnage préfère néanmoins conserver."},{"function":"La portée","sentence":"La réplique invite ainsi à interroger le sens d’un désir déclaré, sans transformer ce cas fictif en vérité universelle sur la souffrance."}],"uses":[{"subject":"Les hommes savent-ils ce qu’ils désirent ?","function":"Distinguer la plainte et son objet véritable","reason":"L’appel de la Mort devient une demande d’aide : analyser l’écart entre les mots prononcés et le désir qui se révèle dans l’épreuve.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"La souffrance est-elle au cœur de l’existence ?","function":"Nuancer l’identification de vivre et souffrir","reason":"La scène associe le poids de l’existence à un attachement persistant à la vie ; elle ouvre la discussion sans justifier toute souffrance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}]},{"id":"la-fontaine-qui-peint-la-victoire","code":"LF03","author":"La Fontaine","title":"Qui peint la victoire ?","work":"Le Lion abattu par l’Homme","collection":"Fables choisies mises en vers","locator":"Livre III, fable X · p. 94 (PDF p. 174)","quote":"Avec plus de raison nous aurions le dessus,\nSi mes confrères savaient peindre.","verse":true,"notions":["art","verite","justice"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Lion","situation":"Devant un tableau glorifiant un homme victorieux d’un lion, un lion conteste le privilège humain de produire les images.","commentary":[{"function":"Le problème","sentence":"Une image montre-t-elle les faits indépendamment de celui qui la produit ?"},{"function":"L’affirmation","sentence":"Le lion suggère que la victoire humaine représentée dépend aussi du pouvoir humain de peindre."},{"function":"Les concepts","sentence":"La représentation sélectionne un point de vue et ne se confond donc pas avec une preuve impartiale."},{"function":"La raison","sentence":"Celui qui possède les moyens de représenter peut rendre sa propre supériorité visible et laisser celle des autres sans image."},{"function":"L’exemple","sentence":"Le tableau admiré par les hommes devient ainsi, pour le lion, le témoignage de leur avantage dans la fabrication des récits."},{"function":"La portée","sentence":"La réplique invite à examiner la position du représentant, sans garantir qu’une peinture de lion serait plus objective."}],"uses":[{"subject":"Que peut nous apprendre une image ?","function":"Distinguer ce qui est représenté et le point de vue du représentant","reason":"Le tableau renseigne sur la gloire que les hommes se donnent autant que sur le combat qu’il prétend montrer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"},{"subject":"Peut-on reprocher à l’art d’être mensonger ?","function":"Interroger une représentation qui se donne pour une preuve","reason":"L’image peut fabriquer une évidence favorable à son auteur ; distinguer cette prétention de la liberté reconnue à la fiction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=10","sourceLabel":"Recueil académique · p. 10"}]},{"id":"la-fontaine-enfermer-sa-joie-avec-son-argent","code":"LF04","author":"La Fontaine","title":"Enfermer sa joie avec son argent","work":"Le Savetier et le Financier","collection":"Fables choisies mises en vers","locator":"Livre VIII, fable II · p. 208 (PDF p. 304)","quote":"Il retourne chez lui : dans sa cave il enserre\nL’argent et sa joie à la fois.","verse":true,"notions":["bonheur","liberte"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Après avoir reçu cent écus du financier, le savetier cache l’argent et perd la tranquillité qui le faisait chanter.","commentary":[{"function":"Le problème","sentence":"Posséder davantage suffit-il à mieux vivre ?"},{"function":"L’affirmation","sentence":"La Fontaine représente un savetier dont l’argent nouvellement reçu enferme aussi la joie."},{"function":"Les concepts","sentence":"La possession matérielle se distingue ici de la disponibilité intérieure nécessaire au bonheur."},{"function":"La raison","sentence":"En craignant constamment de perdre son trésor, le personnage transforme un avantage en source de dépendance."},{"function":"L’exemple","sentence":"L’argent caché dans la cave mobilise désormais son attention et fait taire les chansons qui accompagnaient son travail."},{"function":"La portée","sentence":"L’image permet donc de discuter la valeur des biens par leurs effets sur la vie, sans présenter la pauvreté comme un idéal."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Opposer la possession d’un bien et la capacité d’en jouir","reason":"Le don enrichit le savetier mais suscite la peur de perdre ; la satisfaction matérielle ne garantit pas la tranquillité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"},{"subject":"La liberté s’oppose-t-elle à la sécurité ?","function":"Montrer une recherche de sécurité qui devient une dépendance","reason":"En protégeant sans cesse son trésor, le savetier perd sa liberté d’attention ; distinguer une sécurité utile d’une inquiétude entretenue par elle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}]},{"id":"la-fontaine-le-plaisir-de-comprendre","code":"LF05","author":"La Fontaine","title":"Le plaisir de comprendre","work":"Le Pâtre et le Lion","collection":"Fables choisies mises en vers","locator":"Livre VI, fable I · p. 153 (PDF p. 243)","quote":"Une Morale nue apporte de l’ennui;\nLe conte fait passer le précepte avec lui.","verse":true,"notions":["art","langage","raison"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Avant de raconter la rencontre d’un pâtre et d’un lion, le poète explique comment la fable associe plaisir et instruction.","commentary":[{"function":"Le problème","sentence":"Le plaisir d’une œuvre empêche-t-il de réfléchir ?"},{"function":"L’affirmation","sentence":"La Fontaine soutient que le récit peut rendre une leçon plus accessible qu’un précepte isolé."},{"function":"Les concepts","sentence":"Le conte donne une situation sensible à une règle morale qui resterait autrement abstraite."},{"function":"La raison","sentence":"L’intérêt pris aux personnages conduit le lecteur à suivre les conséquences de leurs actions et à examiner leurs choix."},{"function":"L’exemple","sentence":"L’ours qui tue son ami en voulant le protéger fait comprendre les dangers d’une intention privée de jugement."},{"function":"La portée","sentence":"La formule montre ainsi une coopération possible entre plaisir et réflexion, sans réduire toute œuvre d’art à une leçon."}],"uses":[{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Associer le plaisir du récit à un travail de réflexion","reason":"La fable plaît en faisant suivre une action dont les conséquences instruisent ; le plaisir peut participer à une autre fin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art doit-il nous instruire ?","function":"Décrire une manière d’instruire propre au récit","reason":"Le précepte devient intelligible dans une situation imaginée ; cette possibilité ne suffit pas à imposer une mission morale à tout art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"la-fontaine-changer-de-maitre-rester-soumis","code":"LF06","author":"La Fontaine","title":"Changer de maître, rester soumis","work":"Le Vieillard et l’Âne","collection":"Fables choisies mises en vers","locator":"Livre VI, fable VIII · p. 160 (PDF p. 250)","quote":"Notre ennemi, c’est notre Maître :\nJe vous le dis en bon François.","verse":true,"notions":["liberte","etat","justice"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"L’Âne","situation":"L’âne refuse de fuir l’ennemi : il pense que changer de propriétaire ne modifiera pas la charge qu’il doit porter.","commentary":[{"function":"Le problème","sentence":"Un changement de pouvoir suffit-il à supprimer la domination ?"},{"function":"L’affirmation","sentence":"L’âne considère son maître actuel comme son ennemi parce qu’il demeure celui qui lui impose sa charge."},{"function":"Les concepts","sentence":"La liberté se distingue ici du simple remplacement de la personne qui commande."},{"function":"La raison","sentence":"Du point de vue du dominé, la victoire d’un camp importe peu si elle laisse intacte la relation de servitude."},{"function":"L’exemple","sentence":"Dans la fable, l’animal compare les charges attendues plutôt que les fidélités que le vieillard voudrait lui faire partager."},{"function":"La portée","sentence":"Sa réplique oblige donc à examiner les conditions concrètes de l’obéissance, sans prouver que tous les pouvoirs se valent."}],"uses":[{"subject":"L’État exerce-t-il nécessairement une domination ?","function":"Introduire le point de vue de celui qui subit le pouvoir","reason":"La réplique distingue l’identité des dirigeants et les effets de leur autorité ; elle sert de comparaison, sans assimiler d’emblée l’État au propriétaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"La liberté consiste-t-elle à n’obéir à personne ?","function":"Distinguer changement de maître et libération","reason":"Le refus de l’âne révèle qu’une nouvelle autorité peut reconduire la même dépendance ; examiner ensuite les formes d’obéissance compatibles avec la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}]},{"id":"la-fontaine-la-puissance-devant-le-juge","code":"LF07","author":"La Fontaine","title":"La puissance devant le juge","work":"Les Animaux malades de la peste","collection":"Fables choisies mises en vers","locator":"Livre VII, fable I · p. 180 (PDF p. 270)","quote":"Selon que vous serez puissant ou misérable,\nLes jugements de cour vous rendront blanc ou noir.","verse":true,"notions":["justice","etat","verite"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Le lion est absous de ses violences ; l’âne, coupable d’avoir brouté un peu d’herbe, est désigné comme victime expiatoire.","commentary":[{"function":"Le problème","sentence":"Une décision prononcée par un tribunal est-elle nécessairement juste ?"},{"function":"L’affirmation","sentence":"La Fontaine dénonce des jugements qui changent selon la puissance de l’accusé."},{"function":"Les concepts","sentence":"Le verdict officiel se sépare alors de l’examen impartial des actes commis."},{"function":"La raison","sentence":"La peur des puissants fait excuser leurs crimes, tandis que la faiblesse de l’âne rend sa faute disproportionnellement punissable."},{"function":"L’exemple","sentence":"Le même conseil absout ainsi le lion et condamne celui qui ne peut se défendre contre lui."},{"function":"La portée","sentence":"Ces vers permettent de penser les conditions d’une justice indépendante, plutôt que de conclure que tout jugement est nécessairement corrompu."}],"uses":[{"subject":"La justice met-elle fin à la loi du plus fort ?","function":"Montrer une institution judiciaire capturée par la puissance","reason":"Le jugement prolonge le rapport de force au lieu de le corriger ; définir les garanties qui permettraient d’en sortir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"La loi est-elle une garantie contre l’injustice ?","function":"Établir que l’impartialité de l’application est décisive","reason":"La présence d’une procédure ne suffit pas si le rang de l’accusé détermine le verdict ; distinguer légalité formelle et protection effective.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=33","sourceLabel":"Recueil académique · p. 33"}]},{"id":"la-fontaine-redresser-le-baton-par-le-jugement","code":"LF08","author":"La Fontaine","title":"Redresser le bâton par le jugement","work":"Un Animal dans la Lune","collection":"Fables choisies mises en vers","locator":"Livre VII, fable XVII · p. 201 (PDF p. 297)","quote":"Quand l’eau courbe un bâton ma raison le redresse,\nLa raison décide en maîtresse.","verse":true,"notions":["raison","science","verite"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Le poète examine les apparences trompeuses avant de raconter comment une souris dans une lunette fut prise pour un animal lunaire.","commentary":[{"function":"Le problème","sentence":"Faut-il rejeter les sens parce que certaines apparences nous trompent ?"},{"function":"L’affirmation","sentence":"La Fontaine attribue à la raison le pouvoir de corriger le jugement immédiatement suggéré par la vue."},{"function":"Les concepts","sentence":"Le bâton paraît courbé dans l’eau sans que sa forme réelle ait changé."},{"function":"La raison","sentence":"Comprendre les conditions de l’observation permet de distinguer ce que l’on voit de ce que l’on doit en conclure."},{"function":"L’exemple","sentence":"Dans la suite du récit, l’examen de la lunette explique l’animal aperçu dans la Lune par une souris logée entre les verres."},{"function":"La portée","sentence":"La citation défend donc une perception examinée par la raison, sans établir que celle-ci connaîtrait tout indépendamment de l’expérience."}],"uses":[{"subject":"La raison est-elle plus fiable que l’expérience ?","function":"Distinguer l’observation et son interprétation","reason":"Le bâton apparent ne doit pas être pris pour une description immédiate du réel ; la raison explique l’apparence en tenant compte du milieu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Faut-il chercher la vérité au-delà des apparences ?","function":"Préciser le sens du dépassement des apparences","reason":"Dépasser la première impression consiste ici à en comprendre la cause, et non à abandonner l’observation du monde sensible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"la-fontaine-vouloir-aider-ne-suffit-pas","code":"LF09","author":"La Fontaine","title":"Vouloir aider ne suffit pas","work":"L’Ours et l’Amateur des Jardins","collection":"Fables choisies mises en vers","locator":"Livre VIII, fable X · p. 218 (PDF p. 314)","quote":"Rien n’est si dangereux qu’un ignorant ami;\nMieux vaudrait un sage ennemi.","verse":true,"notions":["devoir","raison","justice"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Pour chasser une mouche du visage de son ami endormi, l’ours lance un pavé et tue celui qu’il voulait protéger.","commentary":[{"function":"Le problème","sentence":"La bonne intention garantit-elle la valeur d’une action ?"},{"function":"L’affirmation","sentence":"La Fontaine montre qu’un ami peut devenir dangereux lorsqu’il agit sans jugement."},{"function":"Les concepts","sentence":"La bienveillance désigne la fin recherchée, tandis que la prudence examine les moyens et leurs conséquences."},{"function":"La raison","sentence":"L’ours vise un bien mais choisit un moyen qui détruit la personne à laquelle il voulait le procurer."},{"function":"L’exemple","sentence":"Le pavé lancé contre la mouche rend visible cette disproportion entre l’aide désirée et le dommage produit."},{"function":"La portée","sentence":"La formule appelle donc à joindre le discernement à l’affection, sans recommander de préférer systématiquement les ennemis aux amis."}],"uses":[{"subject":"Suffit-il que son intention soit bonne pour qu’une action soit morale ?","function":"Construire un contre-exemple à la suffisance de l’intention","reason":"L’ours veut protéger son ami mais le tue ; interroger la responsabilité dans le choix des moyens et la prévision des conséquences.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=115","sourceLabel":"Recueil académique · p. 115"},{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Distinguer aider autrui et lui imposer son idée du bien","reason":"Le désir de rendre service devient destructeur faute de discernement ; montrer qu’une aide doit tenir compte de celui qui la reçoit.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"}]},{"id":"la-fontaine-un-monde-dans-la-presence-aimee","code":"LF10","author":"La Fontaine","title":"Un monde dans la présence aimée","work":"Les Deux Pigeons","collection":"Fables choisies mises en vers","locator":"Livre IX, fable II · p. 247 (PDF p. 343)","quote":"Soyez-vous l’un à l’autre un monde toujours beau,\nToujours divers, toujours nouveau;","verse":true,"notions":["bonheur","temps"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Après le retour du pigeon voyageur auprès de son compagnon, le narrateur s’adresse aux amants et évoque sa propre jeunesse.","commentary":[{"function":"Le problème","sentence":"Le bonheur exige-t-il de chercher sans cesse de nouveaux objets ?"},{"function":"L’affirmation","sentence":"La Fontaine invite les amants à trouver une diversité renouvelée dans leur présence réciproque."},{"function":"Les concepts","sentence":"La nouveauté désigne ici une qualité de l’attention autant qu’un changement de lieu ou de personne."},{"function":"La raison","sentence":"Ce qui semblait familier peut encore surprendre lorsque l’autre n’est pas réduit à ce que l’on croit déjà savoir de lui."},{"function":"L’exemple","sentence":"Au retour du voyageur, la proximité retrouvée prend ainsi un prix que l’éloignement avait fait oublier."},{"function":"La portée","sentence":"L’image ouvre une réflexion sur la fidélité vivante, tout en laissant discuter l’idéal d’un couple qui voudrait tenir lieu de tout."}],"uses":[{"subject":"Comment être heureux, si rien ne dure ?","function":"Penser une durée qui accueille le renouvellement","reason":"La relation peut durer en restant diverse ; distinguer la fidélité d’une immobilité qui prétendrait arrêter le changement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Suffit-il d’être proche d’autrui pour le connaître ?","function":"Distinguer la familiarité et une attention renouvelée","reason":"L’autre demeure un monde à découvrir ; la proximité ne vaut connaissance que si elle laisse place à sa diversité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"}]},{"id":"la-fontaine-du-marbre-au-dieu","code":"LF11","author":"La Fontaine","title":"Du marbre au dieu","work":"Le Statuaire et la Statue de Jupiter","collection":"Fables choisies mises en vers","locator":"Livre IX, fable VI · p. 251 (PDF p. 349)","quote":"Qu’en fera, dit-il, mon ciseau ?\nSera-t-il Dieu, table ou cuvette ?","verse":true,"notions":["art","religion","technique"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Statuaire","situation":"Un sculpteur hésite sur la destination d’un bloc de marbre ; après avoir sculpté Jupiter, il redoute sa propre création.","commentary":[{"function":"Le problème","sentence":"Comment une matière travaillée peut-elle recevoir une puissance qui semble dépasser son fabricant ?"},{"function":"L’affirmation","sentence":"Le statuaire envisage plusieurs destinations pour le même marbre, dont celle d’une figure divine."},{"function":"Les concepts","sentence":"La matière ne détermine donc pas à elle seule la signification ni l’usage de l’objet."},{"function":"La raison","sentence":"Le choix d’une forme, puis le regard porté sur elle, peuvent faire d’une fabrication humaine une présence redoutée."},{"function":"L’exemple","sentence":"Dans le récit, le sculpteur finit par trembler devant le Jupiter qu’il vient lui-même de façonner."},{"function":"La portée","sentence":"La scène permet d’interroger les pouvoirs de l’image et la croyance en une idole, sans démontrer que toute religion serait une illusion."}],"uses":[{"subject":"Qu’est-ce qui fait d’un objet une œuvre d’art ?","function":"Distinguer la matière et la signification de la forme","reason":"Le même bloc peut devenir objet usuel ou figure de Jupiter ; examiner le travail de la forme et la manière de recevoir l’objet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"},{"subject":"L’artiste est-il maître de son œuvre ?","function":"Montrer une création qui agit en retour sur son créateur","reason":"Le sculpteur choisit la figure, puis subit l’effroi qu’elle suscite ; distinguer la maîtrise de la fabrication et celle des effets de l’œuvre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}]},{"id":"la-fontaine-les-limites-de-la-ressemblance","code":"LF12","author":"La Fontaine","title":"Les limites de la ressemblance","work":"Le Cierge","collection":"Fables choisies mises en vers","locator":"Livre IX, fable XII · p. 258 (PDF p. 356)","quote":"Tout en tout est divers : ôtez-vous de l’esprit\nQu’aucun être ait été composé sur le vôtre.","verse":true,"notions":["raison","science","nature"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Un cierge se jette dans le feu pour devenir aussi solide qu’une brique ; il fond au lieu de durcir.","commentary":[{"function":"Le problème","sentence":"Peut-on attribuer à un être les propriétés d’un autre parce qu’ils semblent comparables ?"},{"function":"L’affirmation","sentence":"La Fontaine avertit contre les raisonnements qui oublient la différence de constitution des choses."},{"function":"Les concepts","sentence":"Le mot « aucun » signifie ici quelque être que ce soit, et la composition désigne ce dont chacun est fait."},{"function":"La raison","sentence":"Un traitement favorable à une matière peut en détruire une autre si leur nature diffère."},{"function":"L’exemple","sentence":"Le cierge imite ainsi la brique durcie par le feu, mais sa cire fond dans les mêmes flammes."},{"function":"La portée","sentence":"Le récit demande donc de vérifier la pertinence d’une analogie, sans interdire toute comparaison ni toute connaissance générale."}],"uses":[{"subject":"Suffit-il de bien raisonner pour être raisonnable ?","function":"Montrer la nécessité d’examiner les prémisses","reason":"L’imitation paraît cohérente mais repose sur une fausse équivalence entre cire et argile ; la validité d’une déduction ne garantit pas ses points de départ.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"},{"subject":"Dans quels domaines est-il légitime de prendre la nature comme modèle ?","function":"Fixer une condition de pertinence du modèle","reason":"Une propriété observée ne se transpose pas sans examen ; comparer la constitution des êtres avant de reproduire un procédé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"la-fontaine-une-tache-commune-aux-castors","code":"LF13","author":"La Fontaine","title":"Une tâche commune aux castors","work":"Discours à Madame de La Sablière","collection":"Fables choisies mises en vers","locator":"Fin du livre IX · p. 268 (PDF p. 366)","quote":"Chaque Castor agit; commune en est la tâche;\nLe vieux y fait marcher le jeune sans relâche.","verse":true,"notions":["nature","technique","travail"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Pour discuter la réduction des animaux à des machines, le poète représente des castors organisant ensemble la construction de leurs ouvrages.","commentary":[{"function":"Le problème","sentence":"L’activité organisée et la construction d’ouvrages appartiennent-elles exclusivement aux humains ?"},{"function":"L’affirmation","sentence":"La Fontaine décrit des castors dont les actions particulières participent à une tâche commune."},{"function":"Les concepts","sentence":"Le travail collectif suppose ici une articulation des activités qui dépasse la simple juxtaposition de mouvements."},{"function":"La raison","sentence":"L’ouvrage achevé invite à se demander comment des conduites différentes peuvent concourir à un résultat partagé."},{"function":"L’exemple","sentence":"Le poète représente l’ancien faisant travailler le jeune pour donner à voir cette organisation."},{"function":"La portée","sentence":"Cette image conteste une frontière trop simple entre humains et animaux, mais elle ne constitue pas une preuve zoologique des rôles qu’elle leur prête."}],"uses":[{"subject":"La technique est-elle le propre de l’homme ?","function":"Mettre à l’épreuve une définition exclusivement humaine","reason":"L’image des bâtisseurs animaux oblige à préciser si la technique se définit par l’ouvrage produit, l’organisation ou la conscience du projet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"},{"subject":"L’homme est-il une exception dans la nature ?","function":"Discuter le monopole humain de l’activité organisée","reason":"Le poème attribue une tâche commune aux castors ; s’en servir pour poser une question conceptuelle, sans transformer l’anthropomorphisme en observation scientifique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"la-fontaine-lutilite-deguisee-en-justice","code":"LF14","author":"La Fontaine","title":"L’utilité déguisée en justice","work":"L’Homme et la Couleuvre","collection":"Fables choisies mises en vers","locator":"Livre X, fable I · p. 275 (PDF p. 375)","quote":"Mes jours sont en tes mains, tranche-les : ta justice,\nC’est ton utilité, ton plaisir, ton caprice;","verse":true,"notions":["justice","nature","devoir"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"La Couleuvre","situation":"Capturée par un homme qui invoque son droit de la tuer, la couleuvre conteste la justice de celui qui dispose d’elle.","commentary":[{"function":"Le problème","sentence":"Celui qui peut imposer une décision possède-t-il pour autant une raison juste de le faire ?"},{"function":"L’affirmation","sentence":"La couleuvre accuse l’homme de donner le nom de justice à son intérêt personnel."},{"function":"Les concepts","sentence":"La puissance de disposer d’un être se distingue d’un droit fondé sur une règle impartiale."},{"function":"La raison","sentence":"Un jugement devient arbitraire si celui qui le prononce le mesure seulement à son utilité ou à son plaisir."},{"function":"L’exemple","sentence":"Dans la fable, l’homme sollicite des témoignages mais finit par tuer malgré les accusations portées contre lui."},{"function":"La portée","sentence":"La réplique invite donc à examiner la légitimité de notre pouvoir sur les vivants, sans supposer que la nature parle réellement comme un tribunal."}],"uses":[{"subject":"La relation entre l’humanité et la nature implique-t-elle un rapport de domination ?","function":"Faire entendre le point de vue du vivant dominé","reason":"La couleuvre révèle le pouvoir humain de décider pour elle ; distinguer la capacité d’exploiter et la légitimité de cet usage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"},{"subject":"Avons-nous des devoirs envers la nature ?","function":"Interroger l’intérêt humain comme unique mesure","reason":"La contestation du reptile oblige à demander si notre utilité suffit à justifier le traitement d’autres vivants ; la personnification sert l’examen moral.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"}]},{"id":"la-fontaine-planter-pour-ceux-qui-viendront","code":"LF15","author":"La Fontaine","title":"Planter pour ceux qui viendront","work":"Le Vieillard et les trois jeunes Hommes","collection":"Fables choisies mises en vers","locator":"Livre XI, fable VIII · p. 309 (PDF p. 409)","quote":"Mes arrière-neveux me devront cet ombrage :","verse":true,"notions":["temps","devoir","bonheur"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Vieillard","situation":"Un octogénaire plante un arbre ; trois jeunes gens lui reprochent de travailler pour un avenir dont il ne jouira pas.","commentary":[{"function":"Le problème","sentence":"Une action perd-elle son sens si son auteur ne profite pas lui-même de ses fruits ?"},{"function":"L’affirmation","sentence":"Le vieillard justifie sa plantation par l’ombre dont bénéficieront les générations futures."},{"function":"Les concepts","sentence":"Ses « arrière-neveux » désignent ici la postérité, et non les seuls enfants de ses neveux."},{"function":"La raison","sentence":"Le bien visé peut dépasser la durée d’une vie sans cesser de donner un sens à l’action présente."},{"function":"L’exemple","sentence":"L’arbre planté aujourd’hui rend possible un repos futur pour des personnes que le planteur ne connaîtra pas."},{"function":"La portée","sentence":"Ce vers permet ainsi de penser la responsabilité envers l’avenir et une joie de contribuer, sans confondre toute prévoyance avec une obligation absolue."}],"uses":[{"subject":"Sommes-nous responsables de l’avenir ?","function":"Étendre l’horizon des destinataires de l’action","reason":"Le vieillard agit pour une postérité absente ; montrer que la responsabilité peut porter sur les conditions de vie laissées aux suivants.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Agir par devoir est-ce agir contre son intérêt ?","function":"Distinguer profit personnel et joie de contribuer","reason":"Le vieillard renonce au bénéfice direct de l’ombre mais trouve un fruit présent dans le bien d’autrui ; discuter l’opposition trop simple entre intérêt et devoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"}]},{"id":"la-fontaine-tailler-les-desirs-ou-detruire-la-vie","code":"LF16","author":"La Fontaine","title":"Tailler les désirs ou détruire la vie","work":"Le Philosophe scythe","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XX · p. 349 (PDF p. 459)","quote":"Ils ôtent à nos cœurs le principal ressort;\nIls font cesser de vivre avant que l’on soit mort.","verse":true,"notions":["raison","bonheur","liberte"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Un philosophe taille tous ses arbres sans discernement ; le narrateur y voit l’image de ceux qui veulent supprimer tous les désirs.","commentary":[{"function":"Le problème","sentence":"La maîtrise des passions exige-t-elle leur suppression complète ?"},{"function":"L’affirmation","sentence":"La Fontaine reproche à une discipline excessive de détruire les forces mêmes qui animent l’existence."},{"function":"Les concepts","sentence":"Le « ressort » désigne l’élan du désir, tandis que vivre ne signifie pas ici seulement conserver ses fonctions biologiques."},{"function":"La raison","sentence":"Retrancher indistinctement les désirs nuisibles et les souhaits innocents fait disparaître ce qui donnait un prix à l’action."},{"function":"L’exemple","sentence":"Le jardin ravagé par une taille aveugle figure cette vie appauvrie au nom de son amélioration."},{"function":"La portée","sentence":"Les vers critiquent donc un ascétisme sans discernement, représenté par un stoïcien excessif, et non toute la philosophie stoïcienne ni toute maîtrise de soi."}],"uses":[{"subject":"Être raisonnable, est-ce faire taire ses désirs ?","function":"Distinguer le discernement et la suppression indifférenciée","reason":"Le jardin détruit montre le coût d’une discipline qui confond tous les désirs ; examiner ceux qu’il faut régler et ceux qu’il faut cultiver.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Le bonheur consiste-t-il à ne plus rien désirer ?","function":"Contester un idéal de tranquillité obtenu par l’appauvrissement","reason":"Supprimer jusqu’aux souhaits innocents conserve une vie biologique mais en éteint l’élan ; distinguer la fin du trouble et la possibilité du bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}]},{"id":"la-fontaine-un-adieu-qui-ne-peut-plus-se-dire","code":"LF17","author":"La Fontaine","title":"Un adieu qui ne peut plus se dire","work":"Philémon et Baucis","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XXV · p. 360 (PDF p. 470)","quote":"L’un et l’autre se dit adieu de la pensée :\nLe corps n’est tantôt plus que feuillage et que bois.","verse":true,"notions":["langage","conscience","temps"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Philémon et Baucis, vieillards unis par l’amour, se transforment en arbres ; leur métamorphose empêche les paroles et les gestes d’adieu.","commentary":[{"function":"Le problème","sentence":"La disparition de la parole rend-elle toute pensée impossible ?"},{"function":"L’affirmation","sentence":"La Fontaine imagine deux êtres qui se disent intérieurement adieu lorsque leur corps ne peut plus parler."},{"function":"Les concepts","sentence":"La pensée de l’autre se distingue ici de son expression par des mots ou des gestes."},{"function":"La raison","sentence":"L’écorce qui gagne le corps empêche la manifestation de l’amour sans que le récit fasse aussitôt disparaître cet amour."},{"function":"L’exemple","sentence":"Philémon veut tendre les bras et parler à Baucis, mais leur transformation laisse seulement subsister l’adieu pensé."},{"function":"La portée","sentence":"Ces vers donnent ainsi une forme sensible à la distinction entre pensée et expression, sans prouver une communication effective des consciences sans langage."}],"uses":[{"subject":"Peut-on séparer penser et parler ?","function":"Distinguer la vie intérieure et son expression corporelle","reason":"La métamorphose figure une pensée qui subsiste quand la parole devient impossible ; utiliser la fiction pour préciser la distinction, non pour fournir une preuve.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Les mots peuvent-ils nous manquer pour dire quelque chose ?","function":"Montrer une expérience qui excède la possibilité de la dire","reason":"L’adieu reste présent à la pensée tandis que le corps ne peut plus le manifester ; interroger la perte que représente cette impossibilité d’expression.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}]},{"id":"la-fontaine-laisser-reposer-leau","code":"LF18","author":"La Fontaine","title":"Laisser reposer l’eau","work":"Le Juge arbitre, l’Hospitalier, et le Solitaire","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XXIX · p. 389 (PDF p. 501)","quote":"Mes Frères, dit le Saint, laissez-la reposer,\nVous verrez alors votre image.","verse":true,"notions":["conscience","temps"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Solitaire","situation":"À deux amis absorbés par leurs tâches, le solitaire montre une eau agitée qui ne peut refléter leur visage avant de s’apaiser.","commentary":[{"function":"Le problème","sentence":"L’agitation des activités permet-elle de se connaître soi-même ?"},{"function":"L’affirmation","sentence":"Le solitaire propose à ses amis de laisser reposer l’eau pour y retrouver leur image."},{"function":"Les concepts","sentence":"La surface troublée figure une attention dispersée qui ne distingue plus ce qu’elle cherche à observer."},{"function":"La raison","sentence":"Le retour à soi demande alors une interruption des sollicitations, comme le reflet exige que la vase cesse de masquer l’eau."},{"function":"L’exemple","sentence":"Les deux amis doivent attendre au lieu d’agiter davantage la source pour tenter de mieux s’y voir."},{"function":"La portée","sentence":"L’image invite donc à ménager un temps de réflexion, sans faire de l’abandon des devoirs envers autrui une règle générale."}],"uses":[{"subject":"Peut-on se connaître soi-même ?","function":"Décrire une condition d’attention à soi","reason":"Le reflet ne manque pas de miroir mais d’une eau calme ; examiner le rôle d’un recul temporaire dans l’examen de ses actes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"Faut-il toujours chercher à gagner du temps ?","function":"Montrer la fécondité d’une interruption","reason":"Attendre que l’eau repose rend possible ce qu’une activité accrue empêchait ; distinguer un temps perdu et un temps nécessaire à la compréhension.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"la-fontaine-le-temps-qui-rend-les-plaisirs","code":"LF19","author":"La Fontaine","title":"Le temps qui rend les plaisirs","work":"La Jeune Veuve","collection":"Fables choisies mises en vers","locator":"Livre VI, fable XXI · p. 170 (PDF p. 260)","quote":"Sur les ailes du Temps la tristesse s’envole;\nLe Temps ramène les plaisirs.","verse":true,"notions":["temps","bonheur","conscience"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Le narrateur annonce l’histoire d’une jeune veuve dont le chagrin se transforme progressivement et qui envisage une nouvelle union.","commentary":[{"function":"Le problème","sentence":"Le temps ne fait-il que nous retirer ce que nous aimons ?"},{"function":"L’affirmation","sentence":"La Fontaine lui attribue aussi le pouvoir de diminuer la tristesse et de rouvrir la possibilité des plaisirs."},{"function":"Les concepts","sentence":"La durée ne désigne donc pas seulement une succession de pertes, mais une transformation de notre manière de sentir."},{"function":"La raison","sentence":"Un état affectif qui semble occuper toute l’existence présente peut cesser d’en déterminer chaque moment."},{"function":"L’exemple","sentence":"Le récit montre ainsi une veuve passant du désespoir à la perspective d’une nouvelle union."},{"function":"La portée","sentence":"Ces vers invitent à penser une puissance réparatrice du temps, sans promettre que toute souffrance disparaît ni fixer une durée au deuil."}],"uses":[{"subject":"Le temps est-il nécessairement destructeur ?","function":"Opposer à la perte une transformation réparatrice","reason":"Le temps atténue ici la tristesse et rend les plaisirs possibles ; discuter une durée qui modifie la souffrance au lieu de seulement détruire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Sommes-nous condamnés à subir le temps ?","function":"Nuancer l’assimilation de toute passivité à un mal","reason":"Une transformation non entièrement voulue peut rouvrir la vie ; examiner ce qu’il faut accueillir autant que ce que l’on voudrait maîtriser.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"la-fontaine-entendre-ce-que-lon-soupconne","code":"LF20","author":"La Fontaine","title":"Entendre ce que l’on soupçonne","work":"Les Filles de Minée","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XXVIII · p. 380 (PDF p. 490)","quote":"Elle croit y trouver, non le sens qu’ils cachaient,\nMais celui seulement que ses soupçons cherchaient.","verse":true,"notions":["langage","verite","conscience"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Clymène","situation":"Clymène raconte Procris, qui prend l’appel de Céphale à la brise pour celui d’une rivale.","commentary":[{"function":"Le problème","sentence":"Comprendre une parole consiste-t-il à y retrouver ce que l’on attendait déjà ?"},{"function":"L’affirmation","sentence":"Clymène raconte comment Procris prête aux paroles de Céphale le sens que lui suggère sa jalousie."},{"function":"Les concepts","sentence":"L’interprétation se distingue ici d’une découverte lorsque le soupçon fournit d’avance la réponse recherchée."},{"function":"La raison","sentence":"La passion sélectionne ce qui paraît confirmer sa crainte au lieu d’examiner les autres significations possibles."},{"function":"L’exemple","sentence":"Céphale invoque la brise pour se rafraîchir, mais Procris entend l’appel d’une femme aimée."},{"function":"La portée","sentence":"Le récit invite donc à confronter une interprétation à ses raisons et à son contexte, sans conclure que toute compréhension serait impossible."}],"uses":[{"subject":"Suffirait-il de parler la même langue pour se comprendre ?","function":"Montrer un obstacle affectif à la compréhension","reason":"Procris connaît les mots mais leur donne un sens dicté par sa jalousie ; le partage de la langue ne garantit pas l’examen du contexte.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Toutes les interprétations se valent-elles ?","function":"Distinguer l’interprétation étayée et la confirmation d’un soupçon","reason":"La lecture jalouse néglige la situation de Céphale ; comparer les interprétations par leurs raisons plutôt que par la seule conviction de celui qui les défend.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=77","sourceLabel":"Recueil académique · p. 77"}]}]};
